/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020702-7","meetingId":"h14-cm07","date":"2002年7月2日","dateIso":"2002-07-02","committee":"厚生委員会","time":"午前１０時０７分～午後４時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を106件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"初めに、このパンフレットが発行されたのが６月だと思うんですけれども、普通流れから言って、発行される前に委員会とかに出てくると思うんですが、何で７月に入ってからの今の委員会で報告になったのか。","respondent":"日下部障害者福祉課長","answer":"発行は確かに６月というふうになっておりますが、実はこれについて公表しますのは、今回の委員会が初めてです。今日委員会で公表をさせていただきまして、その上で、各関係のところにもこのあらましについてご配布をする、そういうことで考えております。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"活用方法としてお伺いしたいんですけれども、ここにきれいなパンフレット化をしてありますが、このようにパンフレット化する必要があったのかということと、文責というもので、支援費制度とか、地域福祉計画にどのようにこのアンケート結果を反映させていくのか。","respondent":"日下部障害者福祉課長","answer":"先ほどございました、最後に区に対する障害者施策の希望ということで、障害者に対する理解の啓発ということがございましたけれども、支援費制度への移行を契機として区民の皆さんにさらに一層障害者福祉への理解を深めていただくということも重要なことですから。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"木造アパートですから、いずれ大家が建て替え等のことが出てくると思うんですけれども、８.９％というのは、どのぐらいの人数なのか。いずれ大家が建て替えるときに立ち退き等のいろいろな問題が出てくると思うんですけれども、そのときの対処というのは、どのように考えているんでしょうか。","respondent":"日下部障害者福祉課長","answer":"住み替えの家賃の助成の制度も、いろいろ制度も改革の方向にありますけれども、現にそういう受け皿を持っておりますし、そういったいろいろな施策を活用して対応をしていきたい、このように考えております。","id":"exchange-003"},{"speaker":"金高委員","kind":"質問","question":"せっかくこれだけの方々にアンケートを送って、それを政策に反映させるということが一番の大きな効果だと思うんですけれども、５８.１％、もうちょっと回収率が７５％とか、そういうふうに高くなってしかるべきじゃないかという気がしたんですけれども、平成３年のときと比較してどうかなという、その１点だけお伺いしたいんです。","respondent":"日下部障害者福祉課長","answer":"設問の数も前回に比べまして結構多かったんです。ですから、そういったことで、回答するにしても、かなり大変だったものですから、その辺が回収率が前回ほどにはならなかった。そういう原因だということで理解をしております。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"というのは、１０ページには、介助者のほうは１０歳で区切って非常に細かく報告してあるんだけれども、実態のほうを逆に大ざっぱにしてきているので、本来は逆だろうと思うので、こっちが主になって、そして我々もこういう状況であるといって、いろいろなことを分析したいと思うんだけれども、数字が非常に大ざっぱな数字で統計が出されているんだけれども、この辺は介助者と同じ、回答者の分布というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"何点か伺います。私もちょっと聞き漏らしたのかと思うんですが、７ページの、今後の就労意向のところで、生活費が欲しいということで、４０.８％あるんですけれども、前回はどんなものだったのか、お聞かせいただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"前回の割合が３５.６％です。ですから、今回は約５％ほど数値が上昇しているということです。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問・要望","question":"かなり高くなってきているというふうに思いますけれども、このところで、障害者の方々の収入が、こちらのほうの説明は私も聞いていたんですけれども、自分で得た収入が、前回は３０.３％だったのが、今回は２４.６％と。自分で自立してやっていきたいという願いが、ここから浮き彫りになってくるように思うんです。この願いに対してどういうふうにお考えなのかをお聞かせいただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"ですから、雇用情勢の問題というのは、そう簡単に一自治体のレベルでというのは難しいわけですが、区は区としてこれまでも努力をしてきておりますので、今後ともその辺の取り組みをしっかりやっていきたい、このように考えます。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"参考に聞きたいんですけれども、作業所と、希望している方の数と、実際の定員はどういうふうにお考えでしょうか。","respondent":"日下部障害者福祉課長","answer":"先ほどご説明の中でも申し上げました。区の場合は養護学校の卒後対策も含めて、基本的に全員受け入れということで今まで取り組んできております。その結果、トータルで今４３０名ほどの通所、授産施設の定員を確保しています。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほどアパートの件で質問があったんですけれども、それと関連して聞きたいんですけれども、木賃アパートが減ってきているということでしたけれども、私の知り合いも立ち退きで区外に転出されましたけれども、転出して、減ってきているというのもかなりあろうかと思うんですけれども、一方で、品川区に住んでいたいというふうな声もかなり多いということですけれども、ここら辺の、前回との比較で。","respondent":"日下部障害者福祉課長","answer":"公営住宅に転居をされる方もいらっしゃるでしょうし、区のほうでもそういう住宅をつくっているわけですから、そういう形で区内での住み替えをされている方もいらっしゃいますから、すべてが区外転出に結びついているというふうには考えておりません。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"それは住宅マスタープランのほうですけれども、同じ傾向というのがここに出ているのではないかなというふうに、ここのところは、今具体的な数字というのはないということでありますから、そういうところであまり云々してもしようがないのかもしれませんけれども、今後はそういうところもぜひつかんでいただくような工夫をしていただければというふうに思いますけれども、どうでしょうか。","respondent":"日下部障害者福祉課長","answer":"確かに全体の一つの傾向の問題とか、いろいろありますので、私どもとしてはもう少しその辺の転出なり転入の状況についてはしっかりと把握するようにいたしますけれども、いずれにしろ、これだけ定住意向が強いわけですから、区としても最大限努力をしていきたいと思います。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。もう一つ質問ですけれども、１０ページの、主な介助者のところですけれども、ちょっと聞き漏らしちゃったんですけれども、特に多い父母、配偶者、子、このところの前回のところと、併せてホームヘルパー、ボランティアの前回比をお知らせいただければと思います。","respondent":"日下部障害者福祉課長","answer":"具体的に申し上げます。父母につきましては、前回２０.９％です。配偶者が３４.９％、子どもが１５.８％です。ホームヘルパーにつきましては１.９％です。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"高齢者のほうは介護保険で社会的に介護を負担しようというふうになっているんですけれども、同じ方向に向いてはいると思うんですけれども、数字から見ると、家族介助のほうにかなり、社会的に介助しようという方向へ向いていると思うんだけれども、前に向きながらもうしろに下がっているみたいな、そんな感じがするんですけれども、ここのところは区のほうはどういうふうにお考えでしょうか。","respondent":"日下部障害者福祉課長","answer":"ただ、一方で、それだけですと大変ですから、ホームヘルパーについてもきちんと派遣をして、全体の連携と協力の中で在宅での生活を支えていくということを基本に進めておりますので、その辺については今後そういう考え方を基調として進めていきたい、このように考えております。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"介護保険と比べて状況が前に向きながらも実際はうしろに下がっているみたいな印象が強いものですから、ここのところは特に親亡き後の施設等、親のところは非常に心配しておりますし、公的サービスを強く望んでおりますので、ぜひここのところは頑張っていただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"築舘委員","kind":"質問","question":"これだけではわからないということでしたら、それはそれでいいんですけれども、もし今度やるんだったら、○とか×を付けるのはもちろんいいんですけれども、何か書く欄を設けるとか、少し内容が詳しく分かるようなもののアンケートもしてみていただければという感じをちょっと持ったものですから、それを含めてお答えをお願いします。","respondent":"日下部障害者福祉課長","answer":"ここでもそうなんですが、専門の理学療法士を中心にいたしまして、作業療法士とか、あるいはそのほかの専門家も入りますけれども、機能回復に向けてそれぞれの障害の特性に応じた形で適切な機能訓練を進めているという状況です。","id":"exchange-014"},{"speaker":"山路委員","kind":"質問","question":"これも実際に歩行・外出を毎日のこととしている人は多いと思うんですけれども、その次、主な介助者の交代者という中で、「何もあてがなく困っている」というところが７.９％になっておりますけれども、それぞれの障害に応じてのも出ましたけれども、細かい実態調査をしていらっしゃるとは思うんですけれども、何人ぐらいいらっしゃるのか、ちょっと教えていただけますでしょうか。","respondent":"日下部障害者福祉課長","answer":"これが障害者全体の人数に換算いたしますと２５０人程度にのぼるのではないか、このように計算は出てまいります。","id":"exchange-015"},{"speaker":"山路委員","kind":"質問","question":"昨日も辻委員と宮崎委員のほうからペットの関連で、１０月から介助犬の補助法が施行されるということで、介助犬は生活に必要な大事な存在になってくると思うんです。盲導犬は今までにもいろいろありましたね。そういう対象者は何人ぐらいいらっしゃるか、あるいは１０月から施行されるわけですけれども、区民にどういうふうに周知するか考えていらっしゃるか、お伺いいたします。","respondent":"日下部障害者福祉課長","answer":"そのうち一、二級の重度の方が３分の１を占めるですので、聴導犬ということになれば、その対象者は、一、二級の重度の方の２７０名程度の方が対象になるのではないかというふうに見込んでいるところです。","id":"exchange-016"},{"speaker":"山路委員","kind":"質問","question":"全国的には法律が施行されますので、補助金で訓練もどんどん増えていくと思うんですけれども、品川区に２７０名の対象者の方がいて、本当に必要な方が果たして聴導犬を実際にお借りして生活を共にすることができるかどうか、その辺の実態はどのような見通しを立てていらっしゃるか、お伺いいたします。","respondent":"日下部障害者福祉課長","answer":"そういった意味では、これからどういう形で聴導犬の活用を図っていったらいいのか、私どもとしてもまだそういうことでは実態についてよくわかっていないところがありますので、その辺はこれからしっかりと勉強をしまして、そういう要望等があれば。","id":"exchange-017"},{"speaker":"山路委員","kind":"質問・要望","question":"この実態調査に戻るんですけれども、何もあてがなく困っているという方が、国の補助、また品川区でも、今はありませんけれども、これから最優先に手を挙げていただいて、品川区にお住まいの方に盲導犬、介助犬、聴導犬の、今訓練をしている最中でしょうけれども、一人でも多くの方が一緒に生活できて、何もあてがなく困っているという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問","question":"裏ページのほうの、給付金で、今まで都が払った４分の１が、今度区の負担になるということだけれども、この分については、財調とか、そういうので面倒を見るようになるのか、まるっきり区自体が一般会計から出すという仕組みになるのか、その辺を教えてください。","respondent":"辻田児童課長","answer":"この辺確かめましたところ、都のほうで財調算定の中で見ていくということで考えているという具合に聞いております。","id":"exchange-019"},{"speaker":"藤原委員","kind":"意見","question":"減る方が４０％というお話をしたんですが、ここがちょっとわからないんですけれども、総収入の増加につながるよう改正しているのに、減る方が４０％も出てしまうのかなと思いまして。","respondent":"辻田児童課長","answer":"総収入の増加につながるというのは、先ほどこの表をもって説明いたしましたときに、あるところにいくとガタンと落ちてしまう、そういうような状況の中で、それぞれの方がその近辺にきますと、自ら収入を調整してしまうというような形で、そういうことがないような形。","id":"exchange-020"},{"speaker":"藤原委員","kind":"意見","question":"４０％の人は結果的には減ってしまうわけですよね。なだらかにする結果によって、ぎりぎりの線の人はそこで収入のいろいろな操作をしてしまうから、そういうふうにしなくても、なだらかにすることによって、操作しなくても、働いていてももらえますよということですね。だから、もっと自立して、どんどんご自分でかせぎなさいということも促すという意味ですよね。","respondent":"辻田児童課長","answer":"委員おっしゃるとおりです。基本的には今までは大きな変更があったわけですけれども、この線で分かりますように、減る金額につきましては、この線によってかなりなだらかになっている。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"最後に１つ質問なんですが、減る人も、増える人もいて、予算的には増減はないということでしょうか。","respondent":"辻田児童課長","answer":"金額につきましては、今までは約７億円ぐらいの年間事業経費でございました。この中で少し減ってまいりますけれども、そういうような中で減った部分を換算しますと、年間で４,０００万円ぐらい減るのではないかという試算をしております。","id":"exchange-022"},{"speaker":"金高委員","kind":"質問・要望","question":"説明の中で、4)に特例児童扶養資金の創設がありますけれども、８月以降に受給する児童扶養手当の額が減額となる者に差額を貸し付けるとなっておりますけれども、これは貸付金という形になると思うんですが、貸し付けるとなりますと、金利を取るとか、あるいは幾らまで、差額でしょうけれども、人によってそれぞれ違うと思いますけれども、どのぐらいの形になるか、それを教えていただきたいと思います。","respondent":"辻田児童課長","answer":"これにつきましては無利子になるというような形で説明を受けております。","id":"exchange-023"},{"speaker":"金高委員","kind":"質問","question":"無利子というのは分かりました。借りるわけですから、いずれ貸付金を返さなければいけないという形になりますけれども、その辺の猶予とか、あるいは期間とか、その辺も含めてお願いいたします。","respondent":"辻田児童課長","answer":"激変緩和の措置ですので、この辺は十分考えられておりまして、扶養手当をもらって、それでお金を借りても、なおかつ生活状況がなかなか改善していかないというような状況の中では、一定条件のもとに貸付金の減免を行うとか、長い期間で返済する方法をとるなど。","id":"exchange-024"},{"speaker":"金高委員","kind":"質問","question":"例えば今の説明ですと、個々によって違うわけですから、それぞれの方々に対しての差額に関して貸し付けた金額が戻ってくるということについては、普通ですと、期間とか、そういうのが組まれるわけですけれども、今のご説明ですと、そういうことでないというようなニュアンスに受け取ったんですけれども、いわゆる人によってそれぞれ違うわけですから、それは考慮しながら返していただくという形でしょうか。","respondent":"辻田児童課長","answer":"この制度につきましては、母子福祉資金貸付金制度の中で行われますので、一定の条件が当然示されてくるということで、まだ正式な形で私どものほうにきておりませんので、その辺につきましては、通知があり次第皆さんのほうに周知していくという具合に考えております。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺います。たしか国のほうは３６０億円ぐらい減っていたかなと思うんです。先ほどの説明でも、従来とほぼ同じだというのは５６％ぐらいで、減が４０％弱だというふうな説明だったんですが、別表のところでは、若干増えるところもあるんだという説明なんですが、そうすると、従来が５６％で、減が４０％弱、増えるところは４％ぐらいの人だということなんですか。","respondent":"辻田児童課長","answer":"委員ご指摘のとおり、増える方については５％ぐらいを見ているです。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"４０％の人が減って、５％の人が増える。実際にこれでもなだらかというのとは実態が全然違うというふうに思うんです。細かいことで聞きたいんですけれども、所得範囲の見直しのところで、養育費として受ける金品等というのは、もうちょっと詳しく、どういうのが入っているか。それと、どういうふうに認定するのかということは、どんなものでしょうか。","respondent":"辻田児童課長","answer":"養育費としての金品の範囲というのが、一般生活用の通念的なもので決まってくると思うんですけれども、例えば一時的なお小遣いとか、そういうようなものは多分入ってこないだろうということで説明を受けております。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"例えば離婚するときに、慰謝料を払うとか、養育費としてこれだけ払うよというふうな約束をしても、これが約束どおりやられていないケースというのはかなりありまして、それで相談に来るケースなどもあるんですけれども、ここら辺のところは、詳しいのはこれからになるわけですか。ぜひここのところは状況をよくつかんでいただければというふうに思います。","respondent":"辻田児童課長","answer":"そういうようなことをするとともに、いろいろな形での取り決めなどを促進して、ガイドラインを作成したり何かして、これからは民事執行制度の強化というようなことも含めて、今後は制度をきちっと整備していくということで伺っております。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"今の説明だと、例えば別れたご主人が約束を履行しないということになると、法的な手段も含めて対応するんだということですか。","respondent":"辻田児童課長","answer":"これは法的な裏付けも最終的な形としてはありますよということで、何もそれをどんどん促進していくということではないですけれども、そのために最後に付け加えた形で説明をさせていただいたわけです。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"しつこいようですけれども、ここのところはこれから法整備をしていくということですか。それとも今の範囲でということになると、例えばだれが訴えるんだということなどはどういうふうになるんでしょうか。","respondent":"辻田児童課長、小沼福祉事業部長","answer":"これにつきましては、今説明しましたのは、８月から施行される分です。平成１５年４月から、母子自立の支援のための各施策が出てまいります。いろいろなご意見があることは事実ですけれども、もろもろ上がっているものを今児童課長のほうから、検討されている例としてご説明したということでご理解いただければと思います。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"今検討中ということですけれども、今話が出ましたので、感想を言いますと、そこまで代わりに請求するとか、こんな話が通るのかという、そんな感想を持ちました。次に聞きたいんですけれども、手当の支払い期日ですけれども、８月からは手当の実際の支払いが８月分から１１月分の４カ月をまとめて１２月に払われると言っていたんですけれども、今まではどういうふうな支払いの形態だったでしょうか。","respondent":"辻田児童課長","answer":"支払いの期日につきましては、従来も変わっておりません。４月、８月、１２月、この３期にそれぞれ前月分まで支払うということで実施してきております。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、２の支払いの期日のところは全く変更はないということですか。","respondent":"辻田児童課長","answer":"この部分が改正されたということではございません。流れの中で、一つの手当の支給が、１２月にもらう部分で変更が起きてきますよです。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"分かりました。変更があったのかと思って、質問をしたんです。その上の4)番のところですけれども、激変緩和で、資金の創設ということですけれども、今時点で利用するだろうという見込みとか、利用するとすると、大体１人当たりこのぐらい利用されるとか、そこら辺の見通しはどんなふうに見ておられますか。","respondent":"辻田児童課長","answer":"この辺の手続とか、いろいろなものが私どものほうにまだ示されておりませんので、そこら辺の見込み等もまだ立てている状況ではございません。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問","question":"なかなかかみ合わないなと思うんですけれども、最後に１点聞きたいんですけれども、今の児童扶養手当を支給している対象のところについて、現在のところを聞きたいんですけれども、受けている方々のところでは、子どもの人数が平均何人ぐらいなのかというのと、子どもたちの年齢の平均、そこら辺のところはどんな感じですか。","respondent":"辻田児童課長","answer":"ただ、そのほかにお母さんと、お子さんが３人いるということになりますと、児童扶養手当のほかに、２人目は５,０００円、３人目は３,０００円ということで、あとは１人ずつ増えるごとに３,０００円支給されるということになりますので、その家庭ですと。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"私が聞いたのは、今時点で児童扶養手当がどういうふうに支給されているのか。世帯数と、子どもの人数、年齢、そこら辺の平均のところでも分かりましたら、お願いしたいと思います。","respondent":"辻田児童課長","answer":"一般的にどういう形の人数になっているかといいますと、２人家庭が一番多い状況です。私どものほうで平成１４年度を試算しているところでは、大体基本的な数ですけれども、２人の生活をしているというお宅につきましては、大体１,５００世帯弱ぐらいです。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"意見","question":"先ほどちょっと感想を言ったんですけれども、今リストラが嵐のように吹き荒れている中で、自立でやってほしいと、そういう方向なんだということですけれども、この前もまだ若いお母さんなんですけれども、男の人と同じような仕事の時間なんですよね。こういう中にほうり込まれていったら、逆に、子どもたちとのふれあいの時間がどうなっていくんだろうなというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"今日ご報告していただいた結果は概況になっているんですけれども、今後、今日の１番目のご報告みたいな、障害児の調査のあらましみたいな形で、このようなパンフレットみたいにして、この委員会には報告されるんでしょうか。","respondent":"金子保育課長","answer":"私どもでは、先ほどの実態調査のようなパンフレットは特に作成する予定はございませんが、先ほど申しましたとおり、それぞれの園で改善活動をしていきます。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"一つ、アンケートの方法でもったいなと思ったところが、最後のページの、問４のところで、「入園・保育園運営方針について、どのように感じていらっしゃいますか」というので、「大変満足」から「大変不満」というふうになっているんですけれども、その中において、「不満」、「大変不満」と○をした人は、具体的にどのようなことがというような設問があってもいいと思ったんですけれども。","respondent":"金子保育課長","answer":"今回の設問の構造が、先ほど申し上げたとおり、東京都のほうで基本的なパターンを設定しておりまして、中間のカテゴリーごとに個々に満足度は記すようになっておりますが、そこの部分で自由意見というのはありません。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"例えば問１４で、「要望・意見、いやな思いへの対応について、おうかがいします」で、「１年以内である」と○をした方はどんな内容か、具体的にというような設問があるんですけれども、この辺が生の声ですばらしいと思います。ぜひこういう意見を取り上げて、今後の改善に役立てていってもらいたと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"金高委員","kind":"質問","question":"この辺をこれからのアクション・プランシートでそれぞれの職員の方とともに、６月から１月にかけてそれぞれサービス向上計画の進め方ということで、職員の方々との話し合いになると思うんですけれども、この辺を踏まえて、差があることの感想、それを公立であろうと、私立であろうと、保育問題、子どもに対する愛情のかけ方ですから、それをどのように縮めるための努力をするかという。","respondent":"金子保育課長","answer":"そういった部分がある意味で公立は使いにくいというような評価につながっている可能性が高いというふうに考えております。一つの例ですけれども、それがいろいろな場面であるのではないかなというふうに考えております。","id":"exchange-040"},{"speaker":"金高委員","kind":"質問・要望","question":"確かに公立と私立の違いというのは、一つには、規則とか、そういったところに縛られるところが多々あると思いますけれども、やはり人が人を育てる、あるいは人が人とお互いに向き合ったときに、どのような形でもって行き合えるかということが一番大事だと思いますので、ぜひ職員の方々も、できる、できないは、そのときの状況によって大きく違うと思いますけれども、公立を利用している父兄の方も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"築舘委員","kind":"質問","question":"回収ですけれども、平成１２年度と平成１３年度が、平成１２年度のほうが率が良くて、平成１３年度のほうが悪いということですけれども、質問の内容が同じ質問だったのかどうか。その辺の状況というのがしっかりと指導ができていたのかどうかという、さっきの理由ではもう一つ納得がいかないんですが、そこをお聞かせください。","respondent":"金子保育課長","answer":"回収率については、前年度は記録してありませんけれども、今年度は６０％程度だというふうに聞いておりますので、私どもとしては努力はしなければいけないとは思っておりますけれども、一定改善する方向にある数字だとは認識しております。","id":"exchange-042"},{"speaker":"築舘委員","kind":"質問・要望","question":"例えばあったとしたら、それはちょっとおかしいわけで、そういうことへの指導をしっかりとしているのかどうかというのを、さっき質問をしたんですけれども、お答えいただきたい。「要望・意見・いやな思いへの対応について」ということで、さっきもちょっと出ましたけれども、そのところで「内容はどんなものでしたか。具体的にお書きください。","respondent":"金子保育課長","answer":"要望や不満についてのきちっと分析しろということですけれども、私どもとしても、この部分についてはきちっと分析して対応をしていきたいと考えています。","id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ほかの委員からもあったかと思うんですけれども、ここが大事ですから、自由に書くところを全部というわけにはいかないと思うんですけれども、数字で出せるところはきちっと出していただきたいのと、意見のところも、例えば多い順番に、上位１０位とか、そんな感じで出していただいて、ぜひ見せていただきたいなと思うんですけれども、そこのところはどうでしょうか。","respondent":"金子保育課長","answer":"その部分については公開できないものもあると思いますけれども、基本的には公開対象と考えておりますので、ご理解いただければと思います。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"質問・要望","question":"公開対象ということであれば、厚生委員会のところには出していただけないのかなと思うので、そこのところをお願いしたいと思います。そこのところはここには出ていないものですから、ぜひ全体が分かるようにしていただきたいと思います。それと、これは以前調査したものとの比較みたいなものというのはできるんでしょうか。","respondent":"金子保育課長","answer":"なおかつ、１年前と比較できるのは、４４園ではなくて、１４園ですので、今回はお示しするのは省かせていただきました。","id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"もう一つ、保育全体でどういうふうに見られているかというところですから、これが経年的にどういうふうな評価の変化があるのか、これは経年的にも見たいと思いますので、全く技術的にできない、不可能だということであれば、これは別問題ですけれども、可能であれば、そういうことをつかんで、全体が分かるように努力していただけないかなと思うんですが、そこのところはどうでしょうか。","respondent":"金子保育課長","answer":"ご指摘の部分、私どものほうでも当然理解できるところですので、その部分については明らかにしていきたいと考えています。","id":"exchange-046"},{"speaker":"須藤委員","kind":"質問","question":"そのことが回収率が低かったことに対して、保護者のほうの回答が少ないというようなご答弁が先ほどあったんだけれども、その辺の関係はどうなっているのか。それと、少ない園との関係は、そういうものがどういうふうにつながっているのか教えてください。","respondent":"金子保育課長","answer":"先ほどちょっと申し上げました、同じ時期にある運動団体が調査を実施していたということですけれども、そちらのほうの調査結果を私は目にしていませんので、どのような規模で、どの園でやられたかということは一切承知しておりません。","id":"exchange-047"},{"speaker":"須藤委員","kind":"質問","question":"そういう団体が個々に勝手にできるよというと、今度は逆に、プライバシーの問題、住所とかそういうのが勝手に分かっているというのが、その辺がどういうふうにアンケート自体のとらせ方というか、そういうものを園として承知してやっていたのかどうかという問題もあると思うんです。その辺いかがでしょうか。","respondent":"金子保育課長","answer":"これについては、外部につきましても、また、区の別のセクションにつきましても、保育課のほうを必ず通すようにということで指示しておりますので、園長、つまり組織を通してそのような外部の運動団体がしたアンケートに関与しているというふうなことは考えておりません。","id":"exchange-048"},{"speaker":"須藤委員","kind":"質問","question":"もっと言えば、そういうアンケート自体が園長が直接知らない、あるいは指示しなくても勝手にそういうことができてしまう状況にあるならば、これは由々しき問題だろうと思うんです。ですから、しっかりその辺は、どういう状況であるのか、そして、そこに対して今後どういう処置をしていったのかという問題のほうが私は大きいと思うんですけれども、いかがでしょうか。","respondent":"金子保育課長","answer":"先ほどの説明が言葉が足りなかったのかもしれませんが、私どもとしては、園長には、そういう場合には必ず報告しろと言っておりますので、園長ないしは保育園の職員、保育士に限らず、職員が園の中で係わっていることは一切ないというふうに信じておりますけれども、保育園の外で。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問","question":"今の委員の質問の中で、そういうところでは細かいところは把握していないというふうな説明だったんですけれども、最初のそういうふうな評価が、何で影響したんだというふうに言えるのか、そこのところが、調査していない、つかんでいないというのに、最初の説明では、影響したというふうに言っているんですけれども、何でそういうふうに言えたのか。","respondent":"金子保育課長","answer":"先ほど３点挙げましたけれども、確かに委員おっしゃられるとおり、そのうちの1点が、同じ時期に、項目の内容はわからないんですけれども、趣旨から言って、同じような利用者の保育の中身に対する調査だというふうに思えましたので、そういう意味では、保護者の方からすれば。","id":"exchange-050"}]},{"id":"topic-02","title":"(4) 品川区保育園映像配信サービス","agenda":"(4) 品川区保育園映像配信サービス","exchanges":[{"speaker":"山路委員","kind":"質問・要望","question":"昨年私も、働くお母さんから、子どもたちが保育園でどういう状況で遊んでいるのか知りたいという、テレビのニュースでいろいろなことがあるたびに相談を受けていたわけです。そして、その映像は１秒間に２コマという説明がありました。これは今盛んにはやっておりますＡＤＳＬとか、超高速大容量とか、こういう方式なんでしょうか。その辺について教えていただきたいと思います。","respondent":"金子保育課長","answer":"ですが、先ほども申し上げましたとおり、いろいろなイベント、あるいはいろいろな年齢の方、録画を撮って、別の時間帯に流すことということで、サービス内容については拡大していく方向で検討をしていきたいというふうに考えております。","id":"exchange-051"},{"speaker":"山路委員","kind":"質問・要望","question":"１２時半から１時までですけれども、スタートはこういう形でスタートされる。ですから、１秒でも早く映像にして、お母さんたちに見ていただくという努力もお願いしたいと思うんですけれども、不可能ではないですよね。超高速にＮＴＴの配線を使ってやっていただくというのは。その辺も今後検討をしていただきたいと思いますが、どういうふうにお考えでしょうか。","respondent":"金子保育課長","answer":"大変申し訳ないんですけれども、私も通信回線についてはあまり詳しくないものですから、そういう意味では、サービスをきちっと充実した内容で提供できるように、中身のことについても、また、通信回線等もいろいろ検討を加えて、充実させていきたいというふうに考えております。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問","question":"１点お伺いしますが、利用料としての月額５００円というのは、この額はどのようなことで決めたんでしょうか。","respondent":"金子保育課長","answer":"主には通信回線料になるんですけれども、これを利用者数をある程度想定しまして、カウントして、きりのいい数字ということで、５００円というふうな設定にしています。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"質問","question":"１点だけ伺いたいんですけれども、先ほど不正に使用されたときには、どこから出たのかということをつかむという話だったんですけれども、利用についての制限というのはどういうふうなことでかけられておりますか。","respondent":"金子保育課長","answer":"利用の制限ということですけれども、私どもとしては、この映像は、先ほど申し上げました目的のとおり、親子の緊密化、親密化のために提供しているものですので、両親、あるいは親族の方の間で、そういったことの目的のためにお使いいただくというふうに考えておりますので。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問","question":"情報が一旦出ると、それを規制するというのは難しいというのが一つあろうかと思います。そうなると、例えば今の説明だと、そういうところをどういうふうにして制約するのかなというのが非常に疑問なんですけれども、逆に、そういうことも含め、想定した内容にしていくというのが現実的なような気もするんですけれども、どうでしょうか。","respondent":"金子保育課長","answer":"ですので、それにつきましては、申請される段階で、こういうふうなことであるというお約束のことをすべて申請書の中に書いて、徹底するようにしておりますので、その点については現在のところ認めるということは考えておりません。","id":"exchange-055"}]},{"id":"topic-03","title":"５精神障害者訪問介護事業","agenda":"５精神障害者訪問介護事業","exchanges":[{"speaker":"金高委員","kind":"質問・要望","question":"３番目の、利用者の要件に、日常生活を営む上で支障がある者、精神障害の方というのは非常に分かりにくいところがあるんですけれども、どういう形の日常生活に支障があるか、その辺のところの事例がありましたら、教えていただきたいんです。","respondent":"田中健康課長","answer":"私どもモデル実施ということで、４月以来カンファレンスという形で保健所等々からの報告を受けまして、相談をしてまいりました。今回９名の派遣をする方にも一番多いところなんですが、ご自分の身の周りの整理ができないという方が、内容としては一番多い内容です。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"意見","question":"モデル実施ですけれども、今時点１人当たりで週何時間とか、どういう利用をされているか。それと、今は買い物とか、お話があったんですけれども、その中身と、そこら辺のところをお願いします。","respondent":"田中健康課長","answer":"買い物等が含まれている方もありますし、場合によっては、かなり期間をおいて行くという方もあります。週に１時間から、２週間に一遍ぐらいというのが多うあります。","id":"exchange-057"},{"speaker":"山路委員","kind":"質問・要望","question":"新聞でこの頃Ｃ型肝炎の増加のことがよく載っておりまして、国による対策、品川区でも肝炎検査実施ということで、区民にとっても非常に大事なことだと思うんですけれども、今日は保健所長も、医師も見えておりますのでお伺いしますけれども、Ｃ型肝炎、Ｂ型肝炎の原因というのはどういうことで、一部新聞で言われておりますけれども。","respondent":"小林品川区保健所保健サービス課長","answer":"一般的に国のほうで言われておりますのは、Ｃ型肝炎の感染者は全国的に１％から２％ぐらいじゃないか、１００万人から２００万人程度いらっしゃるのではないかというふうに言われております。","id":"exchange-058"},{"speaker":"山路委員","kind":"質問・要望","question":"分かりやすく聞かせていただきましたけれども、２番のＡＬＴのところですね、３６から４５までを要医療ということです。ここで、区民から見て自覚症状というのはどういうことがあるのか、分かる範囲で教えていたただけますでしょうか。そういう患者が今後出る可能性がある、この辺について教えていただきたいと思います。","respondent":"小林品川区保健所保健サービス課長","answer":"受けた方のそのくらいが見込まれるかなというふうに考えております。ただ、年齢的に高い方のほうが感染の率が高いというふうに言われておりますので、受診者がどのぐらいになるかわかりませんけれども、そういったことで数値が出てくるかと思います。","id":"exchange-059"},{"speaker":"山路委員","kind":"質問","question":"予想としては２％を見込まれるという、社会的にも非常に重要な問題だと思うんですけれども、先ほどＣ型肝炎の輸血による注射針ということでしたが、今は消毒をしていますよね。何年ぐらいに手術をしたとか、そこら辺まで分かっているものなんでしょうか。何年から何年までの間に輸血をした方とか、注射針を使った方とか、可能性があるとか、そういうところまでは分かっているんでしょうか。","respondent":"小林品川区保健所保健サービス課長","answer":"それよりもさらに進んだ検査方法ということで、平成９年に拡散増幅検査という、ウイルスそのものを見る検査ということになっていますので、完全に輸血によってＣ型肝炎の感染がなくなったというのは平成９年以降というふうに考えられると思います。","id":"exchange-060"},{"speaker":"山路委員","kind":"質問・要望","question":"私の知り合いに、本人はＣ型肝炎で生死をさまようところで入院して、よくなって、今は元気になられているんですが、いつ出るかわからないという心配を本人もしているところですけれども、そういう方に対するアドバイスがありましたら、ここでお知らせをしていただきたいと思います。","respondent":"小林品川区保健所保健サービス課長","answer":"Ｃ型肝炎を治療されて、今回復されている方へのアドバイスですけれども、その方がどの程度回復されたかはわかりませんけれども、肝炎から肝硬変、肝硬変から肝がんに進むという可能性がありますので、やはり定期的なチェックをきちっと行っていただきたいということと。","id":"exchange-061"},{"speaker":"築舘委員","kind":"質問・要望","question":"肝炎ということで、慢性肝炎、あと肝硬変というのがあるんですけれども、これは特殊疾病ということの医療費公費の負担等のところで、都の助成対象であったのが、平成１４年９月３０日をもって終了すると書いてあるんですけれども、この辺の原因といいますか、どうして終了するようになって、これからＣ型肝炎なり何なりがどんどんある意味では増えるような傾向がある中で、助成対象であったのが。","respondent":"小林品川区保健所保健サービス課長","answer":"ただいまの委員のご指摘の点につきましては、前回の厚生委員会でも、障害者福祉課長および私のほうからご説明をしていますけれども、Ｃ型肝炎、慢性肝炎、肝硬変の疾病につきましては難病ではないという考え方になってきております。","id":"exchange-062"},{"speaker":"築舘委員","kind":"質問","question":"その説明のときに私も聞いていなかったもので、申し訳ありませんでした。そういう意味では、ウイルスだということで、原因がはっきりしてきたということで、これは原因があるということで、また同時に、治っていくということでもあるんでしょうか。","respondent":"小林品川区保健所保健サービス課長","answer":"全員が回復されるわけではなくて、ウイルスのタイプとか、その人の個人的な体質とかによって左右されますけれども、いずれにしても、慢性肝炎を早く診断して、早く治療をすれば、回復する可能性が高いということで、今回のような肝炎検診を導入されたものと考えております。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"意見","question":"肝炎検診が追加ということで、前進したなと思います。内容のところを聞いておきたいんですけれども、今までの区民健診の肝炎のほうの検査の内容と、今度新しいのは内容がどういうふうに変わるか、そこのところをお聞かせいただければと思います。","respondent":"小林品川区保健所保健サービス課長","answer":"ＧＯＴ、ＧＰＴが異常のあった方について精密検診に行っていただくという流れでございました。今回は、先ほど説明のあった対象者に対して、最初からＣ型、Ｂ型の肝炎の検査を一緒に合わせて行えるということで、項目が加わったものです。","id":"exchange-064"},{"speaker":"宮崎委員","kind":"質問","question":"Ｃ型、Ｂ型が加わったのは知っているんですけれども、内容は何ですかということをお聞きしたんです。","respondent":"小林品川区保健所保健サービス課長","answer":"Ｃ型肝炎のＨＢＣ抗体につきましては、それが陽性だからといって、すぐウイルスそのものがいるとは限りませんので、陽性だった方については、ＲＮＡの検査を１回の採血で同時にできるような流れでやっております。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問","question":"分かりました。もう１点聞きたいんですけれども、２番の対象者の2)のところで、上記以外の区民健康診査結果において指導された者というふうになっておりますが、言葉のところでよくわからないんですけれども、上記以外の健診というと、区民健診の４０歳から７５歳の５歳刻み以外の方、要するに、区民健診で異常が指摘された人ということですか。","respondent":"田中健康課長","answer":"１点目の方は、５歳刻みです。２点目の方は、例えば今回の場合ですと、４１歳、４２歳、４３歳、４４歳、この方は受診券がいっておりませんので、一般の区民健診を通常どおり受けていただく。","id":"exchange-066"},{"speaker":"宮崎委員","kind":"意見","question":"節目でない方でも過去の検診の結果を見てやれますということですね。3)の「過去に肝機能異常を指摘されたことのある者」と、4)がなかなか選定が難しいんだというお話なんですけれども、「保健所等で」となっているんですけれども、「等」ということは、何かほかに考えているのか。指摘されたことのある方の選定が難しいという理由をお聞かせいただければと思います。","respondent":"田中健康課長","answer":"3)、4)ですが、過去に肝機能異常を指摘されたといいますと、私なども何度もひっかかっておりますし、ＧＯＴ、ＧＰＴ、ΓＧＴＰ、あの辺は私どもも普通の職員の健康診断でも一般的な数値ですので、そういうものも入れるのかという意味では。","id":"exchange-067"},{"speaker":"宮崎委員","kind":"質問","question":"仰々しいような感じもしているんです。もうちょっと気軽にできないのかなというふうな感想があるんです。例えば献血をしますと、その場で肝機能が出るわけです。それがあったら、いつもかかっているところで検査を受けられるとかというのはできないのかと思うんですけれども、今話を聞いた感じでは、かなり面倒くさいという感じがするんですけれども、そこら辺のところはどうでしょうか。","respondent":"田中健康課長","answer":"今回の肝炎のウイルス検査というのは、検査所のほうへ持っていって、医師会の医療機関についても、ご自分のところではもちろん判断できませんで、いろいろ難しい内容を含んです。","id":"exchange-068"},{"speaker":"宮崎委員","kind":"質問","question":"異常があると、「異常です」というのを渡されることになっていますね。それを持ってきたら、例えば保健所等に行かなくても、通常の区民健診をやっているところでできるとか、そういうことはできそうに思うんだけれども、どうですかというふうに聞いているんです。","respondent":"田中健康課長","answer":"委員おっしゃる意味での受け入れというのはできないことはございませんが、医師会の理事の方等といろいろこの間折衝してまいりまして、そうなりますと、申し出た方がすべてほとんどひっかかって、受けるような状況になるのではなかろうかという話になりまして。","id":"exchange-069"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私の質問がうまく伝わっていないのかもしれないなという感じがしました。私が言っているのは、何も根拠がない、根拠が薄弱というか、そういう方も対象にというふうには私は言っているつもりではないんです。ですから、そういう人などはどうなのかというふうに言っているわけで、ここのところはまだはっきりしていないようなので、改善できればしていただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"辻副委員長","kind":"確認","question":"区民健診の段階ではただでやってくれるんでしょうけれども、精密検査というか、二次検査というんですか、そうなると、自己負担が出てくるという、この辺の流れというのはどうなんでしょうか。今回東京都が１０月から全国で初めてやろうという、自己負担に対して助成するという仕組みというのはお聞きになっているのか、まずその辺の流れについてはどうなんでしょうか、お聞きします。","respondent":"田中健康課長","answer":"ただ、まだ正式なものとして私どものほうに流れてきてございませんで、一応こういう計画があるよという、それでなおかつ、精密検査を、ウイルス検査の部分というのは非常に難しい判断があるそうでございまして、どうもそれに合わせて都内１００ほどの病院を都のほうも指定して。","id":"exchange-071"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ですから、医療うちでの国検診の問題、次から精密検査の部分での自己負担を含めての問題、それから、場合によっては、医療を介しての医療助成というようなことを東京都のほうは考えて、総合的なＣ型肝炎対策というのを進めようとしているわけですから、その辺決まり次第で結構ですので、お知らせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]},{"id":"topic-04","title":"７番、平成１３年度介護保険制度の運営状況","agenda":"７番、平成１３年度介護保険制度の運営状況","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"今日は説明をいただいて、これからいろいろ勉強していきたいと思うんですけれども、その上で幾つか確認をしておきたいんですけれども、教えていただきたいと思います。１１ページの施設サービスのところでの特別養護老人ホームの最新の待機者の数をお知らせいただきたいと思います。１２ページで、平成１３年度は決算の見込みというふうになっているんですけれども、一定程度締めたところのものですか。","respondent":"早津高齢福祉課長","answer":"平成１３年度の決算見込みですが、一応５月末で締めた形ではありますが、まだ精査段階に至っておりません。速報値ぐらいということで、あくまで見込みということでお願いをしたいと思います。","id":"exchange-073"},{"speaker":"宮崎委員","kind":"質問","question":"最後のほうから聞きますけれども、私が聞いたのは、どこら辺に苦情が集中しているのかということで、そこら辺の傾向をちょっと知りたいと思って伺ったんですけれども、そこら辺のところは全然ないんでしょうか。あったら、聞きたいということです。","respondent":"新美保健高齢事業部長","answer":"保険料のほうは手続関係、例えば口座振替とか、支払い方法、つまり年金天引きですが、６５歳になったときに、一旦普通徴収になって、一定時期以降特別徴収とか、細かな手続関係で、通常のご説明外の方が結構いらっしゃるものですから、苦情といいますか、少し疑問も含めた。","id":"exchange-074"},{"speaker":"宮崎委員","kind":"質問","question":"１３ページの意味は分かったんですけれども、私が伺ったのは、１２ページと１３ページのところの数字が変わってくるのはどういう意味かという、単純な質問なんです。例えば保険給付費の財源内訳というふうに１３ページになっていて、１２ページのほうは決算見込み構成比というふうになっていて、この意味が違ってこういうふうになるのか。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"この６,６００万円は第１号保険料によって賄うものです。正確なのは部長が答えます。１２ページのほうは単純に決算見込みです。歳入で第１号の保険料、つまり平成１３年度は４分の３に当たるわけです。","id":"exchange-075"},{"speaker":"藤原委員","kind":"質問","question":"１点お伺いしますが、１５ページの、主な苦情の内容のところで、サービスのところで、「ヘルパーが連絡もなく休むので困る」という苦情がありますが、これは基本的にあってはならないことですよね。これに対しての対処はどういうふうに行われたんでしょうか。","respondent":"高橋介護保険担当課長","answer":"ヘルパーが予定の時間に来ないという苦情ですが、対応策といたしまして、実質やったのは、事実の確認を含めて、支援センターと事業者に連絡をいたしまして、連絡先との食い違いとか、そういった部分で事業者に反省を求めました。","id":"exchange-076"},{"speaker":"須藤委員","kind":"質問・要望","question":"しっかりまとめ上げたすばらしい資料をいただきまして、ありがとうあります。この辺はこういう状況のカーブが続くのか、最初に介護保険導入に踏み切って、ＰＲが効いてきたので、今こういう状況ですよという形で、ある程度この数値が高齢化率と同じように移行してくるものなのか、その辺は全国的なものと比較しながら、どういう状況なのかということを教えていただきたい。","respondent":"早津高齢福祉課長","answer":"医療では継続しておりますので、そちらでやっていらっしゃる方もいるわけですけれども、南大井のほうを有効に使いながら、必要な人へのサービスに努めていきたいというふうに考えてあります。","id":"exchange-077"},{"speaker":"須藤委員","kind":"質問","question":"平成１２年だと８.何％というので、高齢化率に近い数字になっていますよね。ですから、その辺と考え方を一緒にしながら、今後の介護者数というものを想定していくことができるだろうと思うんだけれども、そんな考え方を持っていいのか。","respondent":"早津高齢福祉課長","answer":"委員のおっしゃるとおりだと思います。大きな傾向で言えば、介護保険制度が定着してきたことが、一つはこの認定者の傾向の中でも見受けられるでしょうし、この傾向を踏まえれば、見込み等についても、従来よりは立てやすいような状況になりつつあるのではないかと考えております。","id":"exchange-078"},{"speaker":"須藤委員","kind":"質問","question":"国民健康保険なども、かからなかったら優良表彰みたいな形でやっていますよね。自治体によってその辺の融通性がつくれないのかなというような思いがあるんだけれども、いかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"ただし、財源について、介護保険に基本サービスは、先ほどの財源内訳のように、国民健康保険も第２号も国の負担金もありますが、特別給付、保健福祉事業は、第１号の保険料で賄うというのが基本になっておりますので、財源構成の面、または分かりやすくしていく。","id":"exchange-079"},{"speaker":"須藤委員","kind":"意見","question":"そうすると、その辺のメンバーの公平感というのか、いろいろな面でお考えをしていって、介護保険料として云々するのは難しいだろうけれども、同じ高齢者も元気だから、逆にこれだけのものがあるよという、恩恵があるので、元気でいられるんだという絵も必要だろうと思うので、その辺もご配慮を、今後検討の中に入れていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"築舘委員","kind":"質問・要望","question":"そのページで、状態変更というのがあるんですけれども、この状態変更というのは、どういう状態なのかということを教えていただきたい。その辺がどういうふうになっているのかなというのをお聞かせいただきたい。在宅介護支援センター以外のところは民間ですから、なかなか集計ができないんだろうなということで推察いたしますけれども、そこのところを教えてください。","respondent":"早津高齢福祉課長","answer":"その後、例えば１年とかという更新期間を設定するわけですが、その更新期間前に状態が変化があって、介護度が重くなったようだから、もう一度認定をしてほしいというような方に対応した措置が状態変更という区分で行っているものです。","id":"exchange-081"},{"speaker":"築舘委員","kind":"質問・要望","question":"それでケアマネージャーがつく前なので、どういうふうにしていいのか自分でもわからないということで、そのままになっていたということなので、むしろ介護支援センターのほうが審査をしたという段階で、その人に対して支援センターのほうで連絡してあげるというのが丁寧ではないかと思うんです。ケアマネージャーはまだついていないわけですから、その辺はどうかというのをお答えいただきたい。","respondent":"早津高齢福祉課長","answer":"私どもも、その方はもちろんご希望されているわけですから、ご希望に間違いないと思うんですけれども、必要度等というようなことをいろいろ考えてみますと、本当に必要性の観点から見たときにどうかというところまでは実数としては把握できないというような状況です。","id":"exchange-082"},{"speaker":"宮崎委員","kind":"質問・要望","question":"分かったら、後で教えていただきたいと思います。ケアプランを作成していない方が５０８人となっているんですけれども、こういう方へのアプローチというか、そういうのは何かされているのかどうなのか聞きたいんです。ぎりぎりまで我慢してやっているものですから、いざとなると施設の入所とか、そういう要望になってくるんですけれども、ところが、在宅のサービスを使っていないとなかなか厳しいんですよね。","respondent":"早津高齢福祉課長","answer":"第１問目のご質問は、６ページのところですが、Ｂの、在宅でケアプランを作成しているところの内訳で、在宅介護支援センターが４,２９６人で、支援センター以外が４６１人、９対１ぐらいの割合だです。","id":"exchange-083"},{"speaker":"宮崎委員","kind":"確認","question":"今のところをちょっと確認したいんですけれども、品川区の場合は特別養護老人ホームの対象を入所調整会議で調整しているんですけれども、そのときには在宅での期間とか、困難度とか、そういう幾つかの基準の中に、一つは、在宅でのサービスを使っているかどうかというのがあったかと思うんですけれども、そういうことなども、場合によれば、こういう条件であって。","respondent":"早津高齢福祉課長","answer":"特別養護老人ホームへの入所調整の判定基準の中での在宅サービスの活用度というのは項目としていますので、これは在宅でどのぐらい頑張っていらっしゃったのか、在宅で頑張って、頑張り切れなくなった方に施設への流れをつくりましょうという、この趣旨の中で。","id":"exchange-084"},{"speaker":"宮崎委員","kind":"質問","question":"私が伺ったのは、在宅でずっと頑張っていたんです。ところが、家の中に人を入れたくないとか、いろいろな事情で、家族が頑張っていた。だから、在宅で頑張っていたイコール公的サービス、在宅サービスを使っていたということではなくて、たとえ在宅サービスを使っていなくても、自宅で頑張っていたというふうに認定するというか、そういうことでいいんですかということです。","respondent":"早津高齢福祉課長","answer":"委員のおっしゃるのは、サービスを使っていたかどうかということを入れることについてどうなのかというご質問かと思いますが、在宅を頑張るためには、介護保険サービスを有効に使うことが大事だというふうに私どもは考えておりますので。","id":"exchange-085"},{"speaker":"山路委員","kind":"質問・要望","question":"南議員の一般質問の中で、生活保護申請にあたっての窓口対応の質問に関連して、フォローの質問をやらせていただきます。その中で、Ａさんの例については、診断書その他の書類の提出を求め、何度も区役所まで足を運ばせるものの、申請を受け付けなかったとの指摘がありましたが、真相はどうなんでしょうか。確認しておきたいと思います。事実関係を確認したいと思いますので、説明していただきたいと思います。","respondent":"小沼福祉事業部長","answer":"これは南議員のほうの錯覚なのか、あるいはケアレスミスなのか、ちょっと分かりかねますけれども、保護費についてですが、国と区が半分ずつというようなことをおっしゃられたと思いますが、私が知る限りでは４分の１が区、市町村が４分の１というようなことが１点ありますので。","id":"exchange-086"},{"speaker":"山路委員","kind":"質問","question":"南議員は、生活福祉課の窓口に訪れた区民に、区役所にはもう行きたくないと思わせたり、何度も足を運ばせることは、結果的に保護を受けることをあきらめさせ、申請しないようにさせるものではないかとして、絶対にやめるべきだと断定がありましたが、南議員の発言のように、品川区生活福祉課の窓口対応というのは、相談に来た人に生活保護を受けられない状況をあえてつくろうとしているのですか。","respondent":"小沼福祉事業部長","answer":"遅延させるとか、不作為に図るとか、少なくとも意図的にそういうような作用、あるいは働きかけているという事実はないと。これは私どものほうの職員の名誉と、品川区の福祉事務所の名誉がかかっている問題ですから、この場で改めて宣言します。","id":"exchange-087"},{"speaker":"山路委員","kind":"質問・要望","question":"今後の対応として、誠実で、一生懸命取り組んでいらっしゃると私は確信を持っておりますけれども、職員の対応について、職員の方が一生懸命やっていらっしゃるのに、誤解があったら申し訳ないということを私自身も思うわけですが、今後どのような対応を考えていらっしゃるか、コメントがあったら述べていただきたいと思います。","respondent":"小沼福祉事業部長","answer":"これはたしか南議員の再質問のときに、窓口対応を親切丁寧にというようなことでのご質問がございましたけれども、その際に私のほうでは、区を挙げて、一つにはイメージアップ運動ということで、これは何も生活福祉課だけではございませんで。","id":"exchange-088"},{"speaker":"須藤委員","kind":"質問","question":"適切な窓口対応というのは必要だと思うんですけれども、今山路委員が言ったように、公平、中立なという考え方も職員の皆さん方はお持ちだろうと思うんです。それでいろいろな質問をされたりというようなことがある。そういったこともあろうかと思うので、公平に審査をするということの考え方については、今部長が、確かに窓口応対は丁寧にしなければいけないけれども、その辺のところはいかがでしょうか。","respondent":"小沼福祉事業部長","answer":"時を見て、あるいは折を見て、こういうようなものを引き続きつなげていって、疑われることがないような生活福祉、あるいは保護行政というようなことで今後とも努めてまいりたいと、かように考えてあります。","id":"exchange-089"},{"speaker":"須藤委員","kind":"質問","question":"お仕事によっては、区民の方々と土曜日に、あるいは日曜日に会わなければいけないとかというような、いわゆる区役所の日常業務の状況ではない時間に職員の方が出ていくようなこともあろうかと思うんですけれども、その辺はいかがでしょうか。","respondent":"小沼福祉事業部長","answer":"行き倒れというんでしょうか、そういうケースから始まりまして、臨時、あるいは飛び込みだとか、定例的な、継続的なケース等がありますから、そういう点で、不公正、あるいはいろいろと疑義等が生じないような形の対応、ですから、ケースによりましては。","id":"exchange-090"},{"speaker":"宮崎委員","kind":"確認","question":"我が党の南議員の一般質問へのフォローということでやられましたので、私も確認したいと思いますけれども、今Ａさん、Ｂさんの事例については、そういう事実はないと、そういうふうなご答弁だったかと思うんです。確認をしたいんですけれども、Ａさんの場合、実際に申請はされなかったということですね。そうすると、相談の段階だったということでいいんですか。","respondent":"小沼福祉事業部長","answer":"つまりそこのお宅の中で、保護を開始するにあたっては、家族の中での意思の統一、あるいは意見の一致が必要なケースでございましたので、その旨を申し上げてきたです。その後、幾つかその関係のやりとりが重なりまして、この方は結果的には今は保護の開始を受けているです。","id":"exchange-091"},{"speaker":"宮崎委員","kind":"質問・要望","question":"一つ確認したいんですけれども、相談は何回されたのか。それと、今、診断書が相談の段階で提出が求められたようですけれども、実際に診断書の提出が求められたのかどうか。求められたとしたら、その根拠は何なのか、お伺いしたいと思います。もう一つは、家族内での意思一致が必要だと。家族の場合、基本的に私もそう思うんですけれども、これは基本的な対応ということでいいんですか。","respondent":"小沼福祉事業部長","answer":"それは私どものほうでの法定の義務です。そこの中でさまざまな面接診断というようなことをまず行ってまいります。ご家族の状況が単身の場合と、家族がある場合と、いろいろありますけれども、そのときに年齢、あるいは生計状況、そういうことを調べていくです。","id":"exchange-092"},{"speaker":"宮崎委員","kind":"確認","question":"私が聞いたのは、診断書の根拠を聞いたんです。それと併せて、診断書は申請者の診断書ですか、それとも申請者とは違う方のですか。そこのところを確認したいと思います。","respondent":"小沼福祉事業部長","answer":"詳しい話につきましては、これ以上はここの場では申し上げることができません。","id":"exchange-093"},{"speaker":"宮崎委員","kind":"質問","question":"この診断書の件というのは、何でこれをやったのかと私は不思議でしようがないんです。生活保護の申請で必要だということであれば、検診命令というのが別にあるわけです。その内容とは違いますよね。そこのところはどうですか。検診命令での検診ですか。","respondent":"小沼福祉事業部長","answer":"この方の場合、いろいろと資産を調べていく状況の中では、ある程度の資産がある世帯ですので、今言ったような検診命令云々のケースとは違いまして、こちらのほうで、相談員が相談に来られた方がおっしゃるような状況であれば、そこの相談されている話について。","id":"exchange-094"},{"speaker":"宮崎委員","kind":"質問","question":"私は、その診断書の根拠を聞いているんです。そこのところが出てこないじゃないですか。どういう法的な根拠でこれを要求したのか。これは相談者が要求されているんですよ。そこのところを私は聞いているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"辻副委員長","kind":"意見","question":"議事進行。ちょっと秘密会にしてもらえますか。ましてや、診断書の中身について、先ほど部長が言っている、その問題についてどういうことかということで、だから秘密会を、根拠というか、どう言っているのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"須藤委員","kind":"質問","question":"議事進行。個々のケースを一般質問のフォローでやっていくことまで必要なのかなという思いがあるので、今全体的な職員の対応という形で、適切な対応をしているという表現をいただいているので、あと、それ以上個々の問題について突き詰めていくなら、私も非公開でやっていかないと、１回休憩して、なしの話にするのか、その辺を整理しないと、いろいろ問題で出てきてしまうと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"宮崎委員","kind":"質問","question":"もう一つは、今回の具体的な事例をもって、事実があるかどうかということで質問がされている。私が今聞いていたのは、診断書の中身とか、どういう診断だったのかということじゃなくて、その診断書を請求した根拠は何だということを聞いているわけですから、これはプライバシー云々のところにはならないと思いますので、そこのところは今の秘密会などというのは、私はそういうふうにならないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、診断書とは別に資産調査のところでは、貯金もあって、余裕があったと。経済的な余裕がある人が、例えば体が具合が悪くて生活保護を受けるということは、どういうケースがありますか。貯金が一定程度あったけれども、そういう状態で、普通私の経験ですと、大体貯金等があると、それだけで生活保護を受けるのは難しいんですけれども、その上に何で診断書を求めたのか、ここのところを聞いているわけです。","respondent":"黒田生活福祉課長","answer":"先ほどご答弁申し上げましたが、まだ余裕があったわけですから、こちらは預貯金がある方には生活保護を開始してございません。求めたのは、まだ預貯金がございました。生活福祉課の窓口にはいろいろな相談を含めてのご相談があります。","id":"exchange-099"},{"speaker":"宮崎委員","kind":"確認","question":"私が聞いているのは、調査で資産がある、貯金があると分かっていれば、その時点で生活保護はちょっと無理ですよという話になるんではないですか。この事例のことで出ていますから、この事例で事実関係を確認しているわけです。ここのところをちゃんと確認をしたい。例えば分離して保護をかけるとか、場合によってはあるかと思うんですけれども、そういう対応はどうですか。","respondent":"黒田生活福祉課長","answer":"ですから、ご本人と、もう一人の方、申請に見えた方と子どもということですが、申請に来られた方が年金をお持ちでしたので、その年金が貯金にまだ残っていたですので、それが先ほどから申し上げている預貯金の中にまだ生活できるということですので、なくなった段階ということで。","id":"exchange-100"},{"speaker":"宮崎委員","kind":"質問","question":"二つ目の質問は、家族がある場合は、基本的に家族での対応だというふうに私も思います。だけれども、場合によっては、分離して法を適用する場合などがあるんじゃないですか。そういうふうな対応というのは原則どういうふうになっていますかと聞いたんです。","respondent":"小沼福祉事業部長","answer":"先ほど来から申し上げておりますけれども、原則は原則であると。それから、分離ということもありますけれども、それができないような家庭状況があるということで、再三再四申し上げていると、こういうことでご理解をお願いしたいと思います。","id":"exchange-101"},{"speaker":"宮崎委員","kind":"質問","question":"私も実際聞いた方の例がいろいろあるんですけれども、例えば７０歳代のご夫婦が、生活保護を申請したと。そういう方の話を聞く機会があったんですけれども、その方は実際上は打ち切り時点の前後あたりですでに貯金も全部なくなっていたんだけれども、それから１年ぐらいも受けられなくて困っていたと。この方の場合は、実際に不正受給ですから、それがいいとは言いませんよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"宮崎委員","kind":"確認","question":"私も終わりにしますけれども、最後にもう一回、確認したいのは、診断書の提出を要求したのは、法的な根拠というのは、今お話がなかったけれども、その根拠はどういうものか。そこのところをもう一回、いわゆる検診命令じゃないほうですね。こっちはどういう根拠でされたのか。そこのところをお聞きしたいと思います。","respondent":"黒田生活福祉課長","answer":"生活保護の開始にあたりましては、資産活用、いろいろな能力を活用していただくということが前提です。稼働能力もその能力の一つですので、能力がないというときには、挙証書類をそろえていただくというのが前提ですので、それが診断書に当たります。","id":"exchange-103"},{"speaker":"宮崎委員","kind":"質問","question":"そうだとすると、今回やっていないですから、早くやってあげなければいけないのかなと思うんですけれども、継続審査の申出書に入っているので、このとおりやっていただければと思うんですけれども、本来であれば、今回の第２回定例会、きのう、今日あたりでやっていなければいけなかったんじゃないかなとも思うんですが、これでぜひお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"宮崎委員","kind":"提案","question":"きのうの今日で、私自身も検討が不十分なものですから、今日私の意見というか、提案といいますと、出せるような状況でありません。次の２３日で提案というスケジュールだったんですが、もし委員会とは別に、いついつまでに出してくれないかみたいなものがあると、それまでに合わせられるかなというふうな感じがするんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"須藤委員","kind":"意見","question":"宮崎委員と同じで、きのう言われて、今日出せというのも、テーマについても、去年のテーマを聞かせていただいて、いろいろお考えがあると思うので、いつまでに正副委員長に出して、それを２３日に整理をしてというような形で段取りをとって、２３日にはしっかり決めるという形ならば日程的に間に合うだろうと思うので、今日すぐどこの、テーマをということでなくて、委員がそれぞれ考えられたらと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-106"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270319?Template=document&Id=3024#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":82439,"voices":262}},{"id":"h14-20020702-8","meetingId":"h14-cm07","date":"2002年7月2日","dateIso":"2002-07-02","committee":"建設委員会","time":"午前１０時０６分～午後２時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"意見","question":"４段目のまず、「本計画線は」というところの部分で、「地域の防災性の向上を図るとともに、地区の交通を分担する機能を果たす地区幹線道路として位置づけられているが」という部分なんですけれども、現状で言えば、こういったこと、つまり防災であるとか、幹線道路、実際の役割は、ほかのところで見直す、防災関係の道路をつくる以外の事柄がいろいろ行われているというようなことや。","respondent":"北野委員長","answer":"別の事柄というところで、先ほど、道路も一つ、挙げられていましたけれども、昨日、正副のほうでつくらせていただいた案文の中では、２種類つくらせていただきまして、その中の片方には、補助２６号線の幹線により、この地区一帯の防災機能を一層充実してきておりということで。","id":"exchange-001"},{"speaker":"船波委員","kind":"意見","question":"防災に関しては今のような内容でいいと思いますけれども、道路に関しては、例えば昨日すでに審議した請願の文章の中では、既に、南北に平行して走る路線として国道１号線が西側の５００ｍの距離にあるというのがありましたけれども、そういった事柄を盛り込んで、この２９号線が目的としている事柄は、既にほかの部分でそのことは達成しているというようなことを入れたほうがいいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"堺委員","kind":"質問・要望","question":"昨日の請願のことなんですけれども、今、手元に配られているあの中に、今、お話があった補助１６３号線とか、２０５号線、これ、ありましたね。そういう補助２９号線のような幹線道路が今、整備されつつある。請願要旨に入っていましたね。私もそんな気しますけども変更可能ならば、そういった形で進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"４の報告事項","agenda":"４の報告事項","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"この方の未払いに至ったその辺の生活の状況といいますか、これを具体的に教えていただきたいのと、それと、報告第１７号と第１８号、１８号のほうは滞納したのは、約１年５カ月ぐらいですかね。そこへ参りましたけれども、これからこういう専決処分なんかは、このまま同じように議会に出てくるのかどうか、その辺だけ教えていただきたいので。","respondent":"田村住宅課長","answer":"それと、３点目の宅建センターとの絡みですが、専決処分等、やはり一定の、中短期の滞納については、宅建センターのほうの督促だとか、催告というようなことを一定、やっていただきますが、法的措置については、これは自治法上、行政しかできませんので。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"宅建センターのことで、ちょっともう１点だけお聞きしたいんですけれども、ちょっと私のところにね、宅建センターでの募集を始めるということで、収入とかも含めて、そこで見ていくところになるわけですけれども、この辺での感情、プライバシー上の問題も含めて、どういう宅建センターと、それから、都の役割の分担みたいなところも含めて、ちょっと、多少、細かく教えていただきたいんですけれども。","respondent":"田村住宅課長","answer":"本件とちょっとあれですけれども、宅建センターのほうと私のほうですね、もう再三、繰り返し、今回、区のほうが、前にもお話ししましたが、品川都市整備公社を介して、宅建センターの民間活力を活用するということで、４月からその切り替えをするというので。","id":"exchange-005"},{"speaker":"船波委員","kind":"質問","question":"すみません。このご報告は、ここに入居している方々に対して、明け渡しと、納めていない使用料の支払いに努める。そういったことをしたということで、その後、明け渡されたかどうかということは、その後の状況はどうなんでしょうか。","respondent":"田村住宅課長","answer":"報告第１７号の場合ですが、その後ですね、こういう形の、先ほどご説明した訴えを提起したという形で、その訴えを提起しましたので、第１回口頭弁論を４月２５日に地方裁判所で行いました。第２回の口頭弁論、５月１６日に行いました。","id":"exchange-006"},{"speaker":"船波委員","kind":"質問","question":"先ほどのご説明では、それぞれいろいろな事情があるんでしょうけれども、その時に区以外に借金があって、そういったことで首が回らないというご説明がありましたけれども、区の側としては区民住宅から出ていってもらって、これでおしまいとしてしまっても、その人の何ていうか問題が解決しないわけで、そうやって借金を抱える状態では、今後の生活であるとか。","respondent":"田村住宅課長","answer":"これは、やはりご本人が自主的な判断で、親戚のうち、友人宅に居候をするなりして、生活設計してもらうという形以外はないんじゃないのかなというふうに考えているところです。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民のどういった要求を満たしていく、利用してもらいたいような公園にしていくのかというところを、もうちょっと詳しくお聞かせいただきたいと思います。もう１点は、バリアフリーの、今、シャワー室とだれでもトイレというお話があったんですけれども、バリアフリー化がどういうふうに図られようとしているのかと、あとトイレですがどのくらいあるのかも、その辺もちょっと教えていただきたいと思います。","respondent":"岩田管理工事課長","answer":"多くの方からご意見をいただいた中で、いろいろ絞り込んで、当委員会にも何とかその内容をご説明しまして、最終的にこのプランで固めたものです。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"たくさんお答え、ありがとうございました。昨日、ゲートボールのところも見に行ったんですけれども、ゲートボールもただお年寄りだけじゃなくて、こういう広場を利用して、若い人とも交流する場としてすごく活用の範囲が広いのではないかなと思うので、ぜひ、その辺もいろいろなところを参考にして、活用できる広場、天然芝が生かせるような活用の広場にしてほしいなというのが要望の一つです。","respondent":"岩田管理工事課長","answer":"緑につきましては、基本的には公園ですので、可能な限り緑を多く植栽をしていくように努めてまいりますけれども、ここの第２期工事の部分につきましては、天然芝を中心として考えてますので、高木をデザイン的には幾つか配置はする予定になっておりますが。","id":"exchange-009"},{"speaker":"堺委員","kind":"提案","question":"確認だけ何点かしたいと思います。そういういわゆる、この中央公園は、どういうふうに制限するのですか。それから、もう一つ、前も予算特別委員会か決算特別委員会で、提案したことがあるんですけれども、中小企業センターの１階突き当たりに食堂がありますよね。先般、私が提案したことがあるんですが、その辺はどうなっているかということ。１点だけ、お尋ねしておきます。","respondent":"岩田管理工事課長","answer":"これ、第２期のほうの工事になるんですが、台数については平面で一箇所で１００台程度は置けるようにはなっておりますが、場合によっては利用状況を見ながら、機械を設置したら、もっと詰めて台数を入れられますので、全体の利用状況を見ながら。","id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"ありがとうございました。今、お答えいただいた方向で、ぜひ、進めていただきたい。さらに確認しておきますけれども、安全対策ということでですね、深夜について夜間の巡回警備、民間に委託して考えておられるということですから、また良かったなと思います。これだけの広い公園ですから、区民公園はいろいろあって、かぎがかかっている。それがない。そういう面ですね。このことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"工事のことですが、１期工事は議決後、すぐ着工するということですが、２期工事の最終全面完成予定はいつになるのか。それとあと、ネーミングなんですが、最終的には、この仮称というのはいつごろとれていくのか、正式名称がいつ完成するのかということと、その決定されるという、そのネーミングをつけるに当たってのコンセプトといいますか、考え方というか、大きく３点、お伺いします。","respondent":"岩田管理工事課長","answer":"全面オープンの予定ですが、再来年の４月１日に全面オープンの予定です。来年の４月１日には、この多目的広場、テニスコートを含む今回の第１期部分と、それと、こちらの北側のですね、区民住宅と一体となった公園、この部分を同時にオープンをいたします。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点だけお願いします。すみません。先ほど、飯沼委員がバリアフリーということでお話をしました。車で来た方は区役所の駐車場を使うというようなことは、障害を持っている方、例えば車いすなんかの方は、坂道の道路を上がって公園を利用するということになるんですけれども、その辺の手だてといいますか、もし考えていらっしゃれば教えていただきたい。","respondent":"岩田管理工事課長","answer":"この中に駐車場をつくること自体は面積的にも無理ですし、特定の１台分だけをここに用意するというのも余り好ましいことではないものですから、それよりは駐輪場の数をふやしていきたいと今回の場合は考えております。","id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"位置的に言えば、もしそういう方がいらっしゃれば、中小企業センターの駐車場を使えるほうが楽なんだと思いますけれども、うちのマンションなんかでも自分で車を運転して、車いすを車から出して、乗り移って、こういう方がお二人いらっしゃるんですけれども、やっぱり特に交通事故やなんかで半身麻痺になられた方というのは、結構、運動というか、そういう人というのはありますから、そういう方がこの公園で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"北野委員","kind":"質問","question":"朗読が終わりました。いかがでしょうか。〔「異議なし」と呼ぶ者あり〕 では、皆さんのご了承をいただきましたので、この意見書にて提出することにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"菊地委員","kind":"意見","question":"一つは管理、このスカイウェイのほうとつながるということですけれども、この管理をどう区分していくのかということと。それから、今、これ、取り壊して工事を始めるんですけれども、都営第２アパートのお住まいの皆さん、これから八ツ山通りへ抜けるときに、通行帯というのはどういうふうになっているのか、この１点だけちょっとお聞かせください。","respondent":"岩田管理工事課長","answer":"ただ、ある時期によっては全面通行止めせざるを得ない時期もありますが、これは今年１月、地域の方との住民説明会で実際の役員の方ともご相談したんですが、住民の方は遠回りでも回って協力していただけるということでしたので。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"今、この部分を残しておくということで、そのときにちょっと現場を見たときに、ここにはほとんど横断歩道帯ってないんですよね。９０度ぐらいの角度で、車が入ってきていますけれども、ちょっと短期間のことなのかというのはわからないですけれども、信号機つきの横断歩道っていうのは、将来的にこれをつくるとか、後に設置するとかということはできないんでしょうかね。そこだけ。","respondent":"岩田管理工事課長","answer":"この絵のような形で道路が全面的に広がりますのは、かなり先の話ですので、当面、この橋の工事をやっているときは、現況の通行の形で工事を進めますので、特に歩行者の方がここの道路を横断する場合に、信号が必要なほど交通量はございませんので、信号機の設置ということは。","id":"exchange-017"},{"speaker":"堺委員","kind":"確認","question":"現地での説明のときにあったんですけれども、これまで確認していたことは、自転車の対応について、この図面でいくと、今度、２.５メートルに拡幅するから、この図面のここのところ真ん中を自転車が通れるようになって、そのように見えるんですが、どういうふうにしていただけるのか。それから、脇の階段ですよね。確認をしておきたいなと思います。","respondent":"岩田管理工事課長","answer":"２点目のエレベーターの件ですが、エレベーターはＢ－４街区が今後つくりますスカイウェイで、奥の建物のほうに、階段らしきものがちょっとごらんになれるかと思うんですが、この図面ではちょっと、絵では載っておりませんけれども。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"取り組みのところで、アンケートの調査実施とありますけれども、この辺、どのぐらいの方に、どのようなご意見が寄せられたのかと、あと、住民説明会開催の参加状況をちょっと教えていただきたいと思います。","respondent":"浜脇住環境整備課長","answer":"当然、建て替え、この事業が開始されれば協力をしたいという方がいらっしゃるといいますか、返事が多かったですので、予定どおり、来年４月１日に向けて、今後、やってまいりたいなということです。住民説明会のことですが、住民説明会、実は距離が長いものですから、１日で２回。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご丁寧にありがとうあります。今後の要望なんかはどういった機会というか、話し合いの集まりがあるんでしょうか。","respondent":"浜脇住環境整備課長","answer":"地元の方々に対してですね、この間、説明会をやった際に、ちょっとここのところ、町会とですね、接触がなかったんですが、久しぶりに接触ができまして、町会長を中心にまちづくりということで、地元のほうとすれば。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お約束ができているということなので、引き続きご意見を聞いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"船波委員","kind":"質問","question":"同じような目的があるものであるんだけれども、助成ができるところとできないところというのは、どういった理由で助成するところ、しないところというそういう違いが出てきてしまうんですか。","respondent":"浜脇住環境整備課長","answer":"昨日の戸越一丁目地区地区計画の場合には、密集住宅市街地促進事業ということで、あれも同じように、この事業と同じように、道路、公園や、あるいは不燃化の建物に対する助成ができるんですが、たまたま１種事業の場合には、アパート、賃貸住宅がないと補助ができないんです。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問・要望","question":"一つだけお聞きしたいんですけれども、都市防災のほうなんですけれども、当初の目標を７０％で、完了時に５６％の不燃化率で目標に達してない状況なんですが、これ、７０％の目標に対して５６％がどうかというのは、私、よくわからないところですけれども、当初目標を決めるときのこの根拠というのは、きっと何かあるんだと思うんですけれども、ちょっとその辺のところを教えていただきたいんですけれども。","respondent":"浜脇住環境整備課長","answer":"都市防災のほうにちょっと戻るんですけれども、都市防災不燃化促進事業のほうは、事業を導入して、１０年間で７０％になる可能性がある地区で実はやりなさいと、こういうことになってございまして、たまたま、この林試の森周辺について言うと。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"これだけのものをつくるとなると、つくった後、維持管理ですか、それはどこが、道路公園課のほうになるのか、庁舎管理の経理課になるのか、あるいは専門の業者にお任せして管理してもらうのか。その辺のところはどういうふうになっているのか参考までに教えていただきたい。","respondent":"松代道路公園課長","answer":"なるべく費用、維持管理等に費用はかからないような手だてを、その職員ボランティアといろいろ工夫しながら、管理をしていければというふうに考えてあります。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"これは、すばらしいと思いますので、ぜひ、これは区民の方々にいろいろ周知をしていただいて、いろいろなことを考えていただきたいと思うんですが、周知の方法と、あと、予算の財源といいますか、支出科目はなに費になるのですか。","respondent":"松代道路公園課長","answer":"先般、質問等でも出ましたが、ガイドブック、そういった厚いものにはちょっとできないかもしれませんけれども、簡単なものをつくって、そういったものを何らかの形でごらんいただけるような方法をとりたいなと。今、そういったものを考えているところです。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ、周知をしていただいて、区民の方を対象にした憩いの場にしていただきたい。先ほど、お昼休みということで、その結果としてですね、大半が、職員の方だけが憩うような状況になるというのもそれはそれでいいとは思うんですが、仮にそうなったとしたら、職員厚生の費用で賄うような内容になってしまってはいけないので、本来の趣旨が遂行されるように、ぜひ広めていただきたい。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"１０月２１日の週のいずれかに決めてはいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"堺委員","kind":"質問","question":"前半のほうに。というのは、そのあとの常任委員会の予定が１１月はじめでしょうから、それにかからない時期ということで早いほうが良いと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"堺委員","kind":"質問","question":"特定事件が決まっていますよね。そういうところに絞り込めるというのではないという気はするんですけれども、そういう中に今回は入れていただいたような屋上緑化ですか。海外調査団でもその件を調査するようですし、また、さっきいただいた報告にもありましたように、品川区、ほかでも屋上緑化、進めていくわけですから、そういう面で、そういうのも調査項目に。そういう気がしますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"意見","question":"私たち、今日、この屋上緑化の資料をいただいて、すごくきれいで、品川も楽しみだなと思っていますけれども、近くでは都内でもあるんですけれども、自治体で大阪とか鹿児島なんかで屋上緑化とか、あと空調と組み合わせたりしたり、ソーラーの関係、地球に優しい建物のつくり方とか、そういうのもあるので、屋上緑化なんですけれども、みんな、国内のところで生かしていただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"堺委員","kind":"質問","question":"それで、大体、建設委員会、過去数年、南のほうに行っているんですよね。鹿児島とか福岡とかだから、ぱっと方向転換してね、遊び半分じゃあいけないんですけれども、北海道、東北地方ですか、北のほうもたまにはいいかなと。過去に建設委員会は南に行っていますから。北のほうに屋上緑化とか調査項目であるかどうかちょっとそこまで調べていないからわかりませんけれども。","respondent":"北野委員長","answer":"そうですね。やはり視察候補地というのも、余り、だぶるというか、同じところではないところでというのは、確かに一つのベースになりますので、検討したいと思います。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"ただ、まだまだ必要だろうと思います。ですから、そういう意味では都市部での緑化対策とか、あと、この中にも水と親しむ公園として、水辺区域での河川対策。浄化だけはなくて、親水性ですか、そういった観点でのまちづくりということであれば、東品川公園でもつくろうとしていますので、そういう観点で視察できればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"船波委員","kind":"意見","question":"あるいは、いろいろ、その住民の人はこうやりたいと思っても、自治法とかその他のいろいろなことがつながってくると思いますけれども、そういったことにどう対処したかというような事例があれば聞いてみたいと思います。そこのまちづくり条例でしたかしら。開発されていないところでは、どういったまちづくりとか、都市整備とかが、そういった行政がどうやって行われているのかということに関心があります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"本間委員","kind":"意見","question":"特にこの地球温暖化対策というのは、全国の４７都道府県だとか、主要の１２政令指定都市なんかでも、相当、力を入れて、２００５年までに何をする、２０１０年までに何をする、２０年は何をするという具体的な数値を上げながら、取り組みを進めてきている部分がかなり経過としてあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"田中委員","kind":"意見","question":"そういう中で、水に親しむ、中島公園ってありますが、そういう水に親しむ公園づくりというのが行われたりとか、今回の品川中央公園の２期工事の中には水の部分、流れの部分というのもありましたので、そういうのもご参考になるのかなと思います。たまたま知りまして、今まで南方面でしたので、北のほうにもあるのかなと思って、ちょっと調べてみました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"林（和）副委員長","kind":"提案","question":"今ね、皆さんから提案が出たのをちょっと参考にしてですね、三つぐらい候補をつくりますので、それを今度、皆さんに検討していただいたらどうかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/923086?Template=document&Id=3728#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":38214,"voices":129}},{"id":"h14-20020702-9","meetingId":"h14-cm07","date":"2002年7月2日","dateIso":"2002-07-02","committee":"文教委員会","time":"午前１０時０４分～午後２時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"答弁の中では「今後１３０名ぐらいの入学で推移していくでしょう」と。１３０名を全部入れたとすると、４０人学級ですから４クラスでいっぱいになっちゃうということですから、そうすると果たしてどうなのかということです。お尋ねしたいんですけれども、小学校・中学校一貫校募集のそれぞれの仕方ですね。","respondent":"富田教育改革担当課長","answer":"は学区域につきましては、第二日野小学校の学区域のままということになりますけれども、現在は小学校については受入れ枠を設けておりませんけれども、その辺につきましても検討していく中で、小学校についても受入れ枠を設けるということになれば、受入れ枠を超えた部分について。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、それだけで今まで四つの小学校に入っていた子どもは、１５０名だと５学級になるわけですね。確かに、地元の小学校があるから分散をしていくと思うんですけれども、例えば地域の皆さんが小中一貫校を小学校から希望したら、日野中学校の子どもはまず無条件で入れるんですか、そこを聞きたい。その２クラス分については、日野中学校の子どもの枠というのはどうなのかを聞きたいんです。","respondent":"富田教育改革担当課長","answer":"第二日野小学校の学区域の児童がそのまま学区域として移行するという想定ですので、小中一貫校の小学校部分の規模について３学級というのは、学校の標準規模ですとか教育内容をもって一貫校として３学級が望ましいということで検討しているです。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"小学校はそれぞれの地元の学校に入ったということで、特別に地域の枠というのは設けない。それから、中学校に入った２クラスというのは、最大で８０名ですね。教育長の話では、地元の第一、第三、第四日野の子どもはその小学校に行って、中学校に一貫校を希望したときに入れることを考慮して４学級から５学級に増やしたというんですけれども、それは実際には入れるんですか。","respondent":"富田教育改革担当課長","answer":"その前に少しお話をしておきたいんですけれども、本会議の答弁で教育長が申し上げましたのは住民基本台帳上の数字でございまして、日野中学校入学者の過去３年間の数字を見てみますと、平均しまして約１９０人、それに対して入学者が約１３０人で。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"もともと開発校で一貫教育をやるのも、特別の１クラスでやるのだったらいいけれども、学生の中に放り込んだために、地域では「入れなくなったらどうするのか」という声が広がって、今度はゆり戻した格好で広げていくとなると、３クラスが一貫校で２クラスが新規募集の学校で、３クラスは別のカリキュラムでどんどん進んでいく。もう１点、前に私どもが「１００億円ぐらい」と言ったら、「断じて違う。","respondent":"青木指導課長、鷹倉庶務課長","answer":"その中でもきめ細かい指導と評価を繰り返す中で、一貫校の子どもたちに溶け込めるような内容のカリキュラムを考えたいと思いますし、８年生、９年生につなげるための７年生の特別コース。方向性としては、一定のクラスを確保していきたいですけれども、それを踏まえてどういう施設内容にしていくのか、どういうレベルのどういうしつらいにしていくのかはすべてこれからですので。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"一貫校と言いながら途中に入って、特別の７年生対策をするから不安はない、溶け込めるような対策を実際にやるとなれば相当難しいですね。小学校から中学校に上がったストレスをなくすと言いながら、後から入ってきて増えた２クラスは強烈なストレスを生ずるんじゃないかと思います。この辺については私どもが根拠のない数字を言ったかなのように言ったんですけれども、それはいかがなんですか。","respondent":"指田教育次長","answer":"その１００億円という話というのは、そのときの話と今の話と混同されて言われてしまいますと、私どものほうで「ここに１００億円がかかりますよ」ということはどこにもしゃべっている話ではありません。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"そのことを言ったんじゃないんです。１００億円という話がひと時あったけれども、港陽小学校の単価を見てみると、大体１００億円ぐらいの目見当は間違えていないんじゃないかと言っているんです。学級数が決まれば、ほぼ規模も決まっていくわけですから、それはどうなんですか。","respondent":"指田教育次長","answer":"今、１００億円かかるかどうかという話というのは、今、庶務課長が言ったように、これから積算していく話ですから、ましてや１００億円というお金がどうのこうのとなりますと、数字が一人歩きするので。","id":"exchange-006"},{"speaker":"高星委員","kind":"質問","question":"今年の春の予算委員会の中でも、私が総括質問の中でこのことに触れさせてもらった。やはり全体のところを日野中学校のグランドなり、日野中学校の校舎のところについても、大学のキャンパスのような形の中で、２１世紀の子どもたちを恵まれた、静かな、空気のきれいな、騒音の少ない、地域の温かい見守る目のある中で育むべきだと考えるんだけれども、その辺はどうなのか教えてください。","respondent":"鷹倉庶務課長","answer":"全体的にこのエリア云々というお話も、第一日野小学校にも関連する話ですけれども、教育総合会館ができたのが昭和５５年で比較的新しいということで、そこの部分についてはまだ取り壊しは困難だと考えている部分もありますので、具体的にはまだまだ難しいのかなと考えています。","id":"exchange-007"},{"speaker":"高星委員","kind":"質問","question":"１２５年の歴史があるわけですから、同窓会の中に町会長もいっぱいいるわけで、町会長同士がけんかになってしまう。話に乗ってくれたと。今になったら、指定されているのは日野中学校と第二日野小学校ということで、名指しで国の指定を受けるから、それを変えるわけにいかないと言われたらどうなっちゃうんですか。これでいいのかなという疑問を思わざるを得ないんだけれども、その辺どうなんでしょうか。","respondent":"鷹倉庶務課長","answer":"入れるだろかと、この部分を早く安心させてほしい、早く知らせてほしい。したがいまして、私どもとしてはその部分が一番大事なところということで、早く検討して、早く方向性を出して安心していただきたいなと、このように考えているところです。","id":"exchange-008","title":"町会・自治会支援"},{"speaker":"高星委員","kind":"質問","question":"フォローとぶれてきているので、これでやめますけれども、先ほど言いましたように、この間学校と地域が本当に連携を図るべきだということで、教育委員会のプラン２１の中で、地域の人たちに学ぶ事業とかいろんなことを取り組んでやってきているわけです。文部科学省の指定は日野中学校と第二日野小学校なんです」と言われたら、地元の人はますます怒るだけのことじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"高星委員","kind":"質問","question":"質問を変えます。いずれにしても、第二グランドにおける建て替えというのは、お金がかかるからからだめだということなんですか。","respondent":"鷹倉庶務課長","answer":"第二グランドの敷地だけでは、必要なスペースが満たされないということです。","id":"exchange-010"},{"speaker":"高星委員","kind":"質問","question":"第一日野小学校のところでは、もうその道はないということですか。","respondent":"鷹倉庶務課長","answer":"第一日野小学校のところにつきましては、先ほど申し上げた内容でご理解いただけるかと思います。","id":"exchange-011"},{"speaker":"高星委員","kind":"質問・要望","question":"そこだけの問題ではないわけです。他の地域は連携教育も含めた立派な品川区の教育をつくっていくんだと言っているけれども、もともと連携教育そのものは、ある意味では小中一貫校の大きな仕事だと思うし、その辺のところを今回の事業は本当に真剣になって考えていかないと、やっぱり品川区の教育に大汚点を残すことになりかねないと思うので、そのことは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"上山副委員長","kind":"質問・要望","question":"これもお聞きしたことがあるんですが、例えば小学校のブロック化のときのアンケート調査で、小学校の親御さんに平成１３年度に調査したものを紹介されておりまして、四つのブロックに分けて、今後どうあるべきかということで、「このままでいい」というのが５０.８２％で、「区内全体で選択したい」というのが３３．８５％ということで、かなり要望なども住民の方というか。","respondent":"若月教育長","answer":"実態をおさえるために、アンケートや数をおさえる、これも有効な一つの方法です。この小中一貫校についてのニーズというのは、戦後５０年余の義務教育の中で、さまざまな学校に対する要請とか、時には苦情とか、時には批判という厳しい形で長年言われてきた課題もあります。","id":"exchange-013"},{"speaker":"上山副委員長","kind":"質問","question":"最後に２点だけ申し上げたいんですが、先ほど述べたように、町会や地元の方のお話で不安とか心配みたいな形で出されると、質問の内容でもかなり心配が出されているようなんです。委員会決定前に公になることが繰り返されて、委員会の形骸化などでいろいろ問題がある」と。今回の一貫校の問題でも、やっぱり似たようなことが現に起きているんじゃないかと思いますけれども、そういうことはないんでしょうか。","respondent":"若月教育長","answer":"やはり解決できないでそのまま何十年来となく引きずっている課題もあります。そして、学校はそれなりに努力はしているんです。世間が言うほど、学校の教員はだらしないと思っていないんです。しかし、どうしようもないところもあるんです。","id":"exchange-014"},{"speaker":"高星委員","kind":"確認","question":"確認の意味で一つだけ。先ほど私から言いました、文部科学省の研究開発校の指定なんですが、これは確か期限付きだと思うんですけれども、その辺を教えてもらえませんか。","respondent":"青木指導課長","answer":"指定ですけれども、平成１４、１５、１６年という３年間の指定期間が付いてあります。","id":"exchange-015"},{"speaker":"高星委員","kind":"質問・要望","question":"そこで、例えば平成１４、１５、１６年の３年間で、平成１８年から小中一貫校をスタートする運びなんですね。この３年間で指定を受けて開発を進めていって、現実に平成１８年に小中一貫校がスタートできなかったというときはペナルティみたいなものがあるのかどうなのか、そこだけ教えていただきたいと思います。","respondent":"青木指導課長","answer":"罰則というようなものはございませんが、この研究というのは一応３年間というのが指定期間ですけれども、その後研究を継続するという前例もあります。この３年間が終了しましても、さらに継続研究ということも考えられますので、そのことも含めて検討してまいりたいと思います。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"だから、継続して検討というのもいいんだけれども、とりあえず３年間の指定を受けて、この先の何か事業をやるため研究校を受けているわけですから、スタートできなかったらペナルティはあるんですかと聞いているのに、検討という答弁では……。","respondent":"青木指導課長、若月教育長","answer":"私たちはそういう形で継続研究を追求していきたいと思っていますが、先ほど委員のご指摘の罰則というのは一切聞いたことはございません。補足をします。３年間の研究期間があります。これはご説明するまでもないんですが、これは何も平成１８年度に今までの指導要領から解放される真新しいものをつくるというものではないんです。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問","question":"先ほど高星委員から遊楽街のお話が出たので、それに対してだけお聞きしたいと思います。いろいろな説明会に行かれているときに遊楽街を通ってくる。私もこの話は何度も耳に挟んでいますけれども、その辺の話が出たときに、何とお答えになっているのかだけ。","respondent":"鷹倉庶務課長","answer":"したがいまして、その後そういう質疑がありましても、そういう言葉が出たとしても、我々はそういうことは言ってはいけないことじゃないかなという思いで受け止めております。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問","question":"それであるならば、今、検討委員会の中でいろいろな検討をしているのであれば、もちろんいろいろな場所からの通学路を含めて、ある程度こういう形でというものも含めて、検討委員会の中でやっていただくことが一つの方法だと思いますし、こういう不安が出ているのであれば、その辺も検討委員会の中で議題に上げていくことも、説明責任の中の一つになっていくんじゃないのかなと思いますので。","respondent":"青木指導課長","answer":"通学路は学校ができた段階で、通学路の決定ということがありますので、そうしたプロセスもご理解いただければと思います。","id":"exchange-019"},{"speaker":"石田委員","kind":"質問","question":"今、お話が出たのが、いろいろな会で不安が出ているということなので、学校ができてから通学路というお話もわかるけれども、高星委員も言うぐらい、我々も耳にするぐらい話が来ているということは、事前に説明責任として今の検討委員会の中で取り上げてやっていただくことが必要なんじゃないですかということで、何でまた学校ができてというプロセスの説明をされちゃうのかなと。もう一度、答弁を。","respondent":"富田教育改革担当課長","answer":"ただいま小中一貫校の準備委員会の中でも、その問題は当初から認識をしておりますが、ただ子どもたちの学校選択の時期までに学級数、学校規模、募集要綱ですとか、さまざまな急ぎ解決していかなければならない課題がありますので。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問・要望","question":"今の第二日野小学校と遊楽街の話というのは、率直に言ってその地域からは出ませんよ、ちょっと離れると出る。そうしないと、本当に全区募集をやってみたら地域の子どもが中学校に入れないことになったら、それこそ一大事ですから、どこかでシミュレーションをやっていただきたいということと、１３０名の受け皿として中学校５クラスでやれば、その辺のところはどうなんでしょうか、それだけ聞きます。","respondent":"谷田部学務課長","answer":"今年度日野中学校に入学された子ども、それから日野中学校の学区域外の子どもがその他の学校に行かれた状況をご説明申し上げます。昨年１１月１日現在の住民基本台帳の数でいきますと、１９９名が日野中学校の学区域におります。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問・要望","question":"ここは出たり入ったり難しいし、実際には住民基本台帳上１９９名いたのが、一貫校までは他学区に行かない部分が増える可能性もあるわけです。これだけの不安が広がっているわけだから、そこは大丈夫ですということをやるようなシミュレーションも含めて、説得力のあるものをつくっていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"原委員","kind":"提案","question":"行政視察一覧表をいただいたんですけれども、今までこういうふうに行きましたという場所の一覧表なんですね。行政視察をするときにどうやって決めるという話し合いがあったと思うんです。前回、委員長のほうで提案されたと思うんです。全国的にそれを探すのは難しいかもしれませんけれども、鋭意お探しいただいて、私はそういう資料を持っていませんけれども、そういう考えでおります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"ですから、特色ある学校というのは品川区が打ち出しているから、それはそれとして私は視察に加えるし、そのテーマにするのは賛成なんですが、同時にちょっと違った角度で、特色あるというのではなくて全体を底上げすると、横並びと言われてしまうとそれまでなんですけれどもね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"沢田委員","kind":"意見","question":"自然発生的に過疎校なり過少校になったところではなくて、意図的に少人数学級を選んで、その効果をある程度蓄積したり総括をしているようなところがあれば、むしろ教育委員会の皆さんにお知恵を借りたいなと。我々も調べてみたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"高星委員","kind":"質問","question":"全国で５校を研究開発ということで指定をしたと聞いているんです。具体的に五つの自治体はわからないんですけれども、先ほど言った特殊な学校の一つだろうと思うんだけれども、そういうものリンクして、地域的なこともあるでしょうから、もしそういうところにコミュニティスクールというものがあったら、ぜひそういうものも勉強するということでもよろしいのかなと思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中島委員","kind":"質問・要望","question":"今、原委員のおっしゃったことに通じるかと思うんですが、今、小中一貫校をこのようにしても、教師の質というものが非常に大事じゃないかなと思うんです。そうしたところに真剣に取り組んでいる自治体があるかどうか、その辺も見ていきたいなと思うんです。そういうのではなくて、もっと一体感で子どもたちにあたっていけるような、そういう部分を求めていきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田委員","kind":"質問・要望","question":"そういうところを、例えばその方たちが地域に根ざした、もちろん税金を支払って自分が区民でもあるわけで、それに賛同するところの経緯、どういう形でそういうものができてきたのか、これからそういうものが求められてくる時代なんじゃないのかなというのもあると思いますので、そういうものをまず見に行ってもいいのではないのかな、どういうやり方でやっているかというのも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"佐藤委員","kind":"質問","question":"参考のために平成１１、１２、１３年度に行った場所だけはそれぞれ書いてあるんですけれども、大体どういうテーマで行かれたのか教えていただければ参考になると思うんです。","respondent":"鶴委員長","answer":"手元に、平成１３年度以前のものがありませんので、去年の分だけ紹介させていただきましたが、そういうようなテーマになってあります。","id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"それぞれテーマが出て、全部やるというのは無理かもしれないし、あるいは欲張ったらできるかもしれないし、その辺は事務局と正副委員長で、こういうのが考えられるというのを二、三出してもらって、それでやるしかないんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"原委員","kind":"提案","question":"私どもで提案をさせていただきましたので、話をします。今、たまたま視察先の話の中で、部活等々の話も出ていますけれども、それだって積極的に取扱っていけば、特色のある学校となるわけでございまして、どういうものがどうなのかということも含めて、調査研究をしていったらどうだろうかなです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"沢田委員","kind":"意見","question":"私は一貫校に象徴される、学校選択は違うんですけれども、一貫校みたいな希望者を募って、抽選で入るなり何なりして、そこに入れば近代的な校舎で、先生たちも特別に全都的に選んだ先生たちで、教育課程も他とは違った体制で、それはそれで意義があるんですけれども、それ以外の同じ区民の子どもがいろいろ問題を抱えているのはどうなんだろうかと、私は常にそのことを思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"沢田委員","kind":"意見","question":"子どもというのは勉強がわかると喜んで、それだけで勉強が好きになるというのがあると思うんです。だから、一人の先生がなるべく少ない子どもを見る体制というのは大事なのかなと思うので、行き届いた教育を実施する上でいろいろな課題があるでしょうけれども、少人数学級を検討すべきではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"佐藤委員","kind":"質問","question":"具体的にこの委員会の運営に関してテーマを上げて、それを決定してやっていくということになると、今でさえも自民党と共産党から二つ出ているわけです。委員会の日数というのは決まってるわけでしょうし、新たに日程を増やしてやるのか、またそういうことをやる場合に理事者の皆さんが最後まで同席をいただくのか、その辺は委員長は具体的にどういう委員会運営をお考えなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"佐藤委員","kind":"提案","question":"非常にいい提案だと思うんですけれども、ただ一つ心配するのは、文教委員会ということになりますと非常にイデオロギーが絡んでくると思うんです。特にこちら側は。いろんなテーマが出た場合に、イデオロギーが絡んでくる。そうすると、そういったものに対して理事者が答弁というのか意見を求められた場合、非常に困る場合があると思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"佐藤委員","kind":"確認","question":"一つ確認しておかないと、今、委員長は大変いい集約をしていただいたんですが、やはりあくまでも委員側の議論ということであれば、ここは大賛成なんですけれども、それに対して理事者の答弁とか理事者からこういうものを聞きたいということが入ってくると、一線を引いておかないと委員長もやりにくいでしょうし、あくまでもこちら側の議論をするというものを基本にすると認識していいわけですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"原委員","kind":"提案","question":"うちのほうから提案をさせていただいたので、佐藤委員からそういう危惧があるという話がありましたけれども、イデオロギーも一つの方法なんです。いろんな考え方があるわけですから、その中でこっち寄りの人もいるし、真ん中の人もいるし、全然違う考えの人もいるかもしれません。そういう意味では、別にこだわることはないと思うんです。ただ、僕が言っているのは、一つのテーマは決めてほしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"中島委員","kind":"質問・要望","question":"プラン２１がスタートして、私たちがすべてのみ込んでいるかというとのみ込んでいない部分はたくさんあります。私たち意見は意見で述べさせていただいて、また検討委員会があるわけですから、そこにも伝えていただいた。そういう時間を取っていただきたいなと思うんですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"沢田委員","kind":"質問","question":"それは、今、区が提起している条例や予算に対してどうかというのではなくて、むしろ調査研究というスタンスだから、別に区とぶつかるということではなくて、お互いに勉強をしよう、我々も教えてもらうというスタンスですから、あまりぶつかることはないんじゃないかと。私なんかは教育はあまりよくわかりませんから教えてほしいなという気持ちがすごく強いのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/207072?Template=document&Id=4444#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":30719,"voices":101}},{"id":"h14-20020702-5","meetingId":"h14-cm07","date":"2002年7月2日","dateIso":"2002-07-02","committee":"総務委員会","time":"午前１０時０８分～午後３時４３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問","question":"これ以下であっては、あまりにも不当だというものをつけている。したがって、今、お話のあった最低基準の物品に対してといいますか、工事全体に対して、そういう形のものが行われているときに、なぜその中の極めて重要な要素である労務賃金について一定レベルのものができないのかというところについては、どのようにお考えなのかを、ちょっと伺っておきたいと思います。","respondent":"西島経理課長","answer":"最低賃金のお話ですけれども、労働者の賃金を守るためにつくられている法律といたしまして、最低賃金法というのがあります。それからもう一つ、賃金の支払い確保に関する法律というものがあります。これは、当然、遵守されているものだろうと、私どもは考えているところです。","id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"これに、やはりそれぞれの職種、それぞれの実際に行う作業の技術的、技能的な内容、こんなものが加味されて、先ほどおっしゃった労働賃金の内容が、設計労務単価というものが決められているとするならば、当然、その単価の中にはいわゆる管理費用的なものも含まれての中身だと思いますから、一定程度のものは認めなきゃいけないわけですから認めるけれども、労務単価と同じじゃないかもしれないけれども。","respondent":"西島経理課長","answer":"国が一般的な条件で決めるということは可能かもしれませんが、区が個々の条例の中でそれを決めるということは、そういう点で問題があるのではなかろうかというのが、今の私どもの考えです。","id":"exchange-002"},{"speaker":"土井委員","kind":"意見","question":"逆の意味で、これは初めからだめなんだと、検討しないというベースに立つから、そういう発想がすぐに浮かぶんで、問題は、検討はすると、課題、問題はこんなものがありますという形で議論を進めていただけないかと、こういうことを申し上げているつもりなんです。","respondent":"西島経理課長","answer":"区が、発注者と、相手の事業者と一対一の対等の関係で契約を結ぶものでございまして、そこから先の下請けの話まで区の権限が及ぶのであろうかという大きな問題がありますので、先ほど申しましたように、国で制定するかどうかという議論であれば。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"最初の質問に入る前に、今、経理課長が、区民ではない、区民以外の方々の条件の整備についてはいかがなものかという趣旨の答弁ですよね。これって、地方自治法の第２条との関係では違うんじゃないかと思うんですよ。第２条第２項、そこに書いてあるのをちょっと読んでいただけませんか。","respondent":"西島経理課長","answer":"第２条第９項第２号です。「法律又はこれに基づく政令により市町村又は特別区が処理することとされる事務のうち、都道府県が本来果たすべき役割に係るものであって、都道府県においてその適正な処理を特に確保する必要があるものとして法律又はこれに基づく政令に特に定めるもの。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"正確じゃないですけれども、住民とそこに滞在者の健康と安全を保持するという任務がどこかに書いてあると思うんですよ。つまり、私が申し上げたいのは、もちろんそこに住む住民は第一義的かもしれない。しかし、区内で働く労働者、実際に働いている人にも、地方自治体の責務としてはあるということだと思うんです。それはどうなんですか。","respondent":"本間総務部長","answer":"実際に使われている方の生活の安定基盤、安定を図るという意味では、先ほど来、経理課長が申しておりますとおり、国の法律で最低賃金法ですとか、賃金の支払いの確保に関する法律というもので、労働者の最低の生活の確保は図られているという状況の中で。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"そこまでちょっと求めてはないんです。通称、公共工事適正化法と言うそうなんですけれども、参議院で「地域の雇用と経済を支える優良な中小・中堅建設業者の受注機会が確保がされるよう配慮するとともに、建設労働者の賃金・労働条件の確保えが適切に行われるよう努めること」と、あわせて付帯決議がされているわけですけれども、これについては、どういう見解をお持ちなんでしょうか。","respondent":"片田施設担当課長、西島経理課長","answer":"先ほど、経理課長が説明しましたように、基本的には、建物を一つつくるのにどのぐらいの材料がかかるのか、その数量等々をまず積算をして、それに対して、例えば大工を頼むということで、材料、工事ともということで。２点目の質問、適切な方法ですけれども、適正化法を設置された目的ですが、「国と福祉法人等および地方公共団体が行う公共工事の入札、契約の適正化を促進し。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問・要望","question":"答弁を丁寧にはいただいているんですけれども、私が質問したのは単純明快で、先ほど、５０種の設計労務単価の平均が１万９,１０６円とかいう数字を教えていただきましたよね。実際、非常に厳しい水準ですから、ちなみに、加えて聞きたいのは、品川区内の収入の基準、平均どの程度なのかというのを教えていただきたいと思います。〔「公務員の所得」と呼ぶ者あり〕公務員の、ちょっと教えてください。","respondent":"西島経理課長","answer":"例えば、きのうの議案審査のときにお話をしました、中央公園のＪＶを組んだ件ですが、あれも基準で言いますと、ＪＶを組む基準ではございませんけれども、中小企業者、区内業者に発注の機会を増やすということで、ＪＶを組んで発注をするというような努力をいたしまして。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問","question":"ここで言われている問題は、元請け、下請け、孫請け、そういう現場で働いている方々の賃金が一番の問題だと思うんですよ。その実態というのは、調べたことってあるんでしょうか。例えば、きのうたまたま契約案件が数件論議されましたけれども、区としては、こうした陳情を受けて、そういうところは実態調査とかはされないんでしょうか。","respondent":"西島経理課長","answer":"ただ、再三お話ししましたように、労使の関係は、基本的に労働者と使用者が決めるものであるという点、あるいは、区が発注するのは、発注者と受注者との関係で契約を結ぶということで、さらにその下の下請け、孫請けまで、契約上及ぼすことができるということは。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問","question":"さっきの質問で、ご答弁いただかなかったけれども、区内の平均収入。","respondent":"市岡企画財政課長","answer":"区内の勤労者の平均年収について、区として正式な統計は押さえておりませんので、そのことは直接お答えできないんですが、私どもの予算で申し上げますと、品川区の職員の給与ベース額については、ご案内のとおり民間準拠でやっておりますので、記載されているとおり。","id":"exchange-009"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望します。実際、こうして陳情された背景というのは、今の不況の中で大変厳しい労働条件、生活条件ということが反映されていると思うんです。ですから、先ほど、冒頭で申し上げた、地方自治体としてのあり方というのか、役割というのか、雇用の確保も含めて、ぜひ積極的に取り組んでいただきたいと、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"藤田委員","kind":"質問・要望","question":"陳情の趣旨は、よく理解できるんです。私たちの周りでも、やはり現場で働く労働者の方々の声を聞きます。大変さというのはよくわかりますが、例えば賃金を決める場合に、国とか、東京都とか、やはり大きな単位で決めるのが望ましいんじゃないかなと思います。各自治体でそれぞれが条例を決めてやることについては、ちょっと疑問が生じるわけなんです。もしわかっていれば、お知らせいただきたいと思います。","respondent":"西島経理課長","answer":"東京都ですけれども、この条例について、特に制定をするとか、検討をするとかという動きは聞いてございません。そういう考えは持っていないと聞いてあります。","id":"exchange-011"},{"speaker":"藤田委員","kind":"質問・要望","question":"そうすると、こうした陳情が、例えば城南５区で議会に提出されているのか。これは品川区だけに提出をされているのか。もしその辺の動きがわかれば、教えていただきたいと思います。","respondent":"西島経理課長","answer":"目黒区と世田谷区にも陳情が出されて、現在、議会がまだ始まっていないようですので、次のときに検討する、議論すると聞いております。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"陳情項目に関しては、これはとても同意しかねると、私どもは思っております。先ほど、参議院の付帯決議に、関連の人たちの雇用を確保したり、いろいろ条件のことについて配慮しなさいよということがあるわけですから、そういう趣旨を踏まえて、果たして品川区レベルで何ができるのかということ、それから、現在、何をしているのかということをお知らせ願えればありがたいと思います。","respondent":"西島経理課長","answer":"難しい質問ですけれども、契約の際に、強制はできませんけれども、お願いということで、一つは下請けをするときには区内の中小業者を使っていただきたいということ、もう一つは、特別な技能はない無技能者の場合は。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"どんどんしわ寄せが下に行っていることは間違いないわけですから、業界のありように対して、かくあるべしということを言えないんですけれども、何が問題かということを理解していないと、やはり変化といいますか、ある種のよい方向に導くことができないわけですから、そこのところの認識ですかね、そういうものも含めて、いま一歩努力の方向性みたいなものを示していただけるとありがたいんですが。","respondent":"西島経理課長","answer":"建設業法との絡みもありますので、当然、強制とか何とかということはできませんけれども、そういう意味では、委員ご指摘がありましたように、受注者に対して、下請け業者を使うときは、適正な賃金をもって雇用するようにという要望なり。","id":"exchange-014"},{"speaker":"川西副委員長","kind":"提案","question":"それともう一つは、公契約だけの保障というのはどうかということが、まだ私は勉強中なので、そういう意味で、最初に申し上げたように、１回ここで継続をして、もう少し勉強したい。そして、できたら、取り扱いについても、最初の提案も、皆さんお考えいただいて、一たんここで継続にされたらどうですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"強いものが弱いものをいじめるという構図がここに書かれているわけで、対等な契約といっても、なかなか対等といかないというのも、おそらく理解をしているはずですから、弱いものの味方というと、ちょっと言い方がいけないかもわからないけれども、対等になるように、行政としてできることをしていってもらうということを強く要望して、我々は願意に沿いがたいという態度です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"藤田委員","kind":"意見","question":"先ほど、申し上げましたけれども、区でもし制定する場合は、独占禁止法という話もありましたけれども、これはやっぱり問題を含んでいるかなと思います。したがいまして、区として、賃金を確保する条例を制定するということについては、やはり同意できない、このように考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"桜井委員","kind":"質問","question":"もしどうしても多数の方が、本日ということならば、趣旨を生かした採択ということにしておきたい。もちろん制定に向けての検討ですから、この陳情項目そのものを検討してほしいということですから、品川区として、今の公共工事において、孫請けの生産労働者のところまでどういう形できちっと生活保障ができるかどうかということを、もう一歩、二歩進めて政策化していくことも必要ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"土井委員","kind":"意見","question":"したがいまして、その目的に向かって、区がこれから何ができるのかということを検討するに当たっても、条例という観点から適正な賃金が支払われるためにはどうしたらいいだろうかということを検討する上にも、やはり、この条例というものを事例にしながら、どのような対応、態度がとれるのかという検討を十分にしていただくということは大変必要なことだろうと思うわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと確認だけ。時間がないようなので、確認だけしますけれども、これは補正予算が通りましたよね。今、繰越した後の新しい年度に入った報告をするということになっている。そうすると、あくまでも、契約が済んでいると、さっきの賃金の話じゃないけど、契約が済んでいるんだから、それも全部ひっくるめてやれと押しつけちゃうものなんですか。","respondent":"西島経理課長","answer":"特に下を掘るものについては多いんですが、その際には、契約変更の手続をとります。そして、場合によっては期間の変更だけで済むもの、あるいは、金額の変更まで及ぼすものというケースがございまして、今回の場合は、期間の延長だけで済んだです。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"両方とも期間の延長だけですか。さっき、エレベーターのほうは、何かいろいろ柵をつくらなきゃいけないとか、電気を消す作業とか。要するに、期間が延びただけじゃなくて、プラスの仕事が増えているけど、全部済んだんですか。","respondent":"西島経理課長、市岡企画財政課長","answer":"すべて、中のやり繰りの中で済んだです。これは、ちょうど繰越しの本質にかかわることですが、打ち切りましたので、もう１回計上しませんと仕事ができませんので、今のところ、９月補正予算にその特定財源をつけて、荏原第三中学校の夜間照明工事についての予算を。","id":"exchange-021"},{"speaker":"川西副委員長","kind":"確認","question":"すみません、ちょっと確認だけしておきたいんですけれども、この工事というのは、昨年のいつ、契約議案として出されたものか、ちょっと忘れているものですから。エレベーターです。〔「第２回定例会」と呼ぶ者あり〕そのころですね、わかりました。私自身も、議案をいただいているわけですから、結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"続き。この二つは、法で決められて報告をするということになっていて、今の打ち切ったというのは、どういう手続きがこれからされるわけですか。","respondent":"市岡企画財政課長","answer":"ただ、不用額ですけれども、これは予定されていた仕事ですから、決算の中では、一般財源分は繰越金の中に入っておりますので、決算が確定してそれを繰越したことによって、平成１４年度の財源がそれだけ残っておりますので、これを補正予算の引き充てにして。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、お金が入って来ないということで、当初というか、繰越明許をした分の工事はなくなりますよね。それも、この事故繰越しの繰越計算書の中に入るんじゃないのかな。事故でしょ。そうすると、これと一緒に報告すべきじゃないのかな。法にはないんでしょうけれども、決算でしか出てこないということになると、ちょっとおかしいんじゃないか。","respondent":"市岡企画財政課長","answer":"２点あります。これはちょっと予算繰越しの具体的な法律上の問題なんですが、事故繰越しというのは支出負担行為、要するに契約をして、予算の執行に手をつけたんだけれども、その後、やむを得ない事故で破綻してしまったという場合です。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"最後にします。５月３１日までに、入って来ないという状況がわかったと。そうすると、例えば今の校庭の照明というのは、平成１４年度の決算としてなくなったという報告があって、あくまでも３月３１日、平成１３年度の決算書には、繰越明許という決算がされると考えていいんですか。それとも、後から、もうできないとわかったから、３月３１日に戻って、それは打ち切りということにするんですか。","respondent":"市岡企画財政課長","answer":"平成１３年度は、予定していた予算を議決をいただいたにもかかわらず、計画どおりできなかったということで、これは予算が未執行のまま決算をして、できませんでしたという決算上のご報告をするわけです。","id":"exchange-025"},{"speaker":"土井委員","kind":"質問","question":"今までのお話を伺うと、要するに３月で決算をした。その場で決算書の報告等はないけれども、きょうのところは情報提供で、それは入らないからやめにしましたという情報提供をいただいたと。実際上は、決算のときは、あるいはそれを新たにのせた予算のときにやるんですよと、こういうことでよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"桜井委員","kind":"質問・要望","question":"今の件とは違うんですけれども、参考までに聞きたいのは、荏原第三中学校の夜間照明の財源構成なんです。全体で総額幾らかということと、それからこれは国庫補助金ですけれども、単費というんでしょうか、大体、学校の場合は、一定に基づいて補助金なり、負担金なりが来ますよね。もしわかれば、教えていただきたいと思うんです。わからなければ、後でもいいです。","respondent":"市岡企画財政課長","answer":"これは補正予算をお出ししております。それで、補助の予定額は２８２万６,０００円で、非常に補助の額は少ないんですが、工事の中で、補助対象になるものに限られておりますので、こういうことです。これは国庫負担ではありませんで、国庫補助ということになります。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問・要望","question":"最後の地元の協力で、ちょっとはっきり聞こえなかったんですけれども、大井第一と八潮地区では、ご協力をいただいたということなんでしょうか。もしいただいたとしたら、日にちというのか、いつごろというのがもしわかったら教えていただきたい。きょうは口頭でと言いますけれども、何か文書でそういう協力要請というのはされたんでしょうか。地元の協力に当たっての条件とか、話し合いがされたんでしょうか。","respondent":"古川総務課長","answer":"２地区のうち１地区については、地区まで確認してございませんけれども、既に協議会においてご説明をし、了解をいただきましたと。","id":"exchange-028"}]},{"id":"topic-02","title":"の大井町駅東口ペデストリアンデッキスロープ整備工事（その３）","agenda":"の大井町駅東口ペデストリアンデッキスロープ整備工事（その３）","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"スロープの勾配ですけれども、ここに３％と載ってますが、例えば、通常の車いすなんかは２％ぐらいと記憶しているんですけれども、何か根拠があるんでしょうか。","respondent":"市岡企画財政課長","answer":"ただ、路面の材質等を、非常に摩擦係数の大きいすべりにくいものを対応するとか、幾つかの工夫をしておりまして、３％でも、車いすの方に支障のないような設計になってあります。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"質問","question":"工事（その３）となっているんですけれども、幾つまで続くのかというのと、その１、その２についての金額と、落札の業者がわかれば教えてください。","respondent":"西島経理課長","answer":"これは、マツオ橋梁株式会社というところに発注しています。その３が、今回、ご報告した内容でございまして、その４で終わりです。〔「何をやるの」と呼ぶ者あり〕きのう、お話が出ました、橋脚の下の街路灯だとか、導水管等の工事を実施する予定です。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"それぞれ違う工事ということですね。きのう、八ッ山のペデストリアンデッキの話がありまして、あれが６月３日入札、これが６月２０日。八ッ山のほうは、前田道路が落札。いろいろ理由は、きのうお聞きしました。これは偶然でしょうかね。いろいろな理由があったんだけれども、今回も、２６号線につながるし、従来の大井町駅前のペデストリアンデッキにもつながるし、アトレのビルにも接続をしている。","respondent":"西島経理課長","answer":"そうしますと、業者としても、談合した結果、２月なり、４カ月なり指名停止、営業停止ということを食らいますと、ほかでも仕事ができなくなっちゃうわけですから、そういう意味では、そういうことはないだろうというふうに、私どもは考えているところです。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういうことはないというふうに信じていますし、起きないようにも、いろいろ注意をしていただきたい。１点だけ、ここで言う話じゃないと思うんですけれども、これから工事が始まる。４ページの写真がありますね。こっち側からは、きゅりあん側ですっきりしておいたほうがいいんだけれども、反対側は電車から見えるんですよね。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"藤田委員","kind":"質問・要望","question":"私もこの場で言うべきものではないのですが、化粧板ということですけれども、問題なのは、せっかくそうしてきれいにしても、こういう橋にはいたずら書きがつきものなんですよね。もう一つ関係の部署に伝えていただきたいのは、橋の下はおそらく歩道駐輪が考えられます。この２点、関係の部署に伝えていただきたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"桜井委員","kind":"質問","question":"街路４号というんでしょうか、きのう拝見したあそこの脇、あの街路は都道ですか、区道ですか。前回、事故があって、雨水が漏れちゃってかなり大事になったんですけれども、その辺の管理というのか、丸井とかＪＲとか、そこにかかわって接している部分として、結構いろいろと今後の維持、修理というんでしょうか、そういうのは、こういう場合は取り決めというのがあるんでしょうか。","respondent":"西島経理課長","answer":"今の質問は、ペデストリアンデッキは都市計画道路街路４号線になります。ほかのところは、ちょっとわかりかねます。","id":"exchange-034"},{"speaker":"桜井委員","kind":"質問・要望","question":"やっぱり建設委員会ですか、所管が違いますね。では、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-03","title":"みずほ銀行のシステム障害","agenda":"みずほ銀行のシステム障害","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"どうもご苦労さまでした。金融庁と東京都のみずほに対する対応というか、品川区は何をしたのかというのが出てない、みずほにですよ。ここに、いろいろやってますよというのはあったけれども、指定金融機関のみずほという意味からも、区としてどういうことをしたんですか。","respondent":"小野（弘）副収入役","answer":"区の対応のところにありますように、これまで何度も、みずほのほうには説明を求める意味での呼び出しをいたしまして、説明を受けてまいりましたけれども、結局のところ、状況把握が非常に混乱の中で。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"６億２,８００万円ぐらいという話をされていた。それは正確に、これしかなかったということなんですか。あのときの説明では、滞納している人の分だとか、自動振替で、要するに預金額が足りなくても、４００万円ぐらい多く区のほうには入れてくれちゃうというような話になっているから、その分多く入ったんだという話になっていたんだけど、後で調べたら正確に入っていたということなんですか、これは。","respondent":"小野（弘）副収入役","answer":"旧第一勧業銀行分についても引き落としできなかった方が当然いるわけで、その後、正しいデータが出た段階で精算して、その分については返還しているという手続をとっております。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"財政上、一たん区に入ったお金を簡単に返還するとか、そういうことはできるんですか。僕らが余計に税金を納めたりすると、とても手間がかかって戻らないのが、こういうところでは、大ざっぱに６億２,４００万円強のところを６億２,８００万円ぐらいどんと入れておいて、後で多かったから返してよ、返しますよという、そんなに簡単な手続でいいんですか。","respondent":"小野（弘）副収入役","answer":"ですから、区の歳入の中には入れてなかった。雑部金も歳入ですけれども、歳入歳出外現金というところでの扱いをいたしました。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"要するに、お金のやり取りを、そんなにあやふなことでいいわけですか、大ざっぱな概算で。だって、僕らが源泉で取られる、払うでしょ、２月、３月に返還してもらうのにはえらい手間隙がかかるわけですよ、我々は。それが、そんなに簡単に返してくれるんなら、すぐに１２月に返してくれればいいんで、そういう理屈は成り立ちませんか。","respondent":"市岡企画財政課長","answer":"件数は明解ですので、そういう意味では、適正な処理だと考えられます。","id":"exchange-039"},{"speaker":"土井委員","kind":"質問・要望","question":"もう一つは、処理の明細表が出るのがおくれることによって、いろいろと残業だとか、あるいは電算機を別途動かすとか、そういうものがあるんだから、それについてはどう処理をするのかという問題で、たしか、請求をするとかというお話等を伺っておりましたけれども、それがまだ原因云々ということの中で、問題があるのかどうかはわかりませんけれども、その経過はどうなっているのか、どうなるのか。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"そのほかに、今回、ご迷惑をかけたということで、４月分のみずほ銀行に係る口座振替の手数料、それから、公共料金のフロッピーディスクの迷惑をかけた部分について、合わせて１６万９,７２８円、みずほ銀行として。でも、そういう現実の手続が後になっていても、ご本人にとっては納めたのは当然そのときですので、法律上、そういう扱いにするということでやっておりますので、これはきちんとした制度ということで、ご質問にお答えいたします。","id":"exchange-040"},{"speaker":"土井委員","kind":"質問","question":"今、請求をお出しになったということは伺った。それから、４月分については、いろいろあったんで、手数料をただにしますよということがあったと。全額であるかどうかは別として、１６万円余のものを返してもらったということなんですけれども、そうすると、５４万円余の請求だけれども、これはある意味では争いになってもおかしくはないわけで、それはどのようになる見通しをお持ちですか。","respondent":"小野（弘）副収入役","answer":"今回のみずほ銀行の報告の中でも、「大変ご迷惑をおかけいたしましたということで、お客様には十分ご相談させていただきながら、誠心誠意対応します」ということでいただいております。","id":"exchange-041"},{"speaker":"桜井委員","kind":"質問・要望","question":"３番目の区の対応なんですけれども、ここに「報告を求めているが、原因解明には未だ不十分」とありますよね。引き続き調査と言っているんですけれども、先ほどの説明ですと、情報システム課の担当者と区のほうの担当者という説明が若干あったんですけれども、もう少し丁寧に教えていただけますでしょうか。どこの部分が未だ不十分なのか、何を調査しているのか、教えてください。","respondent":"小野（弘）副収入役","answer":"文章だけの説明はいただいているんですけれども、それが、我々がそれでわかったというような文章ではないもので、もう少し図示して、わかりやすく、通常はこういう流れを通るんだけれども、今回は、ここのところが欠落していてこういう結果になってしまったというような。","id":"exchange-042"},{"speaker":"桜井委員","kind":"質問・要望","question":"今は正常というお話なんですけれども、５月、６月は引き落としがされて、前のルートでなっていて、４月の段階だけがそうだという理解でいいのかどうかということ。今の冒頭の話だと、区が持っている施設での公共料金という理解なんですか。もう少し、公共料金の中身について、教えていただきたいんですけれども。","respondent":"小野（弘）副収入役","answer":"ただ、５月、６月につきましては正常に、これまでと同様な形で動いております。","id":"exchange-043"}]},{"id":"topic-04","title":"(7) の不在者投票を送致する投票区（所）の指定","agenda":"(7) の不在者投票を送致する投票区（所）の指定","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"これを説明されて、いろいろな単語が出てくるんですけれども、どの時期にやる作業なのかを言ってくれないとわからない。質問の意味はわかりますか。","respondent":"野田口選挙管理委員会事務局長","answer":"説明が不十分ですみません。これは投票日当日の事務の流れです。告示日から選挙期日の前まで不在者投票が行われます。実務的には、選挙管理委員会のほうでそれを保管しておいて、投票日当日になりますと、いつもですと午後３時ごろ、各４３投票所に送致します。","id":"exchange-044"},{"speaker":"林（宏）委員","kind":"質問","question":"やっとわかりました。左側の「指定投票区制度」というところに書いてある説明ですが、不在者投票された票ですよね。「不在者投票を」と書くからおかしくなる。「票」をでしょ。今までは、不在者投票された票を例えば第１投票所の投票箱に入れてましたよね。今度は、１カ所になっちゃう。さっき言ったように、第１投票所の投票率というのは、どうやって計算を出して発表されていくんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"投票率につきましては、不在者投票については、指定した投票区、第４０投票所で投票録に記載されることになります。したがって、各それぞれの残りの関係投票区につきましては、投票録に記載されないということです。","id":"exchange-045"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、例えば、さっきのところでもいいですが、誕生八幡神社の投票区というのか、そのエリアの人が不在者投票をしますよね。それは投票という行為をされているわけですよね。だけど、投票率に入らないということになってくるわけですか。","respondent":"野田口選挙管理委員会事務局長","answer":"投票録の記載が、指定投票区の投票録に記載されるようになりますので、個別の投票区ごとの部分については出ませんけれども、全体の投票率のところでそれが反映される、そういう形になります。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問","question":"いつも結果が発表されると、第１投票区から第４３投票区まで、男子何％、女子何％、合計何％というのが出て、そのエリアの方々の投票行為というのが率であらわされるわけですよ。それがなくなっちゃうんでしょ。それは、影響あるじゃないですか、影響なくはないじゃないですか。非常に大きい影響ですよ。そのエリアの人々の投票行為が無視されるわけですから。と僕は思いますけれども、いかがですか。","respondent":"野田口選挙管理委員会事務局長","answer":"確かに、そういった側面では影響がありますけれども、全体としての投票率については、当然、不在者投票も入るということです。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"意見","question":"一たん集められて、どこどこから何票の投票があったと。例えば、さっきの誕生八幡から５０通の不在者投票があったというカウントはされているわけでしょ。例えば、荏原第三中学校に行く前に、選管にある状態のときに。","respondent":"野田口選挙管理委員会事務局長","answer":"実際に不在者投票の事務をやるのも、投票時間が延長していますから、そういった種分け、事務量が増大して、そういうことをいちいちやっていたんでは、実務的にちょっと対応しきれないということから、指定投票区制度を設けて。","id":"exchange-048"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりますけれども、じゃあ、カウントをやめようというのが、これが始まった趣旨なわけですか。というふうに、今の答えだと聞こえちゃう。不在者投票して、当日もう１回やるというのは絶対に避けなきゃいけないんだから。パソコンの中に、不在者投票された人は入っちゃっているわけですから、その住所が例えば二葉一丁目だったら、第４投票区とかってカウントはすぐに出てくると思うんですよ。","respondent":"野田口選挙管理委員会事務局長","answer":"一つは、そういったいろいろな選挙制度の変更があって、不在者投票事務ならびに当日のそういった事務を軽減しようというところから、この制度が設けられました。","id":"exchange-049"},{"speaker":"土井委員","kind":"質問","question":"それを、今までは４３カ所にばらまいたと、それを何でわざわざ１カ所に持っていくんですか。そうして、さらにまた一つ違ったのは、今までは、４３カ所で混合していたと。ということは、箱は、今までは４３個だったのが、４４個になりますよということですか。そして、その４４個が混ぜられて開票に回っていくという流れだということで、よろしいかというのが一つ。仕組みだけでいいです。","respondent":"野田口選挙管理委員会事務局長","answer":"指定投票区には、不在者投票用の投票箱を２台置く予定です。先ほど、言いましたように、不在者投票は１万６,０００件を超えていますので、全体の１割を超える数です。そういった意味で、２台設置する。","id":"exchange-050"},{"speaker":"土井委員","kind":"確認","question":"問題は、だから、受理・不受理の基準になるものは、投票されて束になっちゃったと言ったら語弊があるけれども、その段階では、もう受理・不受理の判断はされちゃっているんじゃないですかということを言いたいんですよ。それは、どこまで許されて、どこまで可能性があるのかということの追求と、実態的なものは何か進んでいるんですか。今、ここで直接きょうのことには関係ないのかもしれませんが、ちなみに。","respondent":"野田口選挙管理委員会事務局長","answer":"そのときに、例えば、投票管理者があるとか、抜けているとか、事務局のほうが把握しておく。ただ、渡すときに、もし不受理のものがあれば、現実的にはないですけれども、これは法的に受理できませんという対応をしています。","id":"exchange-051"},{"speaker":"土井委員","kind":"質問","question":"そういう仕組みづくりというものもどこかではやられているんではありましょうけれども、そういう仕組みづくりについて、お金もかかることですから、どうなるかわかりませんけれども、品川区でご発想になって進めていくような形をやっていけば、今言った疑問みたいなものも、かなりすっきりと解消できていくんじゃなかろうかなというものもあったんで発言をさせていただきましたが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"桜井委員","kind":"質問","question":"１点だけ教えてください。当日の開票の報告の仕方というんでしょうか。大体、時間でそれぞれやりますよね。この場合、例えば、指定投票区の荏原第三中学校のところで出されるのは、一緒にするから、そこは問題ないという理解なんでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"４３カ所でやっていたのを１カ所でやるということだけで、その１カ所でやったものを開票所に持って行くわけです。開票所に持って行って初めて、みんな一緒になってやりますので、開票事務そのものについては、従前と変わりません。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問","question":"よく、不在者投票がどのぐらいだということを言いますよね。それはまたそれとして報告するという理解なんでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"指定投票区の投票管理者が、不在者投票は１万６,０００件ありましたということで、開票所の開票管理者のほうに報告するということになります。","id":"exchange-054"},{"speaker":"桜井委員","kind":"質問","question":"要するに、私が知りたいのは、有権者との関係で、それはどういう形で公表されるのかというところです。どのぐらい不在者投票があったかということは、結構、私たちも関心事なんですよね。そこは、有権者への公表はどうなんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"先ほど、統計上、そういったものが出ないかというようなことでしたが、それは出ます。これまでの投票率の投票録、開票録に基づいた部分と、統計上の部分とちょっと切り分けて、今後、検討してみたいと思っています。","id":"exchange-055"},{"speaker":"桜井委員","kind":"質問","question":"難しいことを聞いているんじゃなくて、だから、不在者投票というのは、どういう形で報告されるんですかということです。今の話だと、ちょっとわからない。","respondent":"野田口選挙管理委員会事務局長","answer":"第４０投票所で１万６,０００件不在者投票がありましたというような形で、公的な文書には載ります。選挙の記録もつくりますけれども、それもそういうふうな形になります。","id":"exchange-056"},{"speaker":"林（宏）委員","kind":"質問","question":"一つだけいいですか。上のほうの２行目に、年間五、六万件と書いてあるんですけれども、登記件数の五、六万件というのと、請願に書いてあった謄本等の証明関係１６７万件、どっちのほうが重みがあるというか、数で言うと１６７万件と書いたほうが、そんなにあるのかと受けられる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"土井委員","kind":"質問","question":"どうせ直すんですから、１行目の「品川区総合庁舎に」というのを「庁舎内に」にしておいたほうがいいと思います。４行目と同じにしておいてくださいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"桜井委員","kind":"意見","question":"今の利便性のことなんですけれども、この上に、「万一移転統合が実施された場合、利用者の利便性」ってありますよね。今の助役の指摘も大事だと思いますので、文言はお任せしますけれども。同じ言葉を２回に使うのがどうかなと思いますので、参考までに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"林（宏）委員","kind":"質問","question":"迷惑がかかるというのは、大田区民に迷惑がかかる。品川区としては、品川区の人間がここに行ったときに、不利益になるよということを入れたほうがいいんじゃないですかということ。正副委員長で持って行く。","respondent":"伊藤委員長","answer":"この意見書の文章を確定した後のことにつきましては、その取り扱いにつきましては、検討していきたいと考えていますので、よろしくご理解のほどをお願いいたします。","id":"exchange-060"},{"speaker":"桜井委員","kind":"質問","question":"議会でのこうした意見書を出すという点で、願わくば、行政のほうも、例えば区長名で要請されるとかというのはお考えになっているんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"桜井委員","kind":"質問・要望","question":"きのう、３点について申し上げたところなんですけれども、最初の購入の問題から質問をさせていただきたいと思います。時間の関係で２番目に入りますけれども、財産の関係なんです。これって、私は非常に疑問に思うのは、基本財産の４億７,０００万円というのは、要するに原資は区民の税金だと思うんですけれども、この考え方は間違いだという理解なんでしょうか。とりあえず、そこまで質問したいと思います。","respondent":"濱野助役","answer":"いろいろ経過はありますけれども、現在のところの基本財産というのは、出捐金を受けた４億７,０００万円プラス、財団で独自に資金を充当した３,０００万円、基本財産５億円については、何ら損傷なく現在も保有されているということでありますから。","id":"exchange-062"},{"speaker":"桜井委員","kind":"質問・要望","question":"今の区の関与の関係ですが、私も、運用のあり方も含めて関与していくという理解でいいのかどうかというのを質問したんです。４億７,０００万円は、今言ったように区の原資というふうに確認しているんですけれども、それでいいのかどうかというのを、もう一度お答えいただきたいと思います。それは、運用の基金というか、運用の５割を超えているわけですね。そこのところだけ、もう一度確認したいんです。","respondent":"濱野助役","answer":"やり方はいろいろあって、安全、かつ有利なものということであれしますから、ものによってはリスクであれすることはありますけれども、財団が安全かつ有利な資金運用をするというのは、財団の使命だと考えております。","id":"exchange-063"},{"speaker":"桜井委員","kind":"質問・要望","question":"私が申し上げたのは、運用していくということを否定するわけじゃないんです、もちろん事業をやっていくわけですから。財団のもともとの存在意味というのは、文化を区民に寄与すると。だから、そこのところを、私は、どういう根拠で言っているのかはっきりしていただきたい。それから、先ほど申し上げた後段の質問の原資の部分について、もう１回。それから、区の関与についても質問しているんですけれども。","respondent":"濱野助役、中尾根企画部長","answer":"さっきの３６ページですけれども、「剰余金は」となっていますね。剰余金というのは、例えばいろいろなところに引き当てたり、引き当て金をあれしたり、積立金を積んだり何かして、最終的な剰余金ということです。財団全体の資金管理というものと補助金というものは、直接的に結びついているものではありませんので、したがって、区の関与というのは、補助金、委託金の目的の範囲内でやるという規定になっておりますから。","id":"exchange-064"},{"speaker":"桜井委員","kind":"質問・要望","question":"今回、要するに１億６,０００万円は、非常に元本割れもするし、聞くところによると、いろいろな事例からすると、３５％戻ってくるかどうかわからないという話も一部にはありますよね。それって、実際には、今まで随分もうけてきたんだから、十数年にわたって果実を生み出してきたんだから、遠い目で見れば、それはそれだよとお考えになっているのかどうか、改めてそこはお答えいただきたいと思います。","respondent":"濱野助役","answer":"ですから、財団が創立されてから、約３億数千万円の利子収入というのを得ておりますから、今回のアルゼンチン債による若干の損失というのも、そのスパンの中で考えるべきことだろうと一つ思います。","id":"exchange-065"},{"speaker":"桜井委員","kind":"質問","question":"実際に、今の事業に即支障を来すとは考えにくいと思うんです。ちょっともう時間がないので、後半の部分の質問に入りたいんですが、損害賠償の関係ですけれども、区長自身が損害を全部払えとかどうとかという問題もあるかもしれないけれども、区民に言わせるとそういうふうに言っていますけれども、むしろ区長自身の政治的、道義的責任というのはすごく大きいと思うんですよ。これについては、どうなんですか。","respondent":"濱野助役","answer":"ここが、第１回定例会でいろいろご指摘をいただき、また決議をいただいたことに対するけじめと対応だと考えています。それ以上のことについて、いろいろとお伺いをいただきますので、それは、過分なご質問ではないかという意味でのご答弁であると考えています。","id":"exchange-066"},{"speaker":"桜井委員","kind":"質問","question":"ところが、理事長に報告をしたのは５月ですよね。この１億６,０００万円の損害が出た場合というのは、もうこれで幕引きだと、区は関係ないと、あとは品川文化振興事業団がよろしくやってくれよということなんでしょうか。じゃあ、これで幕引きですかと、これで責任ない、これをもって終わりということなんですか。そこをちょっともう一度、助役ご自身の問題と。","respondent":"濱野助役","answer":"これに対する対応としては、先ほど申しましたように、理事長の辞任と、そして取るべき対応策、基本財産の運用の変更、これをもって一定の対応を取ったという認識です。","id":"exchange-067"},{"speaker":"桜井委員","kind":"確認","question":"これで終わります。だから、そこのところを、私は確認したいんです。だから、いまだもって私が非常に不鮮明なのは、区長は、自分だったら買わないと、だけども、理事長印を押したというところが、非常に不鮮明だという問題と、〔発言する者あり〕だって、責任がいまだはっきりしてないじゃないですか。そういう点で、非常に私は、今後これで終わらないと思いますので、引き続いてやっていきたい。","respondent":"濱野助役","answer":"答弁を求められておりませんけれども、今、委員のご発言の中に、理事長が理事印を押したとおっしゃっいましたけれども、それは訂正していただきたい。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"金額が幾らかかるのかということと、大体、どのぐらいの重さが乗るようになったのかということ。防水シート、防根シートと言われたんですが、やはり鉄の部分といいますか、とめるところから水漏れがしますので、やはりかなり神経を配らないと、今のままだったら見えるけれども、かえって見えなくなってしまうので、そういう心配があります。お答えないんでしょうけれども、そこのところを確かめたい。","respondent":"西島経理課長、片田施設担当課長","answer":"金額ですけれども、屋上緑化そのものでは１,９５０万円で予定をしております。今、ご意見いただきました過重問題と防水の問題、私どもも一番心配であった問題です。過重につきましては、合算しますと、おおむねトータルの重量としては１００ｔぐらいの規模のものを乗せるということになります。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問","question":"過重の件ですけれども、１００ｔで８８８m2だと、１１０kgぐらいですか。２６０kgというのは、場所によって、マックスを２６０kgに収めようという考え方ですか。","respondent":"片田施設担当課長","answer":"したがいまして、３００kgまではもつという計算をしてございましたので、安全上、十分支障がないと判断しています。","id":"exchange-070"},{"speaker":"藤田委員","kind":"提案","question":"予算特別委員会でも、私、屋上ガーデニングについていろいろ提案しました。その中で、缶とか落ち葉等が落下した場合の保険をかけておくべきではないかという質問をしました。その後、どう検討をされているのかということ。今、これだと１ｍちょっとぐらいの塀ですので、子どもがぽんと乗っちゃいますと、すとんと落ちるような形になりますので、その辺、どういう工夫をされているのか。","respondent":"西島経理課長、片田施設担当課長","answer":"保険の件ですけれども、私ども、渋谷区のほうにも問い合わせをしてみましたけれども、なかなか適当な保険がないということで、今年度中に、開設までにはもう少し検討を進めてまいりたいと考えております。ただ、一応、今回につきましては、いろいろ植栽に関しての風の影響とかそういうこともありますので、ラチスという形で、植木屋でよく格子状のものを売ってありますけれども、現況の手すりの内側に。","id":"exchange-071"},{"speaker":"藤田委員","kind":"質問・要望","question":"そういうのはいいんですけれども、子どもというのは、目を放しますとするっと行っちゃうんですよ。現在の檻みたいな塀の内側に、上れないようなものをずっと張るべきだと思うんですよ。わかりますか、言っている意味が。これはそんなにお金がかかるものじゃないと思うんですけれども、ぜひ、検討をしていただきたいと思います。","respondent":"片田施設担当課長","answer":"今、ご意見があったことにつきましては、検討させていただきたいと思います。","id":"exchange-072"},{"speaker":"嶋委員","kind":"質問","question":"ここにキッチンガーデンがあるんですが、屋上緑化というのは温室の効果があって、１カ月ぐらいで収穫がどんどんされるということなんですが、どういうものがされるのか、ちょっとお聞きをしたい。温度計の件なんですが、一応、屋上と階下とは大体３度違うとお聞きしていますが、屋上はいいとして、階下の場合、どこに設置をされて、それを比較をされていかれるのか。","respondent":"西島経理課長、片田施設担当課長","answer":"実施をした後に、どれだか変わるのかと、はかって確認してまいりたいと考えているところです。一つは、道路公園課のほうからいろいろとお話をいただいて、まだ検討中ですけれども、実は、ちょっとした展望台みたいなものを設置したいといったような話がございまして、それにつきまして、今、検討しています。","id":"exchange-073"},{"speaker":"嶋委員","kind":"質問・要望","question":"展望台とかって、もしかしたら、それは完全にプライバシーの問題になるので厳しいかなと思います。食べてきました。最後に要望なんですが、私が行ったところで、見学をした帰りに、季節のお花の種とか、栄養剤をくださったんで、これは業者のほうに言って無料で配布していただけたらと思います。帰りに、ちょっとお土産をいただくのもいいかなと思っていますので、要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"桜井委員","kind":"質問","question":"業者なんですけれども、さっき、鹿島建設とおっしゃっていましたよね。１,９５０万円ですか、どうして区内の造園業者とか、あるいはそれにかかわっての建設関係とかを考えられなかったのか。そうなると、やっぱり技術的にも蓄積されていけば、お互いに需要も高まっていくし、そういう点についてはご検討いただかなかったんでしょうか。","respondent":"西島経理課長","answer":"２点目の区内業者の育成という部分では、私ども、今後、各家庭の屋上緑化を進めていく上で、今まで、区内の業者があまり屋上緑化の実績がないものですので、この屋上をつくるに当たって、区内の業者にここでいろいろなことを勉強していただこうということで。","id":"exchange-075"},{"speaker":"桜井委員","kind":"質問","question":"１,９５０万円ですから、一応、議会のほうには契約案件が出てきませんから、いろいろ意見を申し上げるのはここでしかできないと思うんですけれども、せっかくエコテクノガーデンだけで終わっちゃうというのは、ちょっとさみしいんですけれども、何かその辺の検討というのはいかがでしょうかね。","respondent":"西島経理課長","answer":"委員、ご指摘の区内業者の育成という部分では、これから中小企業センターの屋上もあります。それから学校が５校、屋上緑化をしてまいりますので、その辺の部分では、その辺のことも十分に配慮しながら進めてまいりたいと考えているところです。","id":"exchange-076"},{"speaker":"林（宏）委員","kind":"質問","question":"今の話の続きですけれども、ここを区内の業者というのはとても難しいというのは、僕も聞きました。今、言われているのが、この間、品川区がものづくりワールドに出展をする、１０社ぐらい元気のいい中小企業というか、零細企業もある。これで終わりじゃないわけで、これから始まるわけですから、区内のそういう業者が元気が出るようにリードしていってあげる。それはできますよね。","respondent":"西島経理課長","answer":"委員、ご指摘の考えで、今後、進めてまいりたいと、私ども思っております。","id":"exchange-077"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"管理の面で、例えば雨の日、風の日、冬、それから真夏、どういう形でクローズをするとか。何らのか形で、下で、きょうはクローズですよというのを、ビアガーデンなんかも、大体、エレベーターの入り口で教えてくれるわけですから、そういうこともしていっていただきたい。それから、ちらっとさっき出たけれども、たばこがいけないのは十分にわかりましたけれども、飲み食いはどうですか。","respondent":"西島経理課長","answer":"管理の点ですけれども、オープンしている際には、「本日は、屋上庭園を開場しています」というような表示は、２階、３階にする予定です。","id":"exchange-078"},{"speaker":"川西副委員長","kind":"質問","question":"先ほどの１,９５０万円ですが、これは段差解消とか、施設整備が入っているんでしょうか。一つ伺います。","respondent":"西島経理課長","answer":"入口というんですか、屋上庭園側のスロープについては含まれてあります。ただ、手前側につきましては、庁舎の構造上の問題ですので、そこは私どものほうの小破修理という予算がありますので、その部分でちょっと手入れをすることになります。","id":"exchange-079"},{"speaker":"川西副委員長","kind":"提案","question":"今の確認でいくと、そういう庁舎管理部分を除いて、１,９５０万円でできるというようなイメージで完成を待てばいいわけですね。せっかく一般質問で何回もやっているのに、全然聞いてくれないのかなと思って。理事者は、助役がいなくなってとても残念ですけれども、これは要望でいいですけれども、私はずっと申し上げているんです。それから、嶋委員が提案されている菜園もそうですよね。要望です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"藤田委員","kind":"意見","question":"全国で初めて電子投票をやった、岡山県の新見市。あそこもいろいろ報道されていますけれども、これは一つの案でしょうけれども。具体的にどういうふうな作業でやって、どういうふうな結果になって、どういう点が問題になったのか。その辺も一つの調査。それから、平和事業が総務委員会の所管ですので、平和政策、そうしたところも一つ。都市はどこかに限らず。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"林（宏）委員","kind":"質問","question":"事業部制をとっている自治体ってほかにないんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"桜井委員","kind":"質問","question":"三重県なんかはやってないんですか。最初に行政評価をやりましたよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"林（宏）委員","kind":"意見","question":"北九州とか、滋賀県の何市だっけ、名称は事業部じゃないんだけれども、名前が専務とか部長とか、いわゆる企業の名称を職員につけてやっているというようなことを聞いた。北九州の市長は、行革を非常にあれだから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"桜井委員","kind":"質問","question":"私が希望していいですか。場所はちょっとまだ調べてないんですけれども、ＮＰＯの関係というのは、ここじゃなくて区民部なんでしょうか。区民との協働とか、その辺。〔「区民生活事業部」と呼ぶ者あり〕住民自治とか、住民参加とかになるとこちらになるんですか。","respondent":"本間総務部長","answer":"そうすると、所管がないですよね。全てになります。","id":"exchange-085"},{"speaker":"桜井委員","kind":"意見","question":"広聴というのはこっちですものね。希望としたら、そういうＮＰＯというより区民との協働、市民との協働とか。区民生活事業部にいっちゃうと申しわけないけど、あまりあちらに影響がないような。さっきのボランティアじゃないけれども、これから、区民との協働の部分をどういうふうにうまく進めていくのかということが、ちょっと関心があるところなんです。調べますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/891081?Template=document&Id=1588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":72575,"voices":242}},{"id":"h14-20020703-13","meetingId":"h14-cm07","date":"2002年7月3日","dateIso":"2002-07-03","committee":"清掃・リサイクル特別委員会","time":"午前１０時０５分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"ちょっと基本的なことで最初にお尋ねしたいんですが、今回３件の専決処分ということで、清掃車両の接触事故とかいろいろあるかと思うんですが、これは相手方との関係で損害賠償額決定とか、専決処分になっているかと思うんですけれども、ちょっと違っていれば申しわけないんですが、ほかにも例えば何かそういう、わかりやすく言うと物損事故とか、よくわかりませんけれども。","respondent":"山口品川清掃事務所長","answer":"ただ、それが損害賠償にまでなったかというケースは今まではなかろうと思います。今までのケースでいきますと、ないと思います。","id":"exchange-001"},{"speaker":"上山委員","kind":"確認","question":"それで、今回はこういう３件があるんですけれども、いろいろ見ても、一応車線変更で安全確認を怠っただとか、今のご説明ではそういうのが二つですか、一つはフロントガラスの云々かんぬんというんですけれども、特に安全確認の問題で、ちょっとそうすると、ささいなことで大変恐縮なんですが、今各集積所に時間の指定などをずっとやられておりますし、先ほどのご説明でも、例えば第１５号で言えば。","respondent":"山口品川清掃事務所長","answer":"年末年始作業につきましてはごみが増えるということもありまして、それなりの対策車なりそれなりの手を打って、平常の作業よりも一定の手厚い形での人の配置も、それから車も増車をしていますので、たまたまこれは昨年の暮れの、確かにごみの増量のときだったものですので。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問・要望","question":"これで終わりにいたします。最後に要望なんですけれども、特に年末だとか、そういう増量する場合の根本問題ですね、特に毎年であるかわかりませんけれども、予想はされているときがあったと思うんです。年末だとか。これは要望でとどめておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"辻委員","kind":"確認","question":"ちょっとこの１４号の中身がどういう事故だったのか、もう一つわからないんですね。要するに、車線変更して、後方確認をしたんですね。どういう形。それで、曲がる車、直進する車というのは、左折する場所も空いているもんだから、突っ込んでずっと行くケースというのがあって、時々おまわりさんにつかまったりしているんですけれども、この右後方フェンダーというのはどんな形でぶつかったんですか。","respondent":"山口品川清掃事務所長","answer":"私どものほうの車が速度を落として車線変更を開始をしたところ、キャビン左側の角の付近を相手の車の右後方フェンダー付近にちょっと接触をした、こういう格好ですので。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"幾つかお伺いしたいんですが、先ほどからご答弁の中に、税金といいますか、区の持ち出し額が増えてしまったことのおわびの言葉がありましたけれども、これらの載っている金額以外にも、当然区の持ち出しといいますか、税金を使っているところがあると思うんです。","respondent":"山口品川清掃事務所長、中山清掃リサイクル課長","answer":"相手方につきましての損害が７万円ということで、私どもが８割の責任ということで５万６,０００円、こういうことでございまして、相手方に５万６,０００円、私どもには３万９,７９１円、こういうことで。質問の２点目の雇い上げの車両につきましては、これは契約の中で相手方の賠償および自社の車両の修理についてもそれぞれ雇い上げの会社側が行うという契約になってありますので。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、その雇い上げの部分に関して、仮に区が負担していたとするならば、逆に言うと、雇い上げの車両が事故を起こしても、先方の負担でなくて区の負担だからとして、安全運転を怠ってしまったのかなという思いがあったんですが、そういうことはないということですから、それは理解しますが、非常に多いということと、あとこれは区の庁有車が起こしてしまった事故ですが、逆に先方から。","respondent":"中山清掃リサイクル課長","answer":"ちなみに移管後、平成１２年度ですけれども、被害事故としてやはり３件あります。加害事故も同様に３件という形になっております。被害事故については、これは報告するという形にはなってございませんけれども、ほぼこの３件ぐらいの被害が出ているということです。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"繰り返しになって大変恐縮なんですが、受ける側としては防ぎようがない部分はあるかもしれませんが、加えてしまう、相手を傷つけてしまうことの対策というのはさらに、今まで強化されていたにもかかわらず起きているということで、より徹底をお願いしたいと存じます。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"藤原副委員長","kind":"質問","question":"１点お伺いしたいんですけれども、この３件の賠償額というのは、区が区のお金を使って払うんですよね。決まった金額ではなくて。そうすると、これは損害保険とかで払うのではなくて、区が区の予算で払うわけですよね。","respondent":"山口品川清掃事務所長","answer":"私どものほうの車両につきましては、一応任意保険に加入しておりますので、保険からほとんどは補てんをされる、給付されるという。ただし、保険会社の契約の中で、これは免責３万円がありますので、３万円を差し引いた残りについて補てんをされる、こういう形になります。","id":"exchange-008"},{"speaker":"藤原副委員長","kind":"質問","question":"そうすると、例えばこの１６号だと賠償額が１１万２,９４６円ですよね。これから３万円引いた額が保険会社が払ってくれて、３万円は区が払うということですか。","respondent":"中山清掃リサイクル課長","answer":"逆に３万円を超えて払っても、区の保険会社への支払いは３万円。今回のケースですと１万６,２０９円を品川区が保険会社のほうに後ほど免責後に払うという形になります。","id":"exchange-009"},{"speaker":"辻委員","kind":"質問","question":"この横の表で、区名を教えていただければ。それからもう一つは、１区当たり２億円から３６億円とかいうけれども、例えばこれは品川区だったらどうなるんですか。わかりますか。","respondent":"中山清掃リサイクル課長","answer":"品川区の負担ですけれども、ここは非常に大枠での出し方になっているので、品川区でどうなるのかというのは明確に示されておりませんが、大体品川区というのはすべて中間だというふうに考えていただければ、この中の中間がほぼ品川区になると思っていただければ間違いありません。","id":"exchange-010"},{"speaker":"石田副委員長","kind":"意見","question":"この報告は報告で非常に読ませていただいてわかるんですが、先ほど来、秋とかここには１ページ目にすごく基本的な考え方というところで１番、２番、３番という形で出てきて、これが結果的に２３区のこの清掃一部事務組合に対して、解散という決められた問題がありますよね。これにはどういう影響があるかということをちょっと。全体的に。","respondent":"中山清掃リサイクル課長","answer":"地域処理の検討の前提が崩れると申しますか、一たん整理をしないと、そういう工場はもう必要ない、構わないと言いながら、地域処理だけを進めていくというのはちょっと前提が違ってきているんではないか。","id":"exchange-011"},{"speaker":"石田副委員長","kind":"意見","question":"今のところなんですけれども、そこは非常に大切だと思って聞いているわけですけれども、逆に言えば、じゃあその論議をしたくないために、ずるずるとさっきの８区ではない区も出さないでいくと。そうすると、解散をしない方向が望みであるとするならば、そういう論議に乗ってこないほうがいいわけですよね。そういう可能性というのはあるのかないのかということだけ一つお聞かせください。","respondent":"中山清掃リサイクル課長","answer":"したがって、その結論が確かに今年度中にどっちに行くかというのはまだ非常にわからない部分がありますけれども、品川区としては、こういう地域処理の検討を非常にペースを上げてやるべきだという機運が出てまいりましたから、そういう中で従来どおり着実に。","id":"exchange-012"},{"speaker":"石田副委員長","kind":"意見","question":"これでやめますけれども、この委員会がまず持たれたときに、東京二十三区清掃一部事務組合の項目を１番にしたというのは、多分そこら辺の要因があったから、今年１年の中でこの委員会の中でそれを勉強しようよということを、検討しようよというところが、これは出てきたと思いますので、これは後で委員長ともよく話し合いをしますけれども、方向性というのは非常に大切な年だなと考えていますということだけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-02","title":"続きまして、(5)の自治会館（仮称）の建設計画","agenda":"続きまして、(5)の自治会館（仮称）の建設計画","exchanges":[{"speaker":"上山委員","kind":"質問","question":"ちょっと最初に１点お尋ねしたいんですが、私も３年目で、ちょうど３年前に自治制度調査特別委員会にいまして、ちょうどこういうことが出されていた時期だったんですけれども、ちょっと工事費のところでなんですけれども、１４６億６,５００万円ぐらいだとここに書いてありますが、先ほどの説明の中で、私も何か宝くじの云々かんぬんのいうように聞いて、何かそこら辺がよくわからない。","respondent":"古川総務課長","answer":"この団体がそのままここの入居予定に入ってありますけれども、東京都のほうで、昭和５０年に公益法人としてこれが発足したわけなんですが、この協会の主たる業務が、先ほどの施設では宝くじの益金を有効に活用していくわけなんですが。","id":"exchange-014"},{"speaker":"上山委員","kind":"質問","question":"直接区の持ち出しではないということでわかったんですが、その辺ちょっとお尋ねなんですが、先ほど来議論になっておりますけれども、清掃一部事務組合が予定では平成１７年度末、平成１８年３月ですか、一応解散という方向の中で、今課長の説明の中でも、建設スケジュールの中で平成１７年６月の入居ということを予定されていて、平成１８年の３月ではいつまで、入ってすぐ出るというような。","respondent":"古川総務課長","answer":"先ほど申し上げた平成１２年の基本的な実施計画が前提で実は動いておりまして、その後の大きな動きと言いますのは、先ほど申し上げた基本計画は実際として昨年の４月。","id":"exchange-015"},{"speaker":"上山委員","kind":"意見","question":"ちょっと最後に１点だけ、感想的な話で恐縮なんですが、今、全体ではほとんどこういう方向で動いている中で、余りあれこれ私も申し上げるつもりはありませんけれども、全体ではお金もかなりの金額ですし、今、国とかそれから東京都も、品川区は財政は何とか今のところ大丈夫でしょうけれども、かなりあちこち全体では赤字だということで言われている中で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"私も自分が所属していた委員会の中でこれが議論されていることの記憶があることは、これは今回インテリジェントビルにしたという話がありまして、何かそのときの話は、なぜそこまで費用をかけてインテリジェント化するのかと言ったときのご答弁が、外部の団体といいますか、そのときは主に民間という想定を言っていたんですが、入居しやすい、利便性を考えて、利用しやすい形にすれば。","respondent":"古川総務課長","answer":"もう１点は、ＩＴ技術に対応できるような情報通信システムが可能な建物ということで、極めて急速に今進んでおりますＩＴ技術、将来の高速大容量の通信にも対応できるように、ビル内幹線ラインへの光ファイバールートの確保等もその中で考えるという中で、それを具体的な形で計画。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"そうすると、ほとんど身内が入居するのであれば、そこまで費用をかけて利便性をＰＲする必要もなかったのかなという一方で思いもありますが、ちょっとまたこの当委員会にかかわるところでお伺いしたいんですが、この清掃一部事務組合を設立、平成１２年４月１日という部分が、職員の方が１,５００人でスタートしたということなんですが、その入居時、平成１７年、現在でもいいんですが。","respondent":"中山清掃リサイクル課長","answer":"清掃一部事務組合に関するご質問ですので、私がお答え申し上げます。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"ですから、その入居が平成１７年６月で、解散予定が平成１８年３月ということなんですが、我々としてはその時点でもう当初の約束どおり解散ということの思いがするんですが、先ほどの議論もそうなんですけれども、何かこう、ずるずるそのままこういう既成事実がどんどん積み重ねられてしまって、場合によっては３,５００m2ですから相当スペースがあるので。","respondent":"古川総務課長","answer":"それで、もちろん今後清掃一部事務組合がどうなっていくかということが極めて関心の大きい部分ですので、それにつきましては清掃一部事務組合のあり方、これが具体的な形で、清掃一部事務組合が６年間で解散というのは一定の条件が整った場合というのがありますし。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"よくわかりました。ぜひ平成１８年３月には引っ越しをすることを望みつつ、質疑を終えたいと思います。ちょっと素朴な質問なんですが、区長部局と議会は車の両輪ということで対等といいますか、言われている中で、区長会事務局が３５０m2で議長会の事務局が７７m2ということの、何かそうなったことの議論というのはあったのでしょうか。その点だけちょっと。","respondent":"古川総務課長","answer":"区長会事務局と議長会事務局での職員数は違えば違うんですが、区長会事務局は一応想定で２５人、議長会事務局は１５人ですけれども、いわゆるスペースの部分と、一定の共用できる会議室等の部分をどちらにより持たせているのかなということだと私のほうで考えてございまして。","id":"exchange-020"},{"speaker":"辻委員","kind":"質問","question":"今の関連でちょっとお伺いしたいんですが、２３区の清掃一部事務組合は今、四谷の国保連ビルに入っている。これは幾らぐらい費用を。家賃ですか。それはいつまでの契約なんですか。","respondent":"中山清掃リサイクル課長","answer":"年間賃貸料約３億円ぐらい払っております。これは基本的には単年度契約をしておりますから、毎年契約更新をしているものです。","id":"exchange-021"},{"speaker":"辻委員","kind":"質問・要望","question":"もう一つ確認ですが、この総工事費の１４６億円、宝くじと言いましたね。その仕組みをもう１回ちょっと教えていただきたい。要するに、振興協会のほう、宝くじのお金が入ってくる。その毎年こう実際に宝くじやっていますよね。それをこれも同じような単年度みたいに分配してしまうやつは、要するに、このどういう形で１４６億円が出てくるようになっているのですか。","respondent":"古川総務課長","answer":"その基金が先ほど約６００億円ということで、この基金については本来各市町村に個別の配分は難しいようですが、全体の利益と申しましょうか、いわゆる研修所の建設でありますとか、自治会館の建設、いわゆる共同取得の扱い。","id":"exchange-022"},{"speaker":"辻委員","kind":"提案","question":"というと、この１４６億円というのはもらいっ放しでいいわけですか。それは２３区だけではないと思う。ましてこれは先ほど話があったように、たった６カ月の間にひょいと飛び出していくようなものの提案とか、計算して、これは返済しないからいいやという、そういうどんぶり勘定みたいな印象をものすごい与えるんだけれども、いいのかなというような。それを何で考えないんですかね。その辺はどうなんですか。","respondent":"本間総務部長","answer":"こういうような言い方といいますか、説明を私どもは聞いているところでございまして、ただ、感情的には先ほど来ずっと出ておりますとおりに、なぜこんな短期間なのにわざわざ引っ越して入ってくるよりは、さらで新しいところに新しいそういうテナントを募集して入れたほうが。","id":"exchange-023"},{"speaker":"辻委員","kind":"質問","question":"その金が今８,０００万円だというけれども、そんなのすぐすっ飛んでしまうお金じゃないですか。建設費も要するに返す必要もないし、もらえるというのだったら、それだけになったらその分は金もうけして、より今度は２３区のプラスになる金等に使えるようになるようにしたほうが、もう一遍それはちょっとお考えを、その辺の多数派工作をやってもらいたいと思うんですけれども、いかがなものでしょうか。","respondent":"本間総務部長","answer":"ただいまのご意見は、私ども全く同じ思いですけれども、約束の期限内までは、先ほど来清掃リサイクル課長のほうも説明しましたとおり、約３億円弱のオフィス代が負担として出ているということですから、オープン当初はそれとの行ってこい、やりますとあれですけれども。","id":"exchange-024"},{"speaker":"藤原副委員長","kind":"質問","question":"今の辻委員と理事者の質疑を伺って、私も３年前に自治制度に出させていただいたんですけれども、そのときに確か菅家議員が副委員長だったと思うんですけれども、辻委員がおっしゃったことと全く同じことをこの副委員長の席に座られて、なぜ清掃一部事務組合は解散されて出ていくにもかかわらず入れるんだと、入るんだと。","respondent":"松本環境清掃事業部長","answer":"それで、特に清掃一部事務組合の難しい面は、２３区共同で運営をしております。それで、ご承知のことかと思いますけれども、このいわゆる一部事務組合制度は区および２３区議会の全員一致の可決でもって構成をされております。逆に解散もそういう形でなければできない。","id":"exchange-025"},{"speaker":"藤原副委員長","kind":"質問","question":"同じことを考えていますと。だけれども、２３区で構成されて決めていることなのでご理解くださいとご答弁があったと思うんですけれども、ほんとうは今さら聞いてはいけない質問なのかもしれませんけれども、であるならば、清掃一部事務組合というのは、解散するというふうになっていますよね。条文に出ていますけれども、改めて聞きますけれども、２３区の合意が得られなければ、解散はされないんですね。","respondent":"松本環境清掃事業部長","answer":"不燃だとか、粗大。あるいはし尿は残ります。それは共同処理ということで、特に附則の条件がついてございません。そういう意味で、自治法上の制度ですので、大変働きかけをするにも２３区がやはり納得できる案をつくり上げなければできないだろうと思っています。","id":"exchange-026"},{"speaker":"藤原副委員長","kind":"質問","question":"構想の面で一つお伺いしたいんですけれども、これは屋上は屋上緑化されるんでしょうか。","respondent":"古川総務課長","answer":"高さが９８メートルのこのところですので、ちょっと通常の屋上緑化は今のところ予定されていないところだと思います。ちょっとそこまで確認はしてございませんが。失礼しました。","id":"exchange-027"},{"speaker":"石田副委員長","kind":"質問・要望","question":"もういろいろ先ほどからお話が出ているので、ちょっと確認だけしたいんですが、１点目は、この清掃一部事務組合でいろいろ会議を区長会だ、部長会だとされておりますが、先ほど８区の話も出たけれども、この会議というのは基本的には非公開か、公開か。それが１点。３点お伺いします。","respondent":"中山清掃リサイクル課長、古川総務課長","answer":"１点目の清掃一部事務組合の会議に関する部分でご説明申し上げます。それと、１２階部分での乗換階の関係ですけれども、私どものほうで聞いている限りですが、一応１２階までのエレベーター、要するに中層階用エレベーター、それから高層用エレベーターという二つの切り分けが。","id":"exchange-028"},{"speaker":"石田副委員長","kind":"質問","question":"それと、あと会議なんですけれども、基本的には議長は委員として出ている、区長もその一員ですけれども、区長会で話すのも公開で、全部表に出していいという話でいいんですか。","respondent":"松本環境清掃事業部長、古川総務課長","answer":"それで、一組議会につきましては、各区の議長が構成メンバーとなっております。これは一般の自治体の議会と同じ扱いです。委員会等を含めて公開になってあります。その結果として、これはちょっとご質問のお答えになりませんが、一般用のエレベーター８台を設置することとし、ちょうど中間的なところで１２階を乗換階として、高層階用４台、中層階用４台に割って、運用の合理化を図っている。","id":"exchange-029"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１点だけ要望しておきますけれども、協議会のほうの非公開という面は、ぜひぜひこういう話が持ち上がっている、盛り上がってくるのであれば、公開できるように働きかけをしていただきたい。反対しているところが自分の意思を明確に出せるような、そこが結局非公開だとわからなくなっちゃうわけじゃないですか、話をしていて。各区の態度を明快にしていただけるように、要望していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-03","title":"次の案件ですが、次に、(6)の品川区廃棄物減量等推進審議会の中間まとめ（答申）","agenda":"次の案件ですが、次に、(6)の品川区廃棄物減量等推進審議会の中間まとめ（答申）","exchanges":[{"speaker":"川西委員","kind":"質問","question":"推進審議会の、この４回開かれたときの資料は一般的に、要求すればいただくことができるのかどうかが一つ。それから、最近の不燃ごみの量の推移はどのようですか。増えているのか、減っているのか。全体的なごみの量が減っているというのは、先ほどからずっと聞かされています。","respondent":"中山清掃リサイクル課長","answer":"３点目の事業者の役割の部分は、確かに区でどれだけ働きかけをやっていくとご提言いただいておりまして、今までも例えば区長会というチャンネル、あるいは東京都を通じて国への要請等という形でやってきておりますけれども、区の単独ではなかなかやれる部分が限られておりますが。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"それと、事業者責任の関係、こことの関係の事業者責任なんですが、このまとめには随分事業者責任というのが、この委員会の諮問の中でそれぞれの役割分担と位置づけているだけに、事業者責任にも随分言及していて、今までにない、一歩前進しているかなという認識は持つんですけれども、しかしながら、ペットボトルのところについてはこれからやっていくというふうなところではあるんですけれども。","respondent":"中山清掃リサイクル課長","answer":"これはやはり今でもそれだけ集まってしまうと、事業者が最終的に負担する額が上がっていくということになるので、例えば紙製容器などの構造をできるだけ１ｇでも軽くするような技術開発を始めているとかという動きは、ゆっくりではありますけれども動いてきておりますので。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"一番最初に聞いた、減らす努力のところでの問題ですけれども、ご答弁では、テナント３,０００m2以上のというご説明をいただいたんですが、私がちょっと質問した趣旨は、例えばワンルームマンション等に入居される方々に対する、そういう方々への働きかけを、なかなか自治体との接点がないような、そういう世界の方たちへの働きかけも含めて。","respondent":"中山清掃リサイクル課長","answer":"しかしながら、これは近隣の方、地域として、そういうルールを守らないごみ出しをするような方がいる場合に見守っていく姿勢が、ある種かなり行政がやるだけではない有効な手だてという部分がありますので、こういった場合は。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"ですから、もう少しこう、何というのかしら、角度というのかしら、変えたような大きなところでの働きかけが必要じゃないかなというふうに思ったものですから、私としては一番最初にちょっとその点が、入居のときに指導をするとか、あるいはそこにチラシをきちんと届けるとかというふうな、業者の方々のご協力もいただかなくてはいけないわけですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"嶋委員","kind":"質問・要望","question":"二つお聞きをしたいと思います。この審議会で乾電池の件は出たんでしょうか。もし出たのならば、そのお話を聞かせていただきたいと思います。ですから切ったりしますけれども、ほとんどの方が普通に捨てているようなんですが、果たしてこれは、ラミネート加工というのはどうしたらいいのでしょうか。教えていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"１点目の、審議会の中で乾電池の処理そのものについての論議は基本的にはされておりません。ただ、危険物の処理というものについても現状のままでいいのかということで、検討する余地があるんじゃないかという発言はたしかあったかというふうに思っております。","id":"exchange-035"},{"speaker":"嶋委員","kind":"質問・要望","question":"ですから、この包装のいわゆる周りの段ボール、紙の箱を紙質を薄くしていただかないと、たまにごみが出されて、そのままの形で出ているんですが、ほんとうに地域でほとんど出している方たちが、私は最初それは実に手を省いて出しているのかなと思ったんですけれども、やっぱりお年寄りは自分でばらすことができなくて、しようがなくてそのまま出していることが最近わかりましたので、ぜひ紙質を薄くして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"今回の中間の報告は、分別収集計画の見直しの中間報告で、分別収集のことがここで本文で書いてありますが、「はじめに」のところでもありますように、分別収集する目的としては、最終的には資源の有効活用の確保という言葉になると思うんですが、これら分別収集されたものが、じゃあ有効に今後、ちょっと今回のテーマとそれてしまうのかもしれないんですが。","respondent":"中山清掃リサイクル課長","answer":"その一つとして、このカレンダーですが、あるいは前々回に当委員会でもご報告した子ども向けにごみリサイクルの冊子をつくったんですけれども、これはもう少し進めてゲーム形式で、こう集まったものがどうなっていくかを少しクイズ形式で考えてもらおうとか。","id":"exchange-037"},{"speaker":"本間委員","kind":"質問","question":"これは大きなコンビニエンスストアだとかがかかわる、そういう規模のきちんとした営業主体ならばそういうことはないんでしょうけれども、飲み物の自動販売機の脇というか周辺に、その飲み物の空き缶あるいはペットボトル等のいわゆる受け皿となるような入れ物が設置されるべきというか、設置されることが義務づけられているのか、努力的なものになっているのかというようなことについて。","respondent":"中山清掃リサイクル課長","answer":"２点目の、自販機の脇の回収容器等につきましては、これは結論から言えば、義務づけはされておりません。ただ、自販機協会の申し合わせとして、できるだけ周りに回収箱を設置するように自立的に業界の中で申し合わせをしているというところです。","id":"exchange-038"},{"speaker":"本間委員","kind":"質問","question":"なぜかというと、最近カラスが、カラスは減っておりませんですから、防鳥ネットなんかで防護されたところはカラスはよけて、別のところに集中的に行くようになります。しかし、清掃事務所の方は、それでもきれいにお持ち帰りをいただいているという姿を見ているんですけれども、その辺は非常に難しい部分かもしれませんが、どういうふうに理解したらよろしいのでしょうか。","respondent":"山口品川清掃事務所長","answer":"先ほど清掃リサイクル課長のほうからもご説明いたしました集積所につきましては、現在の集積所は、一応そこの集積所をお使いいただく世帯の方たちにご説明をして、お話をして、了解をとった上で集積所を設置してまいりました経過があります。","id":"exchange-039"},{"speaker":"本間委員","kind":"質問","question":"結局この中身を見ている中で関連する問題だというふうに思ったものですから、大変すみません、時間をとりませんが、あともう１点だけ。結局、この中身につきましては、全体のごみとしては何か微増というような、余り減っていないという言い方をされましたね。減ってはいないと思うんです。そうしますと、掲示のきちっとないところは指定された集積所ではないという理解でよろしいのでしょうか。","respondent":"中山清掃リサイクル課長","answer":"最初、私が自然発生的にと申し上げたのは、今の集積所の設置された経過を考えていくと、おさまるところにおさまってきたという意味でということで、この後も自由自在に出してもいいということでは決してございませんし、基本的には集積所と定められたところについては。","id":"exchange-040"}]},{"id":"topic-04","title":"続きまして、第７番目の品川区分別収集計画（平成１５年度～平成１９年度について）","agenda":"続きまして、第７番目の品川区分別収集計画（平成１５年度～平成１９年度について）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"それで、その点では６のところの廃棄物排出の抑制のための方策に関する事項、ここのところ、５点ありますけれども、やはりここがいかに実行されていくのか、具体化されていくのかというところがすごく大事だと思うんですけれども、そういった意味では、私はもう一つにはごみの減量を区民の方に訴えるに当たって、区民の皆さんがわかりやすい目標というんですか。","respondent":"中山清掃リサイクル課長","answer":"さらなる啓発のということですけれども、手段としては、東京都自体から比べると移管された清掃事業についてのＰＲというのは、区のほうはかなりきめ細かに持っているかと思いまして、逆に言えば、十分まだこれを使い切っているかというと。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほんとうに日ごろいろいろな、ほんとうに子ども向けの冊子もとてもよくできているんですよね。だから、こういう面も子どもに限らないで、私なんかもすごく勉強になっているので、ほんとうに活用をできるようにしていただきたい。ほんとうにできるだけ区民の皆さんが受け身ではなくて、自分もやってみる、参加型の啓発の仕方をぜひぜひ追求していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"だけれども、こういう子ども向けのパンフレットをつくって、小さいときから教育をしていくということは、それはそれでほんとうに大事なことだから大歓迎ですし、ぜひそこはそこで進めていただきたいけれども、一方で育っていった大人の大量に排出する側の教育というか、そういうことも実践的にしていくということが大事だというふうに思うので、今どういうことを具体的にやっていただいているのか。","respondent":"中山清掃リサイクル課長","answer":"したがって、やたらに回数を広げてというのはできない部分がありますけれども、こういう学校では環境学習を充実させようという動きも出てきていますから、それをまずとらえて、ある種効率的な中でそういった体験の機会も増やしていくような努力はしていきたいと思います。","id":"exchange-043"},{"speaker":"辻委員","kind":"質問","question":"この中で、３ページのところにこの表が右と左に分けてありますよね。これはこの分別し、その収集をやっていこうとすれば、これはいつも言われているじゃないですか。それにじゃあ課長の、区はそういう言い方はするんですか。びんと。だから、中身をどうなんだという点は、それは二重に、三重の袋でなくてもいいじゃないかという意識をやっていくとすれば、だって出てくるじゃないですか。いかがですか。","respondent":"中山清掃リサイクル課長","answer":"ここの表現は、確かにそういうことも踏まえてこれでいいのかというのは、少し今後検討する余地があるかなという認識はさせていただきましたが、言わんとするのは、容器包装リサイクル法に基づく品目は十幾つとかなりますけれども、集める際にどういうふうにするかということで。","id":"exchange-044"},{"speaker":"石田副委員長","kind":"意見","question":"簡単に言えば、それがお金ではなくても、その商店街の中でどこかに行ったら、ここに行ったら例えばおにぎりが１個もらえるよとか、そういうのを商店街と連携しながら、そういう商店街の活性化に一つ寄与するような、そこにおにぎり１個出す費用というのは商店街がこういう活動をしてくれれば、こういうお金はこういう制度で活用してくださいとか。","respondent":"金井環境課長","answer":"そういたしますと、一定の区民の役割、事業者の役割というものを区としてもある程度打ち出していきたいと考えていますので、そういった中では、ごみも減量も含めまして、各家庭でのリサイクルの問題、それから省エネ、省資源。","id":"exchange-045"},{"speaker":"石田副委員長","kind":"意見","question":"それは非常にわかるんですが、これを見ていても、例えば回収量の見込みというのは必ず出ているわけですよ。こういうふうに増やしていきたいということが出てきているわけですね。これを増やすにはどうしたらいいんだというふうに必ず何かお考えがあろうと思うんですね。よくよく見ると、これを週１回だとか、その週１回にすることがどれぐらいの効果があるの。","respondent":"中山清掃リサイクル課長","answer":"したがって、この辺をもう少し費用対効果というところを明確にしていく必要はあろうかと思いますけれども、片やコストだけがすべてじゃないという面もあって、これはコストを多少、さっき環境課長も言ったような慮外視しても。","id":"exchange-046"},{"speaker":"田中委員","kind":"意見","question":"今回にかかわらず、区のいろいろな事業の中にさまざまな形で基本計画だとか長期計画、いろいろな計画があるんですが、区に清掃事業が移管されたときに、これは一般廃棄物処理計画というのができまして、それは廃棄物の処理及び清掃に関する法律の改正に基づいてと、区に移管という平成１５年の改正により計画をつくったわけですが。","respondent":"中山清掃リサイクル課長","answer":"ただ、数値を見たときに、すべてが突合して一緒になるかということとは別ですけれども、いわゆる法に義務づけがあるなしにかかわらず、一定の統一性、整合性を図っていきたいと考えています。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"個々にまたどんどんこういう形で追加されるとなると、清掃事業は一体体系としてどうなっているのかというのが、整合性の問題もそうなんですけれども、明確性がわかりづらくなる危険性が出てくるのかなという思いが少しありましたので、ちょっとお伺いさせていただきました。ですから、そういう意味では、体系を見据えた上でのわかりやすい事業を進めていただきたいなと要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"藤原副委員長","kind":"質問","question":"一つだけお伺いしたいんですけれども、このステープラーの針なんですけれども、ステープラーの針をとめている資料と、とめていないでこうなっている資料がありますけれども、これはステープラーの針でとめるのは枚数が多いからしようがないとか、何か同じ日に出てきている資料なのに、ステープラーの針とこの紙のでやっているのの差といいますか、何か根拠があるんでしょうか。","respondent":"中山清掃リサイクル課長、土井委員長","answer":"できるだけ針を使わない資料を私としては心がけていきたいと考えています。以上で本日予定いたしましたすべての案件が終了をいたしました。これをもちまして、清掃・リサイクル特別委員会を閉じます。ご苦労さまでございました。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/815229?Template=document&Id=5668#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":63037,"voices":119}},{"id":"h14-20020704-14","meetingId":"h14-cm07","date":"2002年7月4日","dateIso":"2002-07-04","committee":"行財政改革特別委員会","time":"午前１０時０４分～午後０時１４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"何点かお伺いしたいと思います。定数の考え方の基準を教えていただきたいんです。例えば、一つの仕事を３人でやるとか、現業ですから当然ありますね。木の伐採を２人でやるとか、その基準をどういうふうに考えているかということが一つ。それから、当然仕事の内容が機械化、省力化されていくことがあるはずですから、その考慮しつつ定数を考えているかということが一つ。","respondent":"桑村人事課長","answer":"ただ、作業等につきましては、やはりある程度の業務につきましては民間の方をという発想から、現在の作業についての定数は、むしろ緊急時の対応ですとか、地域での陳情対応ですとか、実際上の作業業務というよりもう少し付加した業務を入れて。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば、トイレの清掃、樹木の伐採等々、これは冷静に考えていけば民間のノウハウのある方がやっていただければ、十分カバーできるはずなんですけれども、そういう方向性といいましょうか、考え方はどうでしょうかということが一つ。それから、執行部の皆さんですから、すぐには身分は難しいと思います。それが果たしてどうなのかということを教えていただきたい。","respondent":"桑村人事課長","answer":"過員につきましては、所管のメモにもありますけれども、土木作業につきましては異動の場所があれば、そういった方策を検討したいです。条件につきましてはこれからですけれども、十分検討に値すると考えています。それから、新規採用とのバランスです。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"公園の具体的なトイレの清掃とか云々の民間はどうでしょうかということについてのお答えがありませんので、最後にお答えをいただきたいと思います。それから、私たち議会で思うのは、確かに品川区の職員定数は間違いなく減っています。結果、これだけのマイナスがあったというほうが説得力があるんじゃないかという気がしますので、それを後で教えてくださいということを要望しておきます。","respondent":"桑村人事課長","answer":"先ほど公園の清掃については、委託の現状をお示ししましたけれども、今現在２１０カ所のうち８７カ所を委託を進めているものです。もちろん公園のトイレの清掃等についても、ある程度の委託が入ってあります。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"最後にお話しますけれども、先ほども言いましたように定数が減っていることはわかりました。ただ、再任用、再雇用の人数が増えている。だから、品川区に実際に働く方の人数と、再任用、再雇用を雇ったけれども、結果的に人件費が減ったことがわかる資料を後で教えてくださいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"それに対して、例えば４ページ目の保育園における調理、人件費の節減ということで大幅なコスト削減で出ているとおりに同じような発想で、例えば平成１４年の土木を見て、定数が２５名に対して現員が８５名、プラス６０名ということで、当然もとの定数の給料から再雇用、再任用になってコストが落ちているというのはよくわかるんですが、逆に再雇用、再任用より新規職員を採用した場合の比率ですとか。","respondent":"桑村人事課長","answer":"それについてはできないということになれば、私どものやったという数字自体がおかしかったということになろうかと思いますので、そういう発想でやっているものです。","id":"exchange-005"},{"speaker":"本多委員","kind":"確認","question":"１ページ目のその他のところで、平成１４年は定数１ということで、先ほど経理課の６０歳のメール係ということで、来年は定数が０になっていくということなんですが、０になってもやはり現員は変わらないということでいいんでしょうか、その確認だけお願いいたします。","respondent":"桑村人事課長","answer":"今のところ、定数も現員も０にするという予定で進めてあります。","id":"exchange-006"},{"speaker":"本多委員","kind":"意見","question":"先ほどから出ております定数のバランスというところですけれども、新規職員とのバランスということなんですけれども、やはり職の内容によっては再雇用、再任用ですとか非常勤のほうがいい場合もあるとは思うんですけれども、どうしても民間の発想でいくと、既得権を維持するという発想ではなくて、やはり新卒の方をバランスよく採用していくというような。","respondent":"本間総務部長","answer":"ご要望でございましたけれども、現業職員に対する考え方ですが、基本的には現業職員につきましては、今るる人事課長から説明したような状況もありますので、新規採用職員の現業職については採用しないという考え方です。","id":"exchange-007"},{"speaker":"金高委員","kind":"意見","question":"３ページの改善した点と今後の方向ということがあります。改善した点ということで、９３人から８４人という形になってきています。ただ、現業職員の方の職種が変わったときに、その部門が本当に現在過員なのかどうか、その辺のところが見えてこないんですけれども、異動を検討するということですけれども、その辺はどういうふうに考えているかお聞かせ願いたいんです。","respondent":"桑村人事課長","answer":"その意味で、保育園の給食調理につきましては代行を進めていくということがあるわけですけれども、それ以上に一定の退職が見込める部分がありますので、そういったことも考慮しながら進めていきたいと考えています。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"例えば、よく春先に見かけるんですけれども、職員の方が浸透枡だとか雨水枡の清掃をしていたり、こういうものを委託しようとしたときに、例えば職員がやったときのコストと委託をしたときのコストを計算をして、その上で委託をしていくということなんでしょうか。高木の剪定もそうだと思いますけれども、この辺の考え方を聞かせていただければと思います。","respondent":"桑村人事課長","answer":"今回、職員定数を各事務所に８名置いたというのは、浸水等の事前のものですとか、そういったこまめな点検をチェックをして、それを委託業者につなげていくような仕事ができないだろうかというのが、基本的な所管課の考え方です。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"職員がやったときから見れば半分ぐらいになるのではないかと、総枠での話なんでしょうか、それとも清掃とか剪定とか個別の考え方なんでしょうか。","respondent":"桑村人事課長","answer":"一つ一つの業務について個別の人件費の割合というのは、なかなか出しづらい部分がありますので、一定のサービス水準を維持するときに、民間の方にお願いしたらどのぐらいになるだろうかということで比較したものと考えています。","id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"考え方のところですけれども、２４名、２５名が適正かどうかというのは、さっきのお話だと積み上げ方式だからということなんですけれども、果たしてそこで現業が賄えるかどうか。公園土木の場合はいろんな形で民間を入れてきているわけですけれども、そことの対比からして、仕事そのものが十分補えているのかどうか危惧しているところですけれども、その辺はどうなんでしょうか。","respondent":"桑村人事課長","answer":"先ほど言いました２４名の仕事については、一定の整理ができましたけれども、現実には８０名以上の職員がいて、違う意味での仕事をやっているわけですので、先ほど配置転換と申し上げましたけれども、年齢構成等も高い職員もおりますので、果たしてどこまでいけるかというのは。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"そこにおける土木ですけれども、これから年齢的なものもあるからというお話だけれども、民間委託が八十数名の中で可能な部署というか仕事というか可能性はあるんでしょうか。かなり現状の中では八十数名落とすというのは難しいんじゃないかなという気がするんですけれども、その辺の工夫についてお考えがあればお聞かせください。","respondent":"本間総務部長","answer":"作業職という性格上がございまして、私どもが考えておりますのは、先ほども課長がご答弁しましたとおり、清掃職に転換が可能だということなんですが、これについては時期的な縛りもかかっている面がありますので、この縛りが解けた段階では。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認で教えていただきたいと思います。さっき部長が、退職不補充とかあるいは清掃職への異動とおっしゃっておられましたけれども、既に計画があるということからいきますと、おそらくいつまでにはどうするんだというようなお考えがあるやに受け取れるので、その辺の確認をと思いましてお尋ねをしているわけです。","respondent":"本間総務部長","answer":"ただ、過員がおりますので、その分の作業としてまだ委託化されていないということで、先ほど来ご説明しているような退職まで、要するに過員が減っていけば、その分を委託に順次変えていくという考えです。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問・要望","question":"その件については、わかりました。さっき現業職員の件で、特に質問ではないけれども要望という中で、部長が「現業職については新規職員は採用しないということが前提になっております」とはっきりおっしゃっておられました。その考え方の中には、順次委託化できるものについては委託化していくんだと。正規職員は全部いなくなるんですという理解をしていいですか。その辺の考え方をもう１回教えてください。","respondent":"本間総務部長","answer":"土木職員以外の学校現業の職員につきましても、今の定数だと何年後には定員と現員を割ってくるというケースも考えられますけれども、当然そのときには区民サービスを低下しないようなやり方ですとか、定数自体が時代に合った見直しですとか。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"もう１点確認をお願いしておきたいというか、４ページ目の保育園における給食調理で、調理の業務代行が既に１９園実施されましたが、３番目の今後の方向で、平成１６年度までの２カ年の予定で全園をそうしていくんだということは、残りは１８園ですから、例えば平成１５年度に９園、平成１６年度に９園、すべて３７園調理業務代行委託になるんですという理解をしていいんですか。","respondent":"桑村人事課長","answer":"１点目の平成１６年度までの２カ年ですけれども、園については委員がおっしゃられたように９園、９園と思っていますけれども、これはまた別途の検討等あるいは予算等を伴いますので、別途のことがあろうかと思います。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"こういう時期ですから、区内でやっている事業については、できれば区内業者に委託化していくというんですか、共存共栄ではありませんが、そうしていただけると大変ありがたいなという気がするんですが、行財政改革特別委員会として質問がずれているかもしれませんが、関連ということで教えていただければと思います。","respondent":"桑村人事課長","answer":"いただいている資料なので、正確な情報かどうかの部分がありますが、７社の部分ですけれども、四つの園を持っているところが２業者、三つの園が２業者、二つの園が２業者、一つの園が１業者ということで７社になってあります。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問","question":"例えば、法令で決められた文書とか文章にしなければいけないもの、本庁で印刷をして持っていかなければいけないものがあるでしょうけれども、電子行政とか言われているわけですから、もう少し柔軟に考えて、例えばＥメールで送って、それを現場でプリントをしたものが命令書のかわりになるとか、そんなことは考えられないのでしょうかということをお聞かせください。","respondent":"桑村人事課長、市岡企画財政課長","answer":"仕分けについて１人の方にお願いをしているということで、各職場で本の配送というものはどうしても電子情報だけでは送りきれない部分が残ってありますので、一定程度は残るかなというふうには思ってありますけれども。したがいまして、財調の職員数と各区の職員数というのは乖離がありますが、その中で各区が自主的に判断をして実際の配置を決めていくという関係にあります。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば、一つの仕事を５人でやる３人でやるとわかりやすいですけれども、事務系は例えば文章をつくるとき、今はワープロ、パソコンが入ってきて、昔は３人でやっていたところが１人でできるというのがあるわけですから、これは要望ですけれどもそういうところもどこかで教えていただきたいと考えていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤田副委員長","kind":"質問","question":"私のほうからものの考え方をご質問したいと思います。平成１３年に組織改正をして、三つの土木出張所、二つの公園出張所を統合して、三つの土木事務所にしたということです。先ほど２班に分けたと、４人、４人に分けたという内訳はどういう役割といいますか、どういうふうになっているのか、まずそれをお聞きしたいと思います。","respondent":"桑村人事課長","answer":"現場に行って作業にかかるのにその程度必要だろうということで、一つは緊急時の対応等に、１事務所１班だけではかなり厳しいんじゃないだろうかということが発想です。その意味で、２班８名程度は必要だろうというところで決めたものです。","id":"exchange-019"},{"speaker":"藤田副委員長","kind":"質問","question":"品川区というのは、自転車で行っても大体２０分もすればほかの区に行けるわけです。清掃事務所は荏原と品川の二つあります。そこに８名の方が仕事をされている。さっき言いましたけれども、２２キロ平方しかないわけです。その中でどんどんボランティアも参加してやりましょう、委託もしましょうという時代の流れの中で、私が思っている考えについて、どうお考えになっているかお伺いしたいと思います。","respondent":"桑村人事課長、市岡企画財政課長","answer":"通常の業務は何をしているかと言いますと、８名の方が一定のエリアを巡回しながら点検をし、必要があれば自分たちで直す、あるいは民間の方につなぐというような作業をして、もう少しきめ細やかに対応しようという発想です。ただ、逆に一方、現場管理とかあるいは区民の方からの苦情の窓口あるいはコミュニティとの関連、この辺を逆に３事務所の重点的な業務として再編をしていったらどうたろうかということで、今完全にそこまで進んではおりませんが。","id":"exchange-020"},{"speaker":"藤田副委員長","kind":"質問・要望","question":"清掃事務所でも２カ所しかないわけです。これは毎日の業務です。やっぱり、いろいろ陳情だとかいろんな要望を受けています。ですから、土木についてもそんなに広い範囲ではないと思うんです。２２キロ平方しかないわけですから、毎日車でどんどん回っても１日回れば次の日は大体わかるわけです。陳情だとか要望についても、当然どこにいても受けられるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"給食調理のほうでお聞きしたいんですけれども、４ページの改善した点の２で、「調理代行導入により食材・栄養価等への関心が高まった」と書かれているんですけれども、その前段で「関心が薄かったが」と言っています。職員意識の判断の仕方というのを、ここに書かれている問題で教えていただければと思うんです。","respondent":"桑村人事課長","answer":"私も詳しいことがわかりませんので、聞いている範囲でお答え申し上げたいと思います。","id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"例えば直営の保育園ですと、お互いに職員なわけです。当然のことながら、私が子どもを預けていた時代もそうですけれども、その中で職は違っても職員同士の密接な関係があってやられてきたわけですけれども、代行業者とのつながりが深まったというのは、今まで職員同士のつながりが業種が違うことで薄かったのかと取れちゃうんですけれども、そこをお願いしたいと思います。","respondent":"桑村人事課長","answer":"正直言いまして、私自身がこのことの集約をしているわけではないので、ここに書いてある以上のことは申し上げることはできませんけれども、代行業者とのつながりというのは、調理代行を入れるときに一つの給食調理について一定の分析をし、調理の方がどういう業務をするのか。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"もう１点だけ、「園児の喫食量が増加につながった」という、この辺は基準があるんですか。もちろん栄養とかあるんでしょうけれども、０歳児はどれぐらいだとか、１歳児はどれぐらいだとか、こういう基準があって増加したとかという部分あるんでしょうか。","respondent":"古川総務課長","answer":"当然、０歳児から５歳児まで幅広い年齢を預かっておりますので、それぞれ基準のカロリー数等も国から示されておりますし、それを受けて各自治体、各保育園でそれを勘案してプラスしたり、そういう形では実施しています。","id":"exchange-024"},{"speaker":"鶴委員","kind":"質問","question":"冊子を持ってこなかったから細かな点まで触れることできませんが、私も３月の予算特別委員会の段階で言及しようと思っていたんですが、当時の「さけび」の中でも、Ａさんが言った、Ｂさんが言ったというような感じで、どちらかというと給食調理業務代行が進行していてまずいことだいうとらえ方をしていると思うんですが、最近の組合のとらえ方というのはどうなんですか。栄養の面でも低下ではないです。","respondent":"本間総務部長","answer":"保育園におけます給食調理のあり方につきましては、まさに委員ご指摘のとおり同じ考えで私どもも実施しているわけでございまして、対組合との話し合いの場等につきましても、我々の考え方はきちんと述べしていますし、区のいろいろな施策の方向的なものを職員に流すときにも。","id":"exchange-025"},{"speaker":"鶴委員","kind":"意見","question":"随分、時代錯誤もはなはだしいなと思って、ホームページでのぞいているんですけれども。でも、やっぱりいきなりとはいかないと思うんですよ。そういう視点に立ってやっていくべきではないかと思えてならないんです。それはなぜかと言うと、例えばここに土木作業職員のことがありますが、平成７年に１１７名、そして平成１４年４月１日では定数上では２５名で過員を８５名抱えている。","respondent":"中尾根企画部長","answer":"学校給食の問題についても、組織としては全体として討議をして結論を出しているわけではありませんので、あくまでも今日の段階では私自身の個人的な受け止め方ということに限定しますけれども、そういう意味からしますと。","id":"exchange-026"},{"speaker":"鶴委員","kind":"質問","question":"学校給食法に基づいて行われてきた。どういうふうに教育委員会がとらえているんだろうと。地方では、調べてみれば積極的に検討しているところもあるじゃないですか。企画部から見たらどうですか、教育委員会はどういうところに位置しているの。あるいは、あれは保育園部門でやっていることだから、私たちに関係のないことだというふうに教育委員会は思っていないと思うんですが、正しくはどうなんですか。","respondent":"中尾根企画部長","answer":"ただし、先ほど言いましたように、これからの新しい時代の中で、今後さらにどうあればいいのかという検討の時期には来ているんだろうと、少なくとも企画部門ではそのように受け止めてあります。","id":"exchange-027"},{"speaker":"鶴委員","kind":"質問・要望","question":"論議があったかと思うんですけれども、過員をどういうふうに減らしていくのかという計画は、ちゃんとできているんですか。一方では、ずっと定数は減らしているけれども、過員をずっと抱えていくわけです。そして職員定数としっかり合うようにしていくのだと、いつまでは過員を認めていただきたいと、そういう展望はどうなっているんですか、計画というのは。","respondent":"本間総務部長","answer":"それに比しての退職予定者数を見ましても、そういう思いではいるんですが一定の時間はかかってしまうということは、ひとつご理解をいただきたいと思います。","id":"exchange-028"},{"speaker":"鶴委員","kind":"質問・要望","question":"ちゃんとしたものがないと、何で定数を定めたのかということが意味不明になってくるじゃないですか。でも、勘弁してくださいでは、何のために定数を設けたのか意味がわからないじゃないですか。あんまり多い過員なんて、いつまだでも解消するのですかということになるじゃないですか。区長を擁護しているとか、とんでもないことを言う連中がいるから、どういう考え方で対処していけばいいですか。","respondent":"本間総務部長","answer":"といえば、では、過員がこれだけ出るから、当面定数は６０名をプラスしたもので１００名近い定数で置いておきましょうと言った場合に、そういう姿勢だけは取りたくない。","id":"exchange-029"},{"speaker":"宮崎副委員長","kind":"確認","question":"何点か確認しておきたいんですけれども、先ほど保育園の喫食量のところで、説明がよくわからなかったんですけれども、喫食量というのはどういうふうにして出すんですか。教育も充実したというふうに言っておりますけれども、何か食に関する教育ということだと思うんですけれども、具体的にどういう変化があったのか、ここのところをまずお聞きしたいと思います。","respondent":"桑村人事課長","answer":"大変、申し訳ありません。私自身細かいことはよく知り得ておりませんので、喫食量というのは、０歳児が何グラムというのがあるんだろうと思います。それについての統計を取ったところ、増加しているということなんだろうと思います。","id":"exchange-030"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"喫食量の算定の仕方は、どういう計算をするのか、後でわかったら教えていただきたい。もう一つ、先ほど鶴委員の質問で、企画部長の答弁の中で確認しておきたいんですけれども、企画部のほうから教育委員会に対して学校給食の問題で問題提起をするということなんですか、そこのところを確認しておきたいと思うんです。","respondent":"中尾根企画部長","answer":"今日、行財政改革特別委員会でこのような話があったということは、きちんと責任を持ってお伝えしておくという範囲です。","id":"exchange-031"},{"speaker":"宮崎副委員長","kind":"質問","question":"その前の段階で、企画部長は私見ということでお述べになりました。そのことも含めて話すわけですか。","respondent":"中尾根企画部長","answer":"私見はあくまでも私見ですから、今後の流れの中で、私の私見が取り上げられるようなときが来れば、そういうことになりますが、報告と私自身が意見を持っていることと同時に混同して伝えるというわけではありませんので、きちんと分けて進めていきたいということです。","id":"exchange-032"},{"speaker":"宮崎副委員長","kind":"質問","question":"例えば、３番の年代別現員数の表で、作業Ｉのところで２０代が１名ということですと、退職不補充ということですと、遠からずこの２０代のところは０になっていくのかなと思うんです。年齢構成だけを見ていくと、品川区の職員は先がないかなという感想を持つんですけれども、ここのところはどういうふうにお考えなのか、どういう年齢構成が必要なのか、そこのところはどうでしょうか。","respondent":"桑村人事課長","answer":"採用をストップしていますと、年齢構成が高くなってまいります。ただ、業務の見直しの中で過員がこれだけいる現状、また保育園等についてはさらに調理の代行を進めていくような状況の中で、職員の採用を今行うというのはなかなか難しい状況であるというのは、共通しての認識です。","id":"exchange-033"},{"speaker":"宮崎副委員長","kind":"意見","question":"今、定員ありきという感じで、今の定員が絶対的な感じで印象を受けたんですけれども、そういう感じでいいのか、もうちょっとフレキシブルに委託するにも、どういう仕事を委託したらいいのか、それによってどういう跳ね返りがあるのか、場合によったら定数も一旦こういうふうに決めたけれども、やっぱりもうちょっと増やしたほうがいいとか、その辺の柔軟性というか。","respondent":"桑村人事課長","answer":"私どもと所管課が平成１３年４月１日に定数を決めたときには、こういう仕事について今後正規職員で対応するのが適切であろうという方向性を出したものです。","id":"exchange-034"},{"speaker":"宮崎副委員長","kind":"質問","question":"去年から事業部制になって、事業部制のところで人事の考え方もやっていくのかなと思ったんですけれども、もう一つここで実際に人事課があって、定数も把握するわけですね。過員解消で人事課のほうからも取り組みをするということなんですけれども、定数を決めることも含めて、各事業部と人事課はどういう関係で、実際にどこが責任を持って決めるんだろうと、そこのところはどうですか。","respondent":"桑村人事課長","answer":"もちろん、最終的な定数条例等に出す責任については、人事課が持っているわけですので、私どもが最終的に責任をもって出すということで、内部的な意味での事業部との絡みですが、今までは個別に各課と人事課が直接定数についても議論を進めてきたわけですけれども。","id":"exchange-035"},{"speaker":"宮崎副委員長","kind":"意見","question":"私も前に仕事をやっていたとき人事をやっていて、合理化をやっておりましたけれども、やっぱり現場のところの取り組みが最優先で考えていかないと、上から押しつけてもなかなかうまくいかないという経験をしていましたので、ここのところは区はどういう考えでやっているのかというのが疑問だったので聞いたんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/114679?Template=document&Id=5712#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":36689,"voices":81}},{"id":"h14-20020705-16","meetingId":"h14-cm07","date":"2002年7月5日","dateIso":"2002-07-05","committee":"街づくり特別委員会","time":"午前１０時０６分～午後０時３０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"前にも言ったことで恐縮ですけれども、駅前広場をつくったり、補助第１６３号線を含めた整備をする意義は確かにあると思うんですけれども、この中でも、例えば明電舎、ソニーが単独開発をやるというのは、これはこれで権利ですから否定するつもりはないんですけれども、最大の問題は中地区だと思うんです。住宅街で平屋あるいは２階が軒を連ねているところを、高度地区を外して、準防火を防火に変えていく。","respondent":"南雲都市開発課長","answer":"零細な権利者の方への対応ですが、現在、今後の権利変換の細かい詰めを行っておりますが、その中でも最低でも現状の床面積と同じ面積は確保できるようにということで、権利変換計画の数字の詰めを行っておりまして。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"こうした場合に、全体地区計画の網をかけて、私は乗らないというふうに言ったら、最終的にはどうなるんですか。戸越一丁目地区なんてまさにそうだし、前から私はよく言っているんだけれども、北品川二丁目、一丁目、あそこの道路の半分しかないところがたくさんあるじゃないですか。そして、実際にここに入ってくるデベロッパーなり、参加組合員なりが、現状決まっていれば説明をしてほしいんです。","respondent":"南雲都市開発課長","answer":"３点目につきましては、現在具体的な参加組合員の可能性のあるところ９社と最終的な詰めを行っているということで、これについても現在の参加組合員についてもなるべく早く達成できるように進められているという状況です。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"参加組合員の詰めを行っている、もう少しだ、もう少しだと、何年かかるんでしょうかね。それから、もう一つ、全員合意を目指す、それはぜひ貫いてほしいと思うんですが、そう言いながら、一定の段階になればということがほの見えるわけです。得ていないんじゃないですか。明電舎、ソニーはいいです。オーバルコートだって何だってみんな借りているじゃないですか。一応意見だけ言って、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"中地区の関係ですけれども、中地区は総施工区域が１.８haですね。その１.８haの中で、千代田生命と、この間私どものほうでも指摘している関係でのそれはどのくらいの面積をお持ちなのか。１.８haのうちどのぐらいの面積を占めているのか。もう一つは、今８５人の権利者とおっしゃっておりましたね。土地所有者、借地者、家屋の所有者、家屋を借りている方を教えてください。","respondent":"南雲都市開発課長","answer":"居住している方としては概ね３００人程度ということで、これはアパートなどは出入りが多いので、日々変わっているということで、概ね３００人ぐらいです。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"公有地、道路関係を除いて、底地として１万５,０００m2のうち１万m2というのが実際の面積。あるいは商売をされている方、そういう方は何人いるんでしょうか。今住んでいる方が３００人ということですけれども、１０年前は４４０人ということで、この変化というのをどういうふうに見ていったらいいんでしょうか。その１０年間の推移というのをどういうふうにお考えになっているでしょうか。","respondent":"南雲都市開発課長","answer":"ここは従前は準工業の３００％でありましたので、これについては、この開発の中で空地の内容ですとか、空地の面積、道路などの整備の内容を勘案して５６０％に上げていくというものです。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問","question":"１０年間で減っているのは３割ですよね。本当に夢があって、この開発に期待を持っているとすれば、むしろそこに期待をさせるという関係からすれば、増えるということはないのかもしれないけれども、少なくとも踏みとどまってそこで生きていこうというふうに、普通は人間というのは考えるんじゃないですか。もう一つ、３６０億の５５億円だと。この増えた要因というのは何でしょうか。","respondent":"南雲都市開発課長","answer":"補助金につきましては、まだ確定しておりませんので、本当に見込みですが、昔に比べますと、住宅プロジェクトの場合は補助率が増えたということがありますし、あと共同施設の中でも、住宅の中で共用部分で段差を少なくするとか、手すりをつけるとか。","id":"exchange-006"},{"speaker":"桜井委員","kind":"意見","question":"土地の所有関係を聞いたんですけれども、地権者というか、権利者の中で９割近くが賛同しているということの背景には、借地の中の、例えば６５人のうちフジタ関係で持っていらっしゃるのが５８名ということですね。かなり複雑な権利関係がこの地域の中にはあると思うんです。そのことだけ指摘しておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"船波委員","kind":"質問","question":"南地区のところには、現在ある大崎在宅サービスセンターがくるのではないかと思いますけれども、この地区が業務棟になってしまったときには、介護支援センターはどうなるんですか。","respondent":"南雲都市開発課長","answer":"２ページのところに大まかなイメージがありますが、この図面では業務と住宅ということで、２棟あるような形になっておりますが、現在考えておりますのは、低層の一、二階部分については業務、住宅をまたがるといいますか、低層のところがくっついておりまして。","id":"exchange-008"},{"speaker":"船波委員","kind":"意見","question":"入ることも可能なというのは、検討ということには、可能だから、そこに決める予定なのかどうか、その辺が大事だと思うんですけれども。","respondent":"南雲都市開発課長、市岡企画財政課長","answer":"所管が違うということで、そういう表現になってしまったんですが、開発を行う考え方としては、低層部分に入るということを想定しているです。もちろん現在必要な区の施設としての在宅サービスセンターですから、これは基本的に何らかの形で今よりもより望ましい形で存置をするということですが、ただ、具体的にどの位置に、どういう形で。","id":"exchange-009"},{"speaker":"北野委員","kind":"質問","question":"一つ、基本的なところで聞きたいんですが、高度の第三種とありますけれども、外されたということは、どこまで高さ制限になっていくのかというところを伺いたいんです。ここは３３階建てですけれども、今は建物の高さというのは可能な限り高くなれるんですね。可能というか、問題もあると思うんですけれども、外されたときに、どこまでの高さというのが可能になるのかというところをお伺いしたいんです。","respondent":"南雲都市開発課長","answer":"高度地区というのは、これまでは一律に高さを規制していたということですけれども、今回、再開発の地区計画の中で具体的な計画を見て高さを定めるということで、周辺の道路からの斜線の規制ですとか、そういうものがありまして、定めてくるようになっておりますけれども、ただ。","id":"exchange-010"},{"speaker":"北野委員","kind":"質問","question":"１３０ｍから１４０ｍということですけれども、建物の階数としては、高さというものがありますけれども、概ね何階とかになるんですか。そういったときに、高さというところの制限は何階ぐらいになっているんでしょうか。","respondent":"南雲都市開発課長","answer":"ソニー、明電舎のときはまだ開発の計画がはっきりしておりませんので、高さがどうなるのかということもはっきりいたしませんが、先ほどの航空法の１３０ｍから１４０ｍ、これが上限ということで、今後具体的な内容は決まってくるです。","id":"exchange-011"},{"speaker":"北野委員","kind":"意見","question":"高さが１３０ｍから１４０ｍという制限がありますけれども、でも、周りというところを見渡した限りでも、街並みの景観が崩れていくという現状は確かにあるんじゃないかなと思います。景観ガイドラインをつくるということでもありますけれども、住むときのまちの景観というところではどうかなというのがあります。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私もあの地域で仕事をしていたので、あの地域に３３階建てのビルができるというのがちょっと考えられないという思いがしているんです。もう一つ、百反通りには住宅だけでなく、お店もあると思うんですけれども、そういうお店の営業というところではどうなってしまうのかということについて教えていただきたいと思います。","respondent":"南雲都市開発課長","answer":"商店につきましては、これはそれぞれ具体的に営業をされている方と調整を進めているという状況ですが、基本的には業務棟の１０階建てというところがありまして、駅に近いほうの業務棟、こういうところの中に営業を継続される方については入っていただくということで。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"借地で十数坪ということですけれども、借地の場合だと、２階建てとかというふうな形で建てられていますよね。そうすると、床面積と土地の面積というのは、自ずと床面積のほうが多い状況になっていると思うんですけれども、それでも土地の面積しかマンションに移るときには権利変換の形にならないのか、それとも住んでいる床の面積で変換になるのか、そこのところをお願いいたします。","respondent":"南雲都市開発課長","answer":"権利変換では土地、建物の金額と、新しい床の金額で置き替えるんですけれども、今言っております同じ面積といいますのは、今お住まいの住宅の床面積と同じ面積は確保できるというのを基準に調整を進めているです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、補助金の関係ですけれども、５５億円の補助金というところで、増えた理由というのは、バリアフリーとかで補助金が増えるということで先ほど言われたんですけれども、これまでの制度に加えてバリアフリーということで説明されましたけれども、これまでの制度で５５億円という根拠が、どういうことで補助金が出ているのかということについて教えていただきたいと思います。","respondent":"南雲都市開発課長","answer":"公園とか道路などを整備する場合にも、もろもろの施設の整備の費用についても補助の対象になります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"建物に関しての共同とか、エレベーター、階段、受水槽、そういうふうなところでの補助金というのは、今回の住宅棟に対して５５億円というふうな、そういう考え方なんでしょうか。","respondent":"南雲都市開発課長","answer":"住宅と業務と全部合わせて、それぞれ共同施設については補助対象になります。ただ、住宅のほうが共同施設の割合が高いので、補助の率としては住宅のほうが高くなりますが、全部の棟が入っておりまして、全部合わせてというふうになります。","id":"exchange-016"},{"speaker":"桜井委員","kind":"質問・要望","question":"前回、６月１６日のときに事務事業概要で質問をさせていただいて、資料をいただきたいということでお願いしておりましたので、ちょっとお話しします。もう一度教えていただきたいんですけれども、ここの権利者が約７６名、先ほどと同じような質問なんですけれども、土地所有者、借地、家屋の所有者、借りている方がどうなのかということを、復習の意味で教えてください。","respondent":"南雲都市開発課長、岩野まちづくり事業部次長","answer":"大林組と日本舗道の２社が参加組合の予定者ということでございまして、この２社につきましては、参加組合というのは、保留床を取得するということで、現在この事業の中で賃貸等、住宅も業務もそれぞれ保留床が出てきまして。分譲につきましては、約２２０戸を計画していますが、ここは今のところ日本舗道が取得する予定ということでございまして、残った業務棟については大林組が取得予定というような形で、今検討をしています。","id":"exchange-017"},{"speaker":"桜井委員","kind":"確認","question":"現在その土地を持っていて、賃貸のほうの３２０戸というのは旧住都公団ですね。そこが保留床として入ると。今のご説明だと、分譲の日本舗道というのは、ここで言うと何平米かもう一度確認したいのと、それから業務棟で言うと、業務施設は５,５９６m2ですけれども、工業施設というのが入っていますよね。これもみんな大林組なのかどうか、そこの確認。それから、７割、３割の意味を教えてください。","respondent":"南雲都市開発課長","answer":"比率といいますのは、保留床の金額のうち両者の取得する床が７割と３割の比率になるということで、場所としては日本舗道のほうが分譲住宅、一番北側のところですけれども、オフィス棟のほうが大林組です。","id":"exchange-018"},{"speaker":"桜井委員","kind":"確認","question":"もう一度確認です。今の７割、３割のところですけれども、今の説明の私の理解としては、業務の大林組が７割、３割が日本舗道だという理解でいいのかどうかということをもう一度確認したいんです。","respondent":"南雲都市開発課長","answer":"これは保留床全体の総額のうち、それぞれが取得する部分の比率で言ったものです。これもまだ建物の施設もはっきりしておりませんので、金額も出てこないということで、今のところの想定で、そのくらいの比率で今後取得していくです。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"資料の１ページで、青色系が工業施設だということで、現況の左上で、工業施設が２０棟、５１.３％となっておりますね。５１.３％は、延べ床に対する割合なんでしょうか、土地なのか、よくわからないので教えてほしいんです。それと、これらの工業関係施設は開発の中に取り込む余地があるのかどうなのか教えてください。","respondent":"南雲都市開発課長","answer":"現在工場としての操業を希望されている事業所というのは１件といいますか、１件の方については工場を継続するのかどうなのか、現在検討しているということで、それ以外の工場につきましては、すでに機能を移転されているということで。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"工場は、昔はやっていたけれども、今は一つもなく、１件のみが継続するかどうか検討をしているんだけれども、それは開発地域の中では受け皿は設けるんですか、設けないんですか。そのことが一つ。","respondent":"南雲都市開発課長","answer":"将来この受け皿があるのかどうかですが、この中では、現状では業務、住宅ということで、１件の工場の営業されている方については、準備組合のほうで、操業を継続される場合には継続可能な代替地をあっ旋するということで。","id":"exchange-021"},{"speaker":"沢田委員","kind":"意見","question":"今品川区では産業マスタープランをつくって、製造業を中心とした中小企業のものづくりを育成しようという方針をやっているけれども、ここで見ても、工業、ものづくりは衰退の一途で、最後の１件も代替地というから、ここから出ていかざるを得ない。今、昼間人口と夜間人口の、建った後の見通しはあったんだけれども、現況はどうなのかというのを聞いたんですが、答弁がなかったんです。","respondent":"南雲都市開発課長","answer":"これは確認をいたします。","id":"exchange-022"},{"speaker":"船波委員","kind":"質問","question":"そういった開発されたところに近い地域のところの土地の値段というのは、こういった開発がされるがために便利になったからとか、そういった理由で土地の値段というのは上がってきているものなんでしょうか。そういった変化というのがもし分かれば知りたいんです。","respondent":"南雲都市開発課長","answer":"そうしますと、新しくできた幹線道路に面しているところについては、実際これまでよりも広い道路に面するようになったということで、地価としては上がることが考えられるです。","id":"exchange-023"},{"speaker":"船波委員","kind":"質問","question":"今具体的に出たオーバルコートのそばというのは今後上がることは考えられるというお答えだったと思いますけれども、オーバルコートのそば以外のところで、今までどういうふうな変化をしてきたかというような、数年の状況の変化というのは調査しているんでしょうか。","respondent":"南雲都市開発課長","answer":"東五反田地区は今後開発するということで、地区更新計画というのが定まっておりまして、そういう関係で土地の取引自体もほかの地区に比べて少ないということもありますし、また具体的な民間業者の取引価格というのはなかなか知ることが難しいということがあります。","id":"exchange-024"},{"speaker":"沢田委員","kind":"提案","question":"不勉強で申し訳ないんですけれども、関係権利者の３分の２以上で都市計画が提案できると。民間事業者のことを言っているわけですね。現状との関係ではどうなのかということを教えてほしい。これプラス従来の補助制度ということなんでしょうか。","respondent":"南雲都市開発課長","answer":"３分の２といいますのは、開発区域の中の権利者の３分の２ということで、３分の２の合意で提案することが可能です。都市計画の場合にははっきりした数字はないんですけれども、概ね９割程度の合意が必要というようなことが今までは行われておりました。","id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"これは都市計画ですけれども、先ほどの中地区の場合に、全員合意を目指すと言っているけれども、実態的には３分の２あればいいんだということに、地区計画は地区計画て決まってきますけれども、そういう流れを促進しはしないかということが一つ心配です。","respondent":"南雲都市開発課長","answer":"３分の２といいますのは、都市計画を提案する場合の最低限ということでございまして、３分の２が集まっていれば、それですぐに都市計画が決まって、事業化できるというわけではございませんで、再開発事業の場合ですと。","id":"exchange-026"},{"speaker":"北野委員","kind":"質問","question":"そうしたときには、かかった網かけの部分というのはどうなってしまうんでしょうか。再開発の部分では残るけれども、こちらの緊急性のほうでの網かけの部分との整合性というんですか、再開発としては開発までずっと残るけれども、時限立法としての１０年間の中に開発可能でなければ、その後どういう、再開発だけの部分で残っていくわけですか。","respondent":"南雲都市開発課長","answer":"都市再生特別措置法といいますのは、１０年間の時限立法ということで、緊急に都市の活力を高めていこうというところで、短期間に開発を進めて、都市の活力を高めるということですので、都市再生特別地区の都市計画の整備につきましては１０年間、その期間を過ぎますと。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"大崎の関係で言うと、６０haが再生特別措置法の対象になったというふうに言ったんでしょうか、なるというふうに言ったんでしょうか。その辺の区の係わり方というんでしょうか、区のほうがそういうふうに都を通じて国に対して指定してくれよというふうに言ったのか、その辺の経過を知りたい。そういう視野に入れての都市再生法の申請というんでしょうか、決定に至ったのか、そのところを聞きたいんです。","respondent":"南雲都市開発課長","answer":"区の係わりにつきましては、今後短期間に都市の再生のための開発が進む区域、もう幾つかピックアップされたんですが、その中で区としても大崎駅周辺の地区については、都市再生緊急整備地域に指定を受けて、開発を早期に進めていくことがふさわしいといいますか。","id":"exchange-028"},{"speaker":"桜井委員","kind":"確認","question":"一つ確認ですけれども、この整備の指定については区が申請をした。区が申請するにあたっては、それぞれの地域の地権者も違うし、デベロッパーも違うし、それぞれの意向がありますよね。ということは、この流れとしては地方自治体が案を申し出するわけですから、品川区の中にこういう設置をしたんでしょうか、するんでしょうか。とすれば、どこが責任を持ってやるんでしょうか。","respondent":"南雲都市開発課長","answer":"これは申請とか、そういう手続を踏むものではなくて、都の再生本部の中でどこを指定するのか、方法を判断するために、区として大崎駅周辺をこの指定にふさわしいところであるということの提案をしたということでございまして、今後この手続としては。","id":"exchange-029"},{"speaker":"桜井委員","kind":"確認","question":"ということは、東京都も都市再生本部のね、だけど、区の意向を聞いてという部分で、当然その前提にありますね。そういう意味で、区長の判断で都のほうに、いいよというふうに言ったという、そういう理解でいいのかどうか、そこだけちょっと確認したいんです。","respondent":"南雲都市開発課長","answer":"それに対して区として異論がないということで、意思決定を行いまして、その返答をしているです。","id":"exchange-030"},{"speaker":"北野委員","kind":"提案","question":"今後国のほうではもっと広げていくという考えを示しているんですけれども、品川区としては、指定があれば、有効であるというところで、またどこの地区にもこれはできるようなことを提案という可能性はあるんですか。ちょっと先のことで答えにくいかと思うんですが、お伺いいたします。","respondent":"南雲都市開発課長","answer":"今回の指定はこれだけということではなくて、第１弾ということで、今後第２弾、第３弾、追加で指定されていくというふうに考えます。","id":"exchange-031"},{"speaker":"北野委員","kind":"質問・要望","question":"この制度というのはいろいろ問題があるということは、桜井委員からも指摘していましたので、土地の有効というところもありますけれども、そこに住む品川区の住民ということを第一に考えていただきたいということは、意見としてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"船波委員","kind":"質問","question":"この中では、幾つか仮称であるものがありますけれども、それについては内容がどういうものであるかというのは、審議会でまとめたものでもあるんでしょうか。","respondent":"伊佐都市計画課長","answer":"ですから、今後の動向を注視しながら、新しい制度を今後どういう形で適用していくかというのは今後検討するという流れになってあります。","id":"exchange-033"},{"speaker":"船波委員","kind":"質問","question":"ご説明でわからないところをお伺いしたいんですけれども、豊かな都市環境の形成というところで、４ページの一番上の行ですけれども、「容積率の特例制度を活用し、省エネルギー等を推進します」となっていますけれども、容積率の特例制度を活用することと、省エネルギーができるというのは、どういうふうに関係するのか。","respondent":"伊佐都市計画課長","answer":"こういうケースは、再開発地区計画などでボーナスを与える際に環境配慮の住宅等、建築物を誘導していこうという趣旨です。","id":"exchange-034"},{"speaker":"船波委員","kind":"質問","question":"もう一点だけ、読んだだけでは全然わからないところがあるもので。今お伺いしたところの下の５の３の二つ目の点のところですけれども、「地区内の建築物の更新を円滑に進めるため、地区計画などを前提として、建築基準法とより密接に連携」ですけれども、建築物の更新を進めるということと、地区計画、建築基準法と密接に影響することが、どう関連しているのか。","respondent":"伊佐都市計画課長","answer":"今回戸越一丁目地区などで導入した地区計画もこれのちょっと先取りしたような制度というふうになっております。","id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"それに基づいた議論というものをしないと、都市計画を将来に対してどうするのかということが皆さんが関心のあるところですから、今日のところはこれはこれで終わっても、各委員にきちっとしたものを渡していただきながら、正副委員長で検討していただいて、次にまた質疑するような機会を設けるほうが、今日のところはいいんじゃないかと思うんですけれども、どうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問・要望","question":"土地利用調査特別委員会を設置して、それの答申ということですけれども、簡単でいいですから、なぜこの時期にこういう諮問をして、諮問の中に考え方が示されている、こういうことを考えているんだけれども、専門的な意見の答えを教えよということだろうけれども、そのことを教えてほしいのと、こういうことはよくやるのか、都市計画審議会が。","respondent":"伊佐都市計画課長","answer":"そういった形で都市計画審議会の審議というのは、概ね用途地域の見直しのタイミングで、土地利用の方針が考えられていくというものです。","id":"exchange-037"},{"speaker":"沢田委員","kind":"提案","question":"さっき読んだ、環状７号線の外側は低層の住宅地だと。都市計画を民間事業者が提案できて、３分の２でごりごりやっていく。国の流れも都市再生というのが出てきているので、そういうのを全体を関連させて、我々としてはどう見るのかということが分かるような資料を、短い時間でパーッと言っちゃうんじゃなくて、分かるように説明してほしいというふうにすごく思います。そのことだけ述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"桜井委員","kind":"質問・要望","question":"今のお話だと、２月１９日に区計画審議会があって、その後どういうふうになっていくのか、はっきりしないんですが、この答申を踏まえた後の経過を質問しておきたい。ですから、もう一回される予定のようですけれども、品川区のマスタープランとの関係とか、品川区の土地の有り様がどういうふうに変わってくるのか、そういうものを資料として提供していただきたいと思います。後段は要望です。","respondent":"伊佐都市計画課長","answer":"前回ですと、概ね１年かけて区のほうで原案をつくり、住民の方に説明し、それで区の原案としてまとめて、区の都市計画審議会でご審議いただいて、都に提出する。そこからは都のほうの指定の手続が１年ぐらいかかると。","id":"exchange-039"},{"speaker":"桜井委員","kind":"意見","question":"マスタープランの関係ですけれども、今のお話ですと、大ざっぱに私の受け止め方でしたよね。東京の土地利用に関する基本方針というのは、品川区のマスタープランとある程度マッチしているという考え方というふうに受け止めたんです。だから、もう少しそこは今度の委員会のときでも私どもも具体的に意見を出して審議したいなと思います。","respondent":"山路委員長","answer":"ご意見がいろいろ出ましたが、三上委員の、答申の本文を提出していただいて議論したいという、これは報告できますよね。今日は概要ということで意見が出ましたので、次回におきまして正副委員長で検討して、対応していきたいと思います。","id":"exchange-040"},{"speaker":"須藤副委員長","kind":"質問","question":"ここに人口フレームと書いてあって、２０１０年でピーク、その後減少というのが、品川区として考えた場合には、この人口フレームの考え方は、品川区で考えている第三次長期基本計画と流れ方はどうですか。","respondent":"中尾根企画部長","answer":"ただ、品川区は漸増傾向でいるということについて今後しばらく続くだろうというふうに見ておりますので、そういう側に立って、次回、もしそういうことで本格的にやるんでしたら、そのときに品川区での今後の人口の捉え方を同時にやらせていただきたいと思います。","id":"exchange-041"},{"speaker":"須藤副委員長","kind":"意見","question":"桜井委員からもいろいろまた出てくるけれども、こんなベースで云々という話でなくなって、ある程度参考という形だろうというようなもので見ていかないと、ここ全部がというような考え方は、さっき言った、マスタープランを品川区はやっている、そっちと一緒に見ていかないとという感じがします。","respondent":"南雲都市開発課長","answer":"先ほどの東口第３地区の昼間人口、夜間人口ですが、夜間人口は１５０人、昼間人口が概ね２５０人という状況です。","id":"exchange-042"},{"speaker":"沢田委員","kind":"意見","question":"私が言いたい趣旨は、現状の昼間人口２５０人ぐらいが３,０００人ぐらいに増えてしまうというのは、開発のあちらこちらに出てくるわけです。そうすると、放出性エネルギーがどうなるのか、超過密都市が開発によってどんどん生まれて、もう一方で品川区は屋上緑化だなどということを言っているんですけれども、ヒートアイランド現象の、環境という点からしてどうなのかというまちづくりを聞きたかったんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/783739?Template=document&Id=6236#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":40185,"voices":108}},{"id":"h14-20020723-6","meetingId":"h14-cm07","date":"2002年7月23日","dateIso":"2002-07-23","committee":"区民委員会","time":"午後１時１０分～午後２時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"防災訓練、職員の訓練ということで報告が出ましたけれども、こういうことに、我々議員のかかわりということで、私たちは防災服をたしかいただいているんですよね。そうすると、それに各議員が出動するとか、そういうことがあるんでしょうか。立場から、どういう。どのように対応を考えているんでしょうか。","respondent":"久保田防災課長","answer":"地区防災計画上は、特に議員としての特別な活動という形での取り込んでいるというような考え方はありません。したがいまして、地域の一員として、それぞれの会場のほうに参加していただければと、こういうふうに考えております。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"６号、７号、ちょうど通過時に目黒川が干潮になったということで被害がなかったような話が出ているんですけれども、床上浸水２件ですか、それはどの辺になるんでしょうか。その原因はどんなものですか。","respondent":"久保田防災課長","answer":"その影響で、この床上浸水が２件出たです。それで、この一たんマンホールが盛り上がったものは戻りませんので、早速応急作業ということで、これは下水道局のほうが対策に当たりまして、その日のうちにその盛り上がった部分については対応しているというような状況でございました。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、満潮ではなかったけれども、局地的にどっと降ったので、下水がはけなかったということに対することですか。","respondent":"久保田防災課長","answer":"水自体ははけたんですが、要するに空気の圧縮によって下水のマンホールが上がると。どうしてもそういうような状況が何個か出てくるような状況なんですけれども、今回もそれに当たったです。","id":"exchange-003"},{"speaker":"本田委員","kind":"質問","question":"場所によっては。その辺は前にもそれぞれ個別に点検を入れて、改善するところは改善するというような話があったと思うんですけれども、その辺はどんなぐあいですか。","respondent":"久保田防災課長","answer":"今回、実はこの個別受信機については、地震が震度４以上があったときには放送が流れるような形で、ほかの放送についてはやっていないというような形にしていたんですけれども、今回風水害の情報も欲しいというような要望もございましたので、これはアンケートをとりまして。","id":"exchange-004"},{"speaker":"本田委員","kind":"意見","question":"個別の場所は、今ここでは申し上げませんけれども、そういうところがありますので、一般の方は大雨の中で何か言っているんだけれども聞こえないと。どういうことなんだろうというようなことがありますので、十分その辺は調整をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すごいいい企画だなと思いながら聞かせていただいたんですけれども、申込者がかなり多くて、定員を増やしていただいて、実際にもかなりたくさんの方が受けられるようにということになったということなんですが、こういうご努力は本当に評価できると思うんですけれども、この定員というのはどういう前提といいますか。","respondent":"市川産業振興課長","answer":"それで、決め方については、決定方法については、コンピュータを使った抽せん方法でやってあります。それともう一つは、昨年、同様の企画をしてございまして、昨年申し込んで、残念ながら昨年落ちた子については優先的に受講をさせるような、そういう仕組みをとってあります。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私の子どもも小学校のときの自由研究でロボットがつくりたいとすごい言っていたんですけれども、親が全然そういうふうな技術がなくて、随分夢だったので、結局あきらめてしまったというふうな経過があって、こういう企画がその当時あったらすごくよかったなというふうに思ったんですけれども、そういうところでは。","respondent":"市川産業振興課長","answer":"それで、実際この事業を始めた５年前のときには定員３０名から始めまして、ここ２年間ばかりは９０名ほどの子どもを対象にしていますけれども、都立高専のあちら側の日程上の事情もございまして、その先ほど申し上げたスタッフと場所の確保ということが。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問","question":"そこらあたり、やはり高専だけの話になるのか、それにしても、今、普通高校というようなところで言われているところで、こういったもの、科学部というのがあるかどうかわかりませんけれども、そういったところが何らかの形でそういうようなものを、こういうのはどうだという可能性がないのか、もう少しいろんな意味で、そういう広がるような感じでそんなことをできないかなと思うんですけれども。","respondent":"市川産業振興課長","answer":"それで、高専側のほうでも自校のＰＲということでいろいろ企画は持っておりますが、今ご提言のございました都立高専では高専祭という秋の学校祭がございまして、この場で一部このロボット講座の受講者の発表の場と申しましょうか、みたいな企画も持っているんですが。","id":"exchange-008"},{"speaker":"三上委員","kind":"意見","question":"一番問題になるのはやはりお金の部分ということもあるので、そこらあたり、やはり多少奮発してでも考えていってあげてほしいなと思います。将来のためにということを含めて考えていただければと。そういうことを踏まえた上での品川区の誠意ある取り組みを考えてもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"オプション設定で親子工場見学ツアーが実施されて、９４組ということですが、これは今学校のほうで授業での工場見学というのは行っているんですか。委員会が違うから、わかるかどうか。この前お会いした方たちの中で、やはり工場見学がなくなっているような話をちょっと聞いていたので、そこら辺はどうかということで。","respondent":"市川産業振興課長","answer":"その中に製造業の事業所も入っているようなことを聞いてあります。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"町のことを学ぶ授業やなんかで、確かに工場に行くというのがあったかというふうに記憶しているんですけれども、この９４組というのとロボット講座のほうというのは、割合同じような方の申し込みになっているんですか。","respondent":"市川産業振興課長","answer":"この９４組の大半の方はロボット講座の受講希望の方だったんですが、このうちの十四、五組については、ロボット講座は落ちても工場見学だけは行きたいという申し込みがございました。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この見学ツアーは、実施プランを練り直しているという、団体コースを。できる限り皆さんできればなと対応をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"当然、その後のごみとかという問題は主催者側が全部整理してやるのか、極端な話、床だってかなり汚れる、ごみの残りとか、点検関係はどうなるのですか。","respondent":"上山区民生活事業部副参事","answer":"特にそれだけの人数のお弁当を用意するとなりますと、ケータリング業者、お弁当の業者のほうが入りまして飲食をされるというケースになるものですので、その場合には業者のほうにお引き取りをいただくということで、従来先ほど申し上げました、認めている部分につきましても。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問","question":"今、町会の回覧というふうにおっしゃったんですけれども、要するに個人の方にはこの１枚ずつ手元に残るという形のものとしては渡さなかったんですか。","respondent":"冨田戸籍住民課長","answer":"それで、個人の方々に対しては、コード通知という形で郵便はがきで８月上旬にお送りする予定ですけれども、そこで若干ご案内はさせていただいていますけれども、紙面の都合で十分できないということで、それをフォローするような形で回覧用にチラシを作成したものです。","id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"せっかくですから、印刷物を全世帯に配ったって、それは町会でどのような配り方をするかわかりませんけれども、回覧でとして、だから回覧にしたって、１枚ずつとってくださいと。そういう中にあって、品川区はきっちりやりますということを、それをお知らせするのであれば、なぜそういうような形で私はできないのかなと思うんですよ。","respondent":"太川区民生活事業部長","answer":"今、課長のほうでちょっと説明をさせていただきましたけれども、これにつきまして、今委員のお話がございましたように、各個人、少なくとも世帯あてというのも一つのやり方だというふうに考えております。","id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"広報でやっても、新聞折り込みでやっているわけでしょう。見ていない人、一般紙をとっていない人で、手元に行かない人はいっぱいいるわけですよ。そういう人たちは目を通さずに終わる可能性というのは何％あるんですか。それはだからどこらあたりで何％ぐらい見ているんですか。","respondent":"太川区民生活事業部長","answer":"たしか広報のほうで、世論調査等で広報紙をどのくらい見ていますかという部分では、たしか九十数％の方が広報紙のほうはご覧になっているというふうに判断しています。","id":"exchange-016"},{"speaker":"三上委員","kind":"意見","question":"だから、こういうふうに、もう全国民が全部関係するという問題については、これは国が当然やらなきゃならない話なんですけれども、どうせやるなら、品川区の中でやっぱりそういう事務的なことをやるというのであれば、それはそれで同じやるなら、ここまでやりましたというようなことをやったほうが、うるさくまたうるさく。","respondent":"太川区民生活事業部長","answer":"今のご意見、先般の委員のお話というのは十分、１枚ずつ行けば、本当にこれに越したことはないというふうに判断していますけれども、私のほうといたしましては、先ほど申し上げましたように、品川区の最大の広報、お知らせのものというのは。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは回覧で回すということですけれども、回覧板の回らないアパートだとか、マンションとかというのも結構あるんじゃないかと思うんですけれども、そういうところというのは、どれぐらいの世帯、回覧板の回らないところがあるというのは把握されているんでしょうか。","respondent":"長田地域活動課長","answer":"断られれば、もうそれで結構ですという形で私どものほうではお願いをしています。ただ、その数がどのくらいあるかという話になると、これは膨大な調査になりますので、数についてはちょっと把握してございません。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は結構回覧板が回らない地域というのもあるんじゃないかなというふうな気がするんですよね。そういうふうなところからすると、やっぱりこういうお知らせというふうなものに関しては、もっといろいろなさまざまなところで周知をしていただくというのが一つ必要なんじゃないかなというふうに思うんですけれども、そういうところに関していかがでしょうか。","respondent":"冨田戸籍住民課長","answer":"東京都につきましても、都の広報紙でも周知をすると聞いておりますし、区のほうにおきましても、先ほど来申し上げているとおり、広報しながわあるいはケーブルテレビ等を通じてやる予定です。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"問題点とかもいろいろ含めて。だけれども、この間の朝日新聞、昨日の朝日新聞では、４０％の方がこの住基ネットについて名前も聞いたことがないというふうに答えているんですよね。そういうふうな状況の中で、今回マスコミの中でもすごいさまざま問題が指摘されていますけれども、実際に行われるというふうなところでは、住民合意ということに関しては、区としてはどう考えられているんでしょうか。","respondent":"冨田戸籍住民課長","answer":"当初予定していたそれらの制度面、システム面についての対応策というのは、一応現段階では十分検証されてきているというふうに私どもは理解しておりますので、制度をいろいろ新聞等で不安が言われておりますけれども、私どもとしては。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"品川区としては、今回の住基ネットの始動に関しては、さまざまいろいろマスコミでは問題が指摘されているけれども、そういうことに対しては、特に問題はなく推進できるという、推進していくべきだという、そういうふうな立場だというふうなことでしょうか。","respondent":"太川区民生活事業部長","answer":"今の件につきましては、委員のほうがお話になりましたように、セキュリティー関係、制度面、それから運用面等につきましては十分対応できる、保護措置につきましてとっているつもりですので、そういう意味では、本区といたしましては、この法令に従いまして。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もう一つお聞きしたいんですけれども、前回のこの住基ネットの説明のときに、地域の方もこのことについては初めてでよくわからないということで、いろいろな集まりのときに説明をしていくというふうなことで、ご報告いただいたと思うんですけれども、その実際に説明をどういうふうにされたのか、それでまたそこの中でどのような意見や疑問とかが出されたかについて、ちょっと聞かせてください。","respondent":"太川区民生活事業部長","answer":"ただ、その後、実際上このコードが届きますのが８月１０日近くになろうかと思いますので、それをいただいてからでも、皆さんのいろいろなお問い合わせ、それから質疑には答えてまいりたいと思いますので、機会をとらまえまして。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ説明についてはできる限りやっていただきたいと思いますし、またこういうふうなことでやっていくというふうな計画も、この中に示していただけたらなというふうに思います。それと、そういうふうに決まった説明会というだけではなくて、疑問に思っている方が参加できるような、そういう広い方を対象にするような説明会をぜひ開いていただけたらと思うんですが、その辺のところについてはちょっと。","respondent":"太川区民生活事業部長","answer":"これは法令上の中で動いていくものですので、いろんな具体的な形での説明会というのは現在のところは考えてございませんが、例えばこれは企画部のほうと調整しませんといけませんが、やはり広報広聴課の中にもそういうシステムがありますので。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"個人情報保護の部分では大丈夫だというふうなことで、区のほうは推進するという立場だということなんですが、今日の朝日新聞でも、福島県の矢祭町というんでしょうか、離脱するというふうな記事が載っていましたし、また杉並なんかもずっと心配というふうなことを記して、それに対しての保護条例までつくるという、そういうふうな動きになっていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"本多副委員長","kind":"質問・要望","question":"それと、今後の活動については、２３区共通の要望事項を国と都あてに作成をしていくということなんですが、作成の手順としては、９月、１０月で国、都への要望をつくりまして、１１月に提出という予定になっております。それで、この辺の要望事項については、また品川区の区民委員会としてもそういった意見を出し合っていただきたいと思います。品川の場合はこれは第３定例会にぶつかっているんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問","question":"徳島なんですけれども、徳島に行きますよね。徳島市。私は、ちょっと区民委員会に合うかどうかわからないけれども、あそこでうだつの上がる町なんて、よく。よくうだつって言いますよね。昔の町並みで。あれを区民委員会に合うかわからないけれども、あれは防災なんだよね。できたら、そこで調査を。防災関係で。そんなもんですかね。ある意味では、徳島ね。テレビなんかでもやるから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この出していただいて、ちょっと高松が苦しいかなと思って見ていたんですけれども、斎場公園というのは、結局中の施設まで見せてもらうような形なのか、それとも外観なのか。そこら辺はどういう組み合わせなのか。まだこれからの詰めだと思うんですけれども、ちょっと。だから、当然中に入っていて、ここまで行って、中に入ってくるかなということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"三上委員","kind":"質問","question":"特別どうのと今あるわけではありませんので、最終的に次回決めるということですから、それまで特別今ここに上がっている中にどうしても加えてもらいたいというようなことがあれば、それは委員長のほうに申し出ていただくということでいいんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"三上委員","kind":"質問","question":"状況によっては、現地をよく見させてもらうという考え方のもとでの一つの方向性というようなものを考えていただければいいんじゃないかと思います。ただお話だけ伺うということがあるんじゃなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一昨年のときに、少し踏まえたかもしれないけれども、岡山のときに商店街のおかみさんたちが来ていて、その場で意見交換みたいなのをしたのが、桜井委員などが。あれなんかも本当に行った委員の方も結構参考になった。聞いたということで。岡山は商店街３カ所ぐらい回ったんですけれども、２カ所で向こうの方と説明してもらっているんです。ですから、市役所の方じゃなかったんです。参考になったとかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"視察というのはね。うちは戸越銀座の銀六ですから、実際に年中来るんですよ。戸越銀座の物産をつくったりしているから。バスを連ねてね。何か見ていると、これが視察かなと思う。我々が行くのも本当によくしなくちゃなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"意見","question":"福岡の都市を一昨年でしたか、インターネットでちょっと調べたりしていましたので、だから実際にただインターネットで調べて行ったのと現場を見たというのは大分違う状況。その中で向こうで話を聞くということをやっぱりペーパーベースだけではなくて。見るというような形をぜひ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/365953?Template=document&Id=2336#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":24405,"voices":106}},{"id":"h14-20020723-7","meetingId":"h14-cm07","date":"2002年7月23日","dateIso":"2002-07-23","committee":"厚生委員会","time":"午後１時０８分～午後３時１９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","topics":[{"id":"topic-01","title":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","agenda":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"委員会が新しい構成になってから今回初めてなので、前回とちょっとダブるかもしれないんですけれども、聞かせていただきたいんですが、先ほど課長のほうから、大気汚染患者、公害健康被害補償法と、都条例のほうとの関係で若干ご説明があったんですが、この間の動きをもうちょっと詳しく教えていただければと思います。","respondent":"田中健康課長","answer":"それが４年前の数字ですと１,２８３人、本年度１,３８０人というところまで、数字的には推移しております。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"公害健康被害補償法は新たな認定をしないということだから当然減ってくるんだけれども、全体として大気汚染による患者の増えたり、減ったり、この動きというのがどういうふうになっているかというのが、都条例の制度との関係で見えるのかなというふうに思っているので、そこのところを聞いているんです。","respondent":"田中健康課長","answer":"これ自体、私どもも認定審査会等の中で、審査の先生たちのお話を伺っておりますと、あるいは審査の傾向を見ておりますと、発症時が３歳とか４歳ということになりますので、５歳から９歳がそういう形での医療費の公費助成を受けているというふうに考えられるかと思います。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"都の制度は１８歳未満なものですから、子どものところが集中するというか、数的にはそういうふうになるのは当然だと思うんです。今ご説明があった年度との関係で、公害健康被害補償法のほうは患者数がどういうふうに変わっているかというのは分かりますか。","respondent":"田中健康課長","answer":"認定の方の推移ですが、平成１０年度末で１,３２８名、平成１１年度末で１,３０２名、平成１２年度末で１,１６６名、平成１３年度末で１,１２６名という数字です。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"私が想像するには、死亡されて減ってきているのかなというふうに思うんですけれども、減っている原因はそういうところかどうかという認識が何かあれば聞かせていただければと思います。先ほど二酸化硫黄と言いましたから、ＳＯ２だと思うんですけれども、浮遊粒子状物質の測定の結果が出ているのではないのかなと思うんですけれども、そこら辺のところが分かりましたら、お願いしたいと思います。","respondent":"田中健康課長","answer":"基準値はというところで、今日も問い合わせをしたんですが、若干超えているというふうな環境課のほうの話でございました。ここのところの推移を表でいただいておりますが、平成３年からの１０年間の統計で見ますと、ほぼ横ばいという形というふうに聞いてあります。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"定点のほうは基準の中ということですけれども、自動車排出ガス測定局のほうが基準を超えていると。先ほど基準を若干超えているというふうなご説明だったんですけれども、ここら辺はどういうふうな認識を持っておられるのか。","respondent":"田中健康課長","answer":"申し訳ありませんが、大気汚染そのものの数値等につきましては環境課のほうが所管していますので、これに関連するデータということで聞いてまいって、資料等も用意してきましたので、認識という点では、先ほど申し上げましたとおり、担当課長からも。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"質問を変えまして、大気汚染と被害の、いわゆる公害病といわれる関係ですけれども、大気汚染が原因だというのはもう定着している話だと思うんです。先ほど、今回の東京の大気汚染裁判が平成１４年１０月に判決が出るということになっておりますけれども、一つお伺いしたいのは、大気汚染と、この病気との関係を行政のほうはどういうふうな認識を持っておられるのか。","respondent":"田中健康課長","answer":"それの対策につきまして、特別区長会のほうでも国・都への要望をということで進めてあります。そういう意味では、大気汚染に基づく公害について、行政側としましては、対策をきちっと講じてほしいという旨の国・都への要望は上げているところです。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"今のは区のほうの認識ですよね。国・都、いわゆる行政側のところはどういうふうなところかというのが分かったらお願いいたします。","respondent":"田中健康課長","answer":"そういう意味では、東京都としても国への要望とは別に、都自体でディーゼル車に対する規制について努力をし、公害対策に取り組んでいるというふうに私どもとしては受け止めてあります。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"一昨々年だったか、ディーゼル車の規制を石原都知事が打ち出して、僕らも歓迎したんですけれども、そのときは尼崎とか、幾つかの判決を受けて、それに対して、今度は東京でも裁判があるんだけれども、どうだという質問に対して答えたのが最初だったかなというふうに思うんです。この間の名古屋南部等、司法の判断の流れがどういうふうな感じできているのかというのは、どんなご認識でしょうか。","respondent":"田中健康課長","answer":"大気汚染と健康被害等の関係ですけれども、そういう意味で、大気汚染の状況下と因果関係自体がどのような関係にいるかというのはなかなか難しいところでございまして、昭和６１年の中央公害対策審議会の答申というのがございまして。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"意見","question":"一つここが対決点だと思うんです。ところが、気管支喘息との因果関係がその時点でははっきりしないということでそういう結論になったんですけれども、その後の研究成果といいますか、そのところはどういうふうに捉えておりますか。それは随分昔の認識だというふうに私は思うんですけれども、その後の医学的な研究等が当然あったかと思うんですけれども、そこら辺はどういうふうに認識されておりますか。","respondent":"田中健康課長","answer":"医学的にという意味での問題かと思いますけれども、中央公害対策審議会の答申を覆すところまでの科学的な結論というのは、今のところ、国も、私どものほうとしても認識していないというのが一つの問題かと思います。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私が言ったのは、住民と国との矛盾だけでなくて、国の政治と、東京都および品川区も含めた、そういうところとの矛盾もあるんだというふうに思うんですけれども、そこら辺のところはどうですか。","respondent":"田中健康課長","answer":"国の答申の関係を含めて申し上げますと、先ほどご紹介申し上げました特別区長会、あるいは東京都のほうの対策というのは、自動車公害等についての対策でございまして、これについて健康被害と結びつけて、国の先ほどの答申の結果を覆すようなところまでの論理構成。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"もっと聞きたいのもあるんですけれども、意見で、扱いも含めたのでよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"金高委員","kind":"質問","question":"東京都のほうで、これは「一昨年」となっておりますから、この請願が出たのが平成１３年ですから、実際には平成１２年だろうと思いますけれども、都は一貫して大気汚染の原因は責任を明確にした上でということになっておりますけれども、その後に、「総合的な見直しを検討してまいります」という答弁があったと、都のほうで言っておりますけれども。","respondent":"田中健康課長","answer":"例えばトラック、バス等のディーゼル車の浮遊粒子状物質の排出基準を満たさない車は、平成１５年１０月からは都内運行禁止、自動車の環境管理計画書を作成、提出を義務付け、これは３０台以上を有する事業者については、こういうことで規制を達するように。","id":"exchange-012"},{"speaker":"金高委員","kind":"質問・要望","question":"それと、総合的な見直しということで、確かに石原都知事が平成１５年から、すでに発表しているとおりの形だということでありますので、この問題点は、後で意見表明という形になると思いますけれども、請願の趣旨と、この中に出てくるそれぞれの説明のほうにおいても、救済措置を求めるというふうになっておりますけれども、今までの話を聞きまして、私も今回初めての厚生委員会ですので、内容的には。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"紹介議員に宮崎委員が入っていらっしゃるので、ちょっとお聞かせ願いたいんですが、１番目の、請願の要旨で、自動車メーカー、燃料メーカー等の財源負担というのはどのぐらいになるか、先ほどいろいろな患者の数値を聞いていらっしゃったんだけれども、紹介議員になられたからには、その辺をカウントされて紹介議員になったんだろうと思うので、どのくらいの費用負担になるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"私への質問ですが、私自身、今後財源がどういうふうになるかというところは試算しておりませんけれども、今までの公害健康被害補償法がこの考え方に基づいてやられてきておりますから、それに戻すという考えです。もう一つの、自動車メーカーと燃料メーカーというところの、燃料メーカーのほうも同じ責任があるかどうかということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問","question":"ですから、患者の数も分かってきているはずですよね。ここに出されてきているんだから。そうすると自動車メーカー、燃料メーカーに対してどのくらいの数字を補償しなさいということを言ってきているですか。２番目についても、新たにというような認定された場合には、今度はどうなんでしょうか。そうした場合でも同じような趣旨になってくるんですかという、３点の質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど言ったように、試算のほうはやられておりません。考え方のところですけれども、今後新たな技術的な開発が進むということになれば、また考え方は当然出てくると思います。一方で、そういうある技術を使っていればもっと防げたはずだと。最新の技術を患者救済のために使っていくかどうか、そういうところの姿勢なども今後の考え方に反映してくるというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"辻副委員長","kind":"確認","question":"私も初めてこの委員会に出たので、その都度報道はされていたんでしょうけれども、もう一回確認の意味で。尼崎公害と名古屋南部の公害の判決ですが、訴訟そのものというのは、どういう訴訟だったんでしょうか。画期的な判断ということですけれども、「公害差し止めを命ずる」というのはどういう内容か教えていただけますか。","respondent":"田中健康課長","answer":"尼崎公害訴訟につきましては、沿道汚染と、その発症、ですから、先ほど申し上げました、５０ｍ以内という局所的にという前提が付きますが、発症等につきましては、因果関係が認められるので、大気汚染物質の排出による損害賠償の責任を負うという判断が出たです。","id":"exchange-018"},{"speaker":"辻副委員長","kind":"質問・要望","question":"道路沿いの５０ｍの範囲で起こった問題についてということで限定された話ですね。だから、財源を求めてやれということなんでしょうが、これは法的にこういう形で自治体ができるのか。この辺の問題が１番目で、２つ目は、国に対してという話ですけれども、まず１番目の財源負担ということについて、都とか、自治体にこういう形というのは可能なのかどうか。","respondent":"田中健康課長","answer":"こちらで、今の認定患者につきましては補償等を行っているです。東京都のほうにつきましては、医療費助成の関係ですので、東京都はいろいろ難病等につきましても医療費助成をしておりますが、それと同じような中身で都単独の考え方で行っているです。","id":"exchange-019"},{"speaker":"辻副委員長","kind":"質問・要望","question":"今回の新しい１番目に対して、自動車メーカーと燃料メーカー、先ほど言ったように、金額がどのぐらいかわからないわけだけど、例えば東京都が新たに都独自で大気汚染被害の制度というものをつくったときに、その原資というものを燃料メーカー、自動車メーカーに求めることはできるのかどうか。それがないと、１番目の前提が崩れてしまうんですが、そういうものが可能なのかどうかということです。","respondent":"田中健康課長","answer":"ただ、公害健康被害補償法にありますとおり、こういうところにはもともと見解の相違があるわけでございまして、そういう点で国のほうとしましては、この法律をつくった時点ではそういうところに出資を義務付けて、それで法制度をつくったですので、東京都段階でこの辺の判断を。","id":"exchange-020"},{"speaker":"辻副委員長","kind":"質問・要望","question":"２つ目のほうで、この問題で、現状としての段階でどういう動きがあるのか確認しておきたいんです。そう考えていいんでしょうか。今まではＳＯ２を出しているところに求めましたね。そのときに、今言ったように、国のほうはＮＯ２とか、ＳＰＭの汚染指標として再指定するとかという動き、考え方というのは、現状の段階ではどこまで話になっているんでしょうか。","respondent":"田中健康課長","answer":"そういう意味では、現状、環境省のほうもこの原則でおるというふうに、私どもとしましても聞いておりまして、ここにつきましては、この二つの汚染指標が急激に増えているような状況では別かもしれませんが、横ばいという中では、こういう当時の判断の客観情勢につきましては。","id":"exchange-021"},{"speaker":"辻副委員長","kind":"質問","question":"今回、東京裁判が結審したといいますが、この争点になったのは、先ほど言った尼崎とか名古屋南部と同じですか。部分的な問題のことをもうちょっと。要するに、自動車は１００％悪であって、使わなければ、なくなるということに対しては、使わざるを得ない、ドライバーの責任については全く論議を抜きにして話というのはされてきているのか。その辺、２点お願いします。","respondent":"田中健康課長","answer":"そういう意味では、先ほど副委員長からご指摘がありましたドライバー等については、被告というふうには訴訟としてはしていないようです。","id":"exchange-022"},{"speaker":"辻副委員長","kind":"質問・要望","question":"私は、今回の請願については非常に難しい部分があるなというのは、ただ単にメーカーに求めてはどうだということではなくて、一つは、大きい意味での、そういう対抗線をどうするかという生き方の問題、生活のあり方の問題というのを考えていかなければ解決できない問題、これだけ車社会の中にあっての問題。そういう面では、この扱いについては、国の制度として大きく被害の補償というものを求めていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これはぜひ今日結論を出していただきたいと思います。私のほうは、紹介議員になっていることもあるんですけれども、採択をお願いしたいというふうに思います。その原因が変わってきている。そういう点では、ほかの議会のところでは継続あるいは不採択のところもあるようですけれども、ぜひ品川区議会では採択していただければというふうに思って、この点は私からも皆さんにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"金高委員","kind":"質問","question":"結審が終わったのは昨年１２月１８日という説明でありましたし、１０月２９日に判決が出るということですから、それを踏まえて、また審査をしてもいいのではないかという気がいたしますので、継続できればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"私も、裁判の結果が出てからということでも結構ですし、今日、決をとっていただいても、先ほどちょっと質問をしたところのように、数字的にも出ていない、いろいろな問題点があるところをとり切れないというような思いがあります。結果は、責任問題というのは、東京の判決で出てくるだろうけれども、内容的には疑問視するところがあると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"今の皆さんのご意見だと継続ということなので、継続になろうかと思うんですけれども、私としては、これはずっと継続で長くきているということもあって、今日あたりは判断を出してあげたいというふうに思っております。あえて言いたいと思います。継続が多数のようですから、それはしようがないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"３点お尋ねします。４０歳および５０歳の対象人数は何人でしょうか。それと、この事業の予算はどのぐらいかかるんでしょうか。３点目に、なぜ４０歳および５０歳の方を対象にしたのか。３点お伺いします。","respondent":"田中健康課長","answer":"都のほうからも補助が出ますし、指導事業の部分は都の単独補助でございまして、３分の２ほど改善指導の補助を見込んです。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"何点か伺います。今、４０歳と５０歳は国の補助事業だと。今まで５歳刻みですよね。そうすると、４０歳と５０歳はこっちのほうになるということですか。","respondent":"田中健康課長","answer":"委員ご指摘のとおり、４０歳、５０歳の方についてはこちらで検診をしていただく。その後必要な方について指導事業。残りの５歳刻みの方については、従来の成人歯科検診という形になります。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"４０歳と５０歳というふうになっているんですけれども、４０歳と５０歳の場合では、通常、親知らずまで入れると３２本ですね。要するに、普通、歯周疾患になるというのは、３０歳台、あるいは２０歳台からというふうにいわれているんですけれども、どうせやるんだったら、もっと若いうちからやったらというふうに思うんですけれども、そこら辺のところが分かったら、教えていただければと思います。","respondent":"田中健康課長","answer":"ただ、国のほうが４０歳、５０歳に合わせて、生活習慣病の一環ということで、本年１月からスタートしております医のほうの糖尿病、高血圧等の生活改善指導事業という形と合わせまして、生活習慣の予防のためにということでこういう事業を組んで補助対象にしておるところから。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"もう一つ、細かいことで聞きたいんですけれども、４のところの改善指導が1)、2)、3)となっていて、４カ月後の検診で一フロー終わるということになろうかと思うんですけれども、医療機関に対する費用の支払いというのは、３回目ですか、それとも１回ごとですか。","respondent":"田中健康課長","answer":"検診ならびに１回、２回、３回それぞれです。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"それぞれで支払いをするということですと、実施時期との関係で何か関係があるのかなと思ったんですけれども、改善指導を希望する者の検診、１１月３０日まで。これが今年度で４カ月のところということになるから１１月３０日までということですね。１回１回やるんだったら、特にこれで１１月３０日とか決めなくてもいいんじゃないかという気がするんですけれども、どうなんでしょうか。","respondent":"田中健康課長","answer":"先ほど意向調査ということで、本人にご希望を確認いただくということがありますが、これ自体は東京都の制度も含めまして、３回を受けていただくということが基礎条件になります。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"意見","question":"例えば医療機関との関係での支払いが、１回、２回、３回とその都度やられるんだったら、受診者は３回受けてくださいよということでやればいいだけの話であって、１１月３０日になろうが、例えば年が明けて１月になろうが、４カ月後に３回目の指導を受けるということが守られていけば、１１月３０日というのがどんな意味があるんだろうと思ったんです。","respondent":"田中健康課長","answer":"ですから、１２月になりますと、翌年の４月に改善指導の３回目というふうになってしまいますので、これは契約期間とは違ってきますし、先ほど申し上げました、診療報酬等の単価の問題も生じますので、このような形にするという内容です。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっとかみ合わないんですけれども、私は、３月３１日までに一クール終わらせてくれという、その事情がよくわからないんです。診療報酬との関係であれば、これはこれで診療報酬も参考にするけれども、費用は別に契約するわけですよね。","respondent":"田中健康課長","answer":"もう１点は、東京都のほうもこの３回を年度内にして、補助金としての体制について事務的にもそういうふうにきてございまして、そういう内容としての事業というふうに組んです。","id":"exchange-034"},{"speaker":"築舘委員","kind":"質問・要望","question":"私も５０歳なものですから、これを受ける資格はあると思うんです。先ほど９,２００人いらっしゃるということで、そのうち３２０人程度だというのが最初から分かるんですか。その辺をお聞かせいただきたいと思います。","respondent":"田中健康課長","answer":"ただ、今回期待しておりますのは、４０歳、５０歳の、今年度に限りということでご通知申し上げますので、昨年来そういう通知を申し上げておりますので、若干ずつ受診率が上がっておるので、期待はしています。","id":"exchange-035"},{"speaker":"築舘委員","kind":"意見","question":"「要指導」に私は確実になると思うんですけれども、その場合に、ある程度指導をしてもらうと治るのかどうかという、要するに、私は歯ぐきから血が出たりしていまして、かなり悪い状況じゃないかと思いますけれども、何か改善指導をすると、よくなってくるという、こういう実績というか、そういうのはありますか。","respondent":"田中健康課長","answer":"結果として、うまくいけば、治療に結びつかないで、予防の段階で食い止められるというのが最大の目的でございまして、例えば私も今回説明会の席上でびっくりしたんですが、１日１回１０分間磨くという、それをすることで随分効果が違うそうです。","id":"exchange-036"},{"speaker":"築舘委員","kind":"質問・要望","question":"歯石などを取る場合は、地元の歯医者のほうにお金を払って、その後やってもらうということですね。歯の磨き方というのは、１０分間というようなことですので、なかなかそれができないなという部分がありますけれども、そういう生活習慣をしっかりとつければ予防という形でうまくいくということだと思うんです。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"１点だけお伺いしたいんですが、実施場所ですけれども、検診した場所と、指導を受ける歯医者が何で同じにならないといけなかったのか、理由なり根拠があれば教えていただけますか。","respondent":"田中健康課長","answer":"１回目の指導が、検診の結果をお知らせいただくその回というふうに考えてあります。","id":"exchange-038"}]},{"id":"topic-02","title":"部長にお残りいただいて、議題としてまいりたいと思いますので、後ほどにさせていただきまして、次の、その他のほうに移らせていただきます。 その他の１番","agenda":"部長にお残りいただいて、議題としてまいりたいと思いますので、後ほどにさせていただきまして、次の、その他のほうに移らせていただきます。 その他の１番","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"きのうこの資料を見て、全部見たわけではないんですけれども、ちょっと気になったのは、先ほど原則として５年間に同一の回答を繰り返されている項目、これはいつも委員長会のときにも話題になるんですよね。ですから、ここのところは委員長にお願いですけれども、委員長会のところではここのところを引き続いて要望をしていただくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"須藤委員","kind":"意見","question":"先ほどお話があったように、８月１４日までにということなので、今宮崎委員の言うように、非常に大切なところもいろいろあるので、ここの委員会で今精査していくというのは大変だと思うので、正副委員長にお任せして、調整をしていただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]},{"id":"topic-03","title":"先ほど先送りをさせていただきました３番、行政視察","agenda":"先ほど先送りをさせていただきました３番、行政視察","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"両方ともそれぞれというような、委員長の言葉なので、部長から、ここはこうだよとかというようなご意見をいただければ、我々も決めやすいと思うので、いかがでしょうか。","respondent":"小沼福祉事業部長","answer":"必ずしも障害が重度の方だけでなくて、重度の方と軽度の方、中軽度の方と混在する形で、ですから、軽度の方について、工場ですから、正規の従業員として雇用し、重度の方については、これはあまり適切な言葉でないんですが、実習参加というようなことで、正規の方ですと。","id":"exchange-041"},{"speaker":"山路委員","kind":"質問","question":"例えば北海道の場合で、北海道の旭川の健康プラザを調べたいという場合は、理事者は２人になるんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"辻副委員長","kind":"意見","question":"よかったというか、もう一回行きたいなというのは、身体障害者でＩＴを使ってコンピュータの仕事をやっているんです。コンピュータでインターネットを使って、あの当時でも進んでいたんですけれども、今はどういう状況になっているか。授産施設の中の内容が、ＩＴでソフトをつくったり、グラフィックをやったりしています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"須藤委員","kind":"提案","question":"推薦されていない会派の方がいらっしゃると思うんです。それはピシッと厚生委員会としての姿勢を見せていかないといけないと思うので、私どもは一つ提案をさせていただきました。ほかの方も一つ提案されたと思うので、提案されていない方がいらっしゃったら、提案をしていだいて、考え方を出していただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"提案","question":"私もいろいろ考えたんですけれども、ここというところが提案できなかったんですけれども、実際に自民党、公明党の二つの案はかなり似ているというか、障害者福祉のところ、どっちも見てみたいという感じですから、どういうふうに決めたらいいのかというのはよくわからないんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"金高委員","kind":"意見","question":"前に公明党のほうから岩見沢市のことを聞いたことがありますし、今部長のお話のとおり、知的障害者の方のそういったところも近くにあるのであれば、身障者の方と知的障害者の方の福祉センターということがドッキングできるのであれば、北海道のほうでもいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"須藤委員","kind":"提案","question":"ですから、今日の委員会で、今それぞれ内容的に了とするならば、あとは正副委員長で精査をしていただいて、その後の関連の地域へ行けるということの考え方も整理をしていただいて、正副委員長にお願いをして、委員会としてそれをピシッとみんなで提案してきたんだという形をとっていただければいいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270319?Template=document&Id=3026#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":31706,"voices":122}},{"id":"h14-20020723-8","meetingId":"h14-cm07","date":"2002年7月23日","dateIso":"2002-07-23","committee":"建設委員会","time":"午後１時０９分～午後４時２０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"ＩＣカードが導入されて、ＪＲのＳｕｉｃａですけれども、今見てきた駅の券売機のところではパスネットが発売されていて、今はパスネットの利用が主力なんですけれども、全線開通された後には、ＪＲのＩＣカードのＳｕｉｃａでも乗れるし、パスネットでも乗れるという状況になるんですか。","respondent":"伊佐都市計画課長","answer":"例えばＩＣカードの利用についても、具体的なＪＲの条件等を聞いてございませんが、基本的には、両方使える形にしたいものと考えております。パスネットも使えるように、どちらか一方が使えなくなるということではないようにしていきたいと考えております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"意見","question":"今のご説明の中で、東京都、品川区、目黒区および東京急行電鉄(株)の四事業者間において、代替施設の見直しについて合意がされたので、という説明がありましたけれども、前回、請願のときに示唆された代替案がありますよね、それから、今回、お示しされた案に至るまでの経緯を、ちょっと時系列的に、いつどういう話があったのでこういう新しい案が示されたのか、お知らせいただければと思います。","respondent":"中島街路事業担当課長","answer":"内部の担当者レベルでは、エレベーター設置の必要性というのはずっと昔から思っていまして、たまたま議会レベルで話題にはなったんですけれども、具体的に一番直近で言いますと、今年５月に連立事業の協議会がございまして、その中で。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"この方たちの声ってどこまで届いているのかなというのを、まず１点、お伺いしたい。住民の方々が、平成１３年の段階で、既にエレベーターについて検討はどうかという投げかけをしてる。さっき、どこまで声が届いているのかと言いましたけれども、その点に関して、住民の方々との位置づけと、７年も話し合われているこの問題の認識について、改めてお伺いしたいと思います。","respondent":"中島街路事業担当課長","answer":"１点目の、反対側の方との話し合いですけれども、私ども、目黒区の説明会等に毎回、参加をしています。私が行かない折には係長が出たりですけれども、その内容につきましては、当然、部長に報告をしています。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"そもそも、７年間も話が続いているという最初のスタートの時点のことを、ちゃんと区が認識していらっしゃるのかということを、もう１回お伺いしたい。閉鎖をされる架道橋の周囲の方が、それをきちんと理解できない状態で話が進んでいる、伝えきれていなかったという、ここのところの認識を、品川区も都と同じように持っていらっしゃるのかどうか、その辺を伺いたいと思います。","respondent":"中島街路事業担当課長","answer":"１点目の、苦渋の選択というお話ですけれども、東京都といたしましても、こちらの連立事業に伴いまして、洗足架道橋、ガード下の道路が閉鎖されてしまうことにつきましては、確かに、苦渋の選択という表現もしていますし、そういう認識を持っているものと考えています。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺が十分だと言える根拠って一体何なのかなと思うのと、一部の方の理解を得ていない、大部分の方は理解をしてくれているということですが、大部分というその辺のとらえ方の根拠というのは一体何なんでしょうか。それを示していただきたい。そこに住んでいらっしゃる住民の方々の安全というところをとらえた場合に、どうなんでしょうか。その辺のご意見を聞かせていただければと思います。","respondent":"中島街路事業担当課長","answer":"それについて、より充実した内容の、より安全性の高いものということで、現在、事業者として検討してきて、ここまでのものができていると認識しています。ここが閉鎖されることがなければというれば論では、ちょっと論議できないものがあると考えています。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住民の方々の話を四事業者がすごく尊重して、反対する方々の話し合いを７年間続けていて、５月に話し合いをして、次は夏ということで、さっきも課長から説明がありまして、また行われるわけです。前回の議事録を見たら、部長は、関係機関に働きかけをして協議をするという答弁をされているので、その辺、一つは危険性への認識と、関係機関への検討内容とか、到達点を教えていただきたいと思います。","respondent":"中島街路事業担当課長","answer":"ですから、今後また要請等があれば、引き続き話し合いをしていくと思いますので、例えば８月、９月になって、話をしてくださいというようなことは、東京都は言ってございませんので、引き続き話し合いが行われるものと認識しています。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この点は要望で終わります。代替道路なんですが、警察が最終的に判断をするということですけれども、区のほうから、その辺はきちんと、この間の経緯とか、住民要望を伝えていただけるのでしょうか。もう１点、どうしても引っかかるのは、付替道路は代替案の一つですよね。だから、この道路がないと代替案は成立しないのかどうか、その点を確認しておきます。","respondent":"中島街路事業担当課長","answer":"そういう形で供用しないということになりますと、もともと閉鎖に伴って、歩道橋をつけて、これを代替道路とするということで事業認可を取ってありますので、そういった部分では、洗足架道橋の閉鎖に伴いまして、不可欠な道路と考えています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"最後に、不可欠な道路ということですけれども、今回、お示しの新しいエレベーターがついた段階で、前よりもより一層あそこのスペースが狭くなって、危険になっていますよね。付替道路のスロープと、こちら側の階段と、エレベーターが鉢合わせする状況で、ここは何ｍぐらいあるんですか。今の不可欠な道路と言われて、私はとても心配で、このまま収められないという思いなんです。","respondent":"中島街路事業担当課長","answer":"同じようなことが、こちらのほうにも言えるんですけれども、この絵でいきますと、激突するような絵になっていますけれども、そういったことがないように、全体をもう少し曲げて、エレベーターにぶつからないような形でおりて来るということは、安全対策も含めて、今。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後です。私は、どんな対策を立てても、あそこのスペースでは、車がおりてきたら、車対車ならまだわかりますけれども、人間の生命が保証されるとはとても思えないので、ぜひ、前回の議会の論議と、地域の方々からほんとうに危険だという声がいっぱい上がっていますから、尊重して、受けとめていただきたいなと思って、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"ちょっとお聞きしておきたいんですけれども、さっき、エレベーター１基が５,０００万円という話でしたね。２基ついて１億円ですか、当然、橋桁を通る形でしょうから、全体の工事費というのはもっと大きなものになるんだと思います。エレベーターのところも含めて、歩道橋をつくったり、スロープとか代替道路、これらの何点かすべての代替案は、総事業費としては、幾らぐらいかかるものなんですか。","respondent":"中島街路事業担当課長","answer":"そのほかの、例えば、歩道スロープ、取付スロープは、今、概算の詳細は出てないんですけれども、数年前、こちらのエレベーターをつける前の段階で、約３億円前後と言われていますので、今度、エレベーターを設置したことによって。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"４億円から５億円ぐらいということで、総事業費が８００億円で、今回のだけを取ってみても、代替案の事業費として、新たに１億４,０００万円ぐらいがかかってくるわけですよね。これだけの予備費みたいなものがあるのかどうかというのがわからないんですけれども、その辺をちょっと教えていただけますか。","respondent":"中島街路事業担当課長","answer":"あくまでもこれは概算ですので、これにつきまして、実際に、エレベーター設置することついて１億５,０００万円かかってしまって、これが８１６億５,０００万円になるのか、あるいは、それ以内で収まるのかというのは、今の段階では何とも言えないところです。","id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"今までのエレベーターがつく前の代替施設ですと、年間の維持管理費はそんなに膨大なものにはならないのかもしれませんけれども、エレベーターがついちゃうと、２４時間の防犯体制とかといって相当なものになっていくと思うんですけれども、これによって、これからの管理上の問題で、実際に区が年間に支出しなければならないものが出てくるのかどうか。","respondent":"中島街路事業担当課長","answer":"こちらにつきましては、先般申しましたように、目黒区が管理するということになってありますので、管理費につきましては、目黒区のほうで支出するという形になるです。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"今、飯沼委員がいろいろ、住民との話の中の問題で質問しましたけれども、この間、エレベーターの問題を特にやったから、線形の問題をお聞きしたいんですけれども、ちょっと幾つか聞いてみたら、大江戸線なんかは１０００分の５０とか、神戸電鉄(株)では、通常の車両で１０００分の４５とかいうのがあるみたいです。","respondent":"中島街路事業担当課長","answer":"今、委員の言われたいわゆるリニア方式といいますか、磁気で推進させるというお話ですけれども、そういった方式の列車につきましては、鉄道構造規則で１０００分の６０以内となっています。ただ、それはもちろん構造が違うわけで、そういうことが可能になるわけです。","id":"exchange-013"},{"speaker":"菊地委員","kind":"確認","question":"前回、課長が言われていた特認事項の話がありましたけれども、あれにしても、特認事項でそういう路線をつくってしまえば、あとは鉄道ですから、５年、１０年でまさか路線を変えるわけではないでしょうから、何十年間かの安全性は十分に保証されるということで、そういう特認事項が設けられているんだと思うんです。ちょっとその辺のことを。","respondent":"中島街路事業担当課長","answer":"東京急行電鉄(株)といたしましては、それ以上きつくするということは、再々申し上げてありますけれども、安全運行上問題が出てくるというようなことで、東京急行電鉄(株)としては絶対に１０００分の３５を超える勾配で鉄道を運行するという考えはないです。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"ということは、１０００分の３５を超えるものというのは、安全上問題があるということなんですか。","respondent":"中島街路事業担当課長","answer":"ですから、今の神戸電鉄(株)がどういう地形の中で、どういう形で、どのぐらいの距離でもってというのはわかりませんけれども、少なくとも、鉄道事業者の責任として、東京急行電鉄(株)は１０００分の３５を超える勾配では運行しないというのが東京急行電鉄(株)側の考えです。","id":"exchange-015"},{"speaker":"林（和）副委員長","kind":"質問","question":"一応、２案を正副委員長で考えたわけですけれども、このうちで理事者のほうでどうなんですかね。行くとすれば、どっちかに決めなきゃいけないと思うんですけれども、そちらの考えはどうですか。","respondent":"中谷まちづくり事業部長","answer":"私も、今回、正式には初めて目を通させていただきましたので、ちょっと今すぐにはなかなか言いにくいんですが。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"前回、いただいた資料で、過去数年間、各委員会が行ったところは、建設委員会だと、北側が少なかったので、じゃあ北のほうはどうですかなんて、そんな簡単なことで、前回、申し上げたかなと思うんですけれども、委員会として行くならば、いつも同じ方面に行くよりは、違った方面で、違ったところを違った視点から見るのもいいのかなという気がしたということで申し上げたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"林（和）副委員長","kind":"意見","question":"さっきの話だと、次の回までにというようなことだったら、では、資料を一応持ち帰って、よく検討して、次のときに結論を出せばいいかなと思ったんだけれども、今、それじゃあおそいということですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"私のほうとしては、前回の委員会のときに、田中委員から北海道はどうだという話があって、非常に大切にしていたことで、今、船波委員が言われたように、私にも魅力のある調査項目があるんですけれども、緑化との関係で言うと、温暖化をどう進めていくのかというのが、まず大きな課題なのかなという気がしますので、そうなると、やっぱり大阪方面のほうが、今としては大切なのかなという気がします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"本間委員","kind":"質問","question":"しかし、この中にもちろんあるわけでして、そういう意味から言いますと、事務局が一生懸命調べていただいた部分の中から、そういう視点から、問題意識として拾い上げていくという形にしなくちゃならない。そういう部分をちょっと探し出して、やっていただければ、わかりやすいんじゃないですか。ただ、緑化対策だけではちょっと、選びの違いというか、選びにくいですね。","respondent":"北野委員長","answer":"前回は、緑化ということも多かったということで、緑化中心になってしまったんですけれども、まちづくりということでは、こちらのほうで検討させていただいたんです。田中委員は北海道を提案されたから、北海道ですね。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"ちょっと１点だけ、理事者にお伺いしたいんですが、札幌はそうなんですが、大阪府と神戸市は政令指定都市になっていまして、直接品川区との比較というのは、権限のあれで、そういう意味ではちょっと難しいのか。こういった緑に関係するまちづくりという観点で、政令指定都市だからこそできること、また、品川区ではそこまではちょっとできないようなことってあるのでしょうか。","respondent":"中谷まちづくり事業部長","answer":"東京２３区の場合は、２３区が東京都市計画という一つの都市計画になっていますが、大きな都市計画の考え方に基づいて、各区の考え方は各区でまとめるというような形にもなっていますから、そういう意味では、基本的に違ってこないです。","id":"exchange-021"},{"speaker":"田中委員","kind":"意見","question":"気候風土について、大きな問題としてベースに考えるのなら、確かにヒートアイランド現象が札幌市内にもあるとは思いますが、直接比較をするとなると関西なのかなと。旭川の説明にも、2)のところに、「除雪および雪囲いの対応を行って」という記述もあるように、環境面では、気温というか、そういう面からすると、適切な見方はできないのかなという思いも少し持ちました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"本間委員","kind":"意見","question":"私も言ったんですけれども、別にどちらこちらということじゃなくて、今までのを見ますと、今、田中委員の話がありましたように、品川区人口３２万人の地方自治体と比較的似通った財政規模の地方自治体が、一つぐらいはまっていたような感じがありますね、必ずしも一緒でなくてもいいわけですけれども。そういうことも選択肢の一つに加えられてはいかがかなと思います。これは意見ですけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"船波委員","kind":"質問","question":"緑化については、海外調査の調査項目の中にも入っているし、たくさんこれから調査もされるんじゃないかと思うので、あまり調査項目が緑化、環境ばかりにしてしまうよりも、品川区もこれから景観ガイドラインを作成するわけですから、そういったことを先取りして、何らかの調査をしたいと思うので、景観条例のある北海道。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"私も景観条例のところにすごくひかれるんです。気候、風土とか、いろいろ考えたら、全体としては関西のほうがいいなと思っているんで、景観条例に係わるようなところで、西のほうでどこかないですかね。たまたま函館ということで、ひかれてしまったんですが、もうちょっと広げて考えていただけないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"林（和）副委員長","kind":"質問","question":"じゃあ、岡山市のほうはどうなんですか、倉敷市とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"堺委員","kind":"質問","question":"そういうのはさっきね。１案でよろしいんじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"本間委員","kind":"意見","question":"別にそれにこだわっているわけじゃないけれども、前回、僕は三重県だとか、和歌山県だとか、鳥取県の自治体の市長が意欲的に取り組んでいるというお話をさせていただいた部分で、お調べになったところはないんですね。そこまでは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"本間委員","kind":"意見","question":"もちろんです。具体的な目標設定値を出して、各傘下の地方自治体にきちっと出す。結構、例えば四日市がどうだとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"本間委員","kind":"質問","question":"だから、その温暖化対策の中に必ず緑化とか、そういうことも出てくるわけですから。幾つかありますよ、例えば環境リサイクルの問題とか。だから、うちのつながりでいけば、もちろん、まちづくりの部分だとかにつながってくる部分は必ずあるはずですね。どこも意欲的なんだろうけれども、特に突出したものが見える部分とすると、僕が調べたところでは三重県。どこの地方自治体もやっているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"堺委員","kind":"質問","question":"せっかく前回の各委員の意見を集約した形で、１案、２案という形に絞り込んでいただいたわけですから、これをまたさらに新しくゼロからスタートするとなると、１からやり直しになってしまう。どっちかで、正副委員長に一任するか、ここで決めるか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"林（和）副委員長","kind":"質問","question":"でも、最初と最後と雰囲気が大分変わったような気がしたんですよね。最後になってくると、何か第１案のほうがいいなという雰囲気になってきた。どうですかね。私はどっちでもいいと思うんですけれども。船波委員が１人、北海道に固持されるから。この雰囲気を見ると、そのほかの方々は、どっちかと言えば、大阪のほうがいいんじゃないかという雰囲気に聞こえるんですよね。","respondent":"北野委員長","answer":"ここでは諮ることはできませんが、淡路島というところが、大きな公園ということで、品川区にそぐわないということであれば、また違う場所で、景観条例とか、そういうガイドラインを含めたところで、ちょっと検討させていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/923086?Template=document&Id=3730#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":24997,"voices":135}}]);
